-- KJV batch 2 (blocks 26-50 of 349)
-- Run this in Supabase Dashboard SQL Editor

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 28, 40, E'And for Aaron’s sons thou shalt make coats, and thou shalt make for them girdles, and bonnets shalt thou make for them, for glory and for beauty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 28, 41, E'And thou shalt put them upon Aaron thy brother, and his sons with him; and shalt anoint them, and consecrate them, and sanctify them, that they may minister unto me in the priest’s office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 28, 42, E'And thou shalt make them linen breeches to cover their nakedness; from the loins even unto the thighs they shall reach:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 28, 43, E'And they shall be upon Aaron, and upon his sons, when they come in unto the tabernacle of the congregation, or when they come near unto the altar to minister in the holy place; that they bear not iniquity, and die: it shall be a statute for ever unto him and his seed after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 1, E'And this is the thing that thou shalt do unto them to hallow them, to minister unto me in the priest’s office: Take one young bullock, and two rams without blemish,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 2, E'And unleavened bread, and cakes unleavened tempered with oil, and wafers unleavened anointed with oil: of wheaten flour shalt thou make them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 3, E'And thou shalt put them into one basket, and bring them in the basket, with the bullock and the two rams.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 4, E'And Aaron and his sons thou shalt bring unto the door of the tabernacle of the congregation, and shalt wash them with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 5, E'And thou shalt take the garments, and put upon Aaron the coat, and the robe of the ephod, and the ephod, and the breastplate, and gird him with the curious girdle of the ephod:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 6, E'And thou shalt put the mitre upon his head, and put the holy crown upon the mitre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 7, E'Then shalt thou take the anointing oil, and pour it upon his head, and anoint him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 8, E'And thou shalt bring his sons, and put coats upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 9, E'And thou shalt gird them with girdles, Aaron and his sons, and put the bonnets on them: and the priest’s office shall be theirs for a perpetual statute: and thou shalt consecrate Aaron and his sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 10, E'And thou shalt cause a bullock to be brought before the tabernacle of the congregation: and Aaron and his sons shall put their hands upon the head of the bullock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 11, E'And thou shalt kill the bullock before the LORD, by the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 12, E'And thou shalt take of the blood of the bullock, and put it upon the horns of the altar with thy finger, and pour all the blood beside the bottom of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 13, E'And thou shalt take all the fat that covereth the inwards, and the caul that is above the liver, and the two kidneys, and the fat that is upon them, and burn them upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 14, E'But the flesh of the bullock, and his skin, and his dung, shalt thou burn with fire without the camp: it is a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 15, E'Thou shalt also take one ram; and Aaron and his sons shall put their hands upon the head of the ram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 16, E'And thou shalt slay the ram, and thou shalt take his blood, and sprinkle it round about upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 17, E'And thou shalt cut the ram in pieces, and wash the inwards of him, and his legs, and put them unto his pieces, and unto his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 18, E'And thou shalt burn the whole ram upon the altar: it is a burnt offering unto the LORD: it is a sweet savour, an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 19, E'And thou shalt take the other ram; and Aaron and his sons shall put their hands upon the head of the ram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 20, E'Then shalt thou kill the ram, and take of his blood, and put it upon the tip of the right ear of Aaron, and upon the tip of the right ear of his sons, and upon the thumb of their right hand, and upon the great toe of their right foot, and sprinkle the blood upon the altar round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 21, E'And thou shalt take of the blood that is upon the altar, and of the anointing oil, and sprinkle it upon Aaron, and upon his garments, and upon his sons, and upon the garments of his sons with him: and he shall be hallowed, and his garments, and his sons, and his sons’ garments with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 22, E'Also thou shalt take of the ram the fat and the rump, and the fat that covereth the inwards, and the caul above the liver, and the two kidneys, and the fat that is upon them, and the right shoulder; for it is a ram of consecration:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 23, E'And one loaf of bread, and one cake of oiled bread, and one wafer out of the basket of the unleavened bread that is before the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 24, E'And thou shalt put all in the hands of Aaron, and in the hands of his sons; and shalt wave them for a wave offering before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 25, E'And thou shalt receive them of their hands, and burn them upon the altar for a burnt offering, for a sweet savour before the LORD: it is an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 26, E'And thou shalt take the breast of the ram of Aaron’s consecration, and wave it for a wave offering before the LORD: and it shall be thy part.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 27, E'And thou shalt sanctify the breast of the wave offering, and the shoulder of the heave offering, which is waved, and which is heaved up, of the ram of the consecration, even of that which is for Aaron, and of that which is for his sons:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 28, E'And it shall be Aaron’s and his sons’ by a statute for ever from the children of Israel: for it is an heave offering: and it shall be an heave offering from the children of Israel of the sacrifice of their peace offerings, even their heave offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 29, E'And the holy garments of Aaron shall be his sons’ after him, to be anointed therein, and to be consecrated in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 30, E'And that son that is priest in his stead shall put them on seven days, when he cometh into the tabernacle of the congregation to minister in the holy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 31, E'And thou shalt take the ram of the consecration, and seethe his flesh in the holy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 32, E'And Aaron and his sons shall eat the flesh of the ram, and the bread that is in the basket, by the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 33, E'And they shall eat those things wherewith the atonement was made, to consecrate and to sanctify them: but a stranger shall not eat thereof, because they are holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 34, E'And if ought of the flesh of the consecrations, or of the bread, remain unto the morning, then thou shalt burn the remainder with fire: it shall not be eaten, because it is holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 35, E'And thus shalt thou do unto Aaron, and to his sons, according to all things which I have commanded thee: seven days shalt thou consecrate them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 36, E'And thou shalt offer every day a bullock for a sin offering for atonement: and thou shalt cleanse the altar, when thou hast made an atonement for it, and thou shalt anoint it, to sanctify it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 37, E'Seven days thou shalt make an atonement for the altar, and sanctify it; and it shall be an altar most holy: whatsoever toucheth the altar shall be holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 38, E'Now this is that which thou shalt offer upon the altar; two lambs of the first year day by day continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 39, E'The one lamb thou shalt offer in the morning; and the other lamb thou shalt offer at even:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 40, E'And with the one lamb a tenth deal of flour mingled with the fourth part of an hin of beaten oil; and the fourth part of an hin of wine for a drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 41, E'And the other lamb thou shalt offer at even, and shalt do thereto according to the meat offering of the morning, and according to the drink offering thereof, for a sweet savour, an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 42, E'This shall be a continual burnt offering throughout your generations at the door of the tabernacle of the congregation before the LORD: where I will meet you, to speak there unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 43, E'And there I will meet with the children of Israel, and the tabernacle shall be sanctified by my glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 44, E'And I will sanctify the tabernacle of the congregation, and the altar: I will sanctify also both Aaron and his sons, to minister to me in the priest’s office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 45, E'And I will dwell among the children of Israel, and will be their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 29, 46, E'And they shall know that I am the LORD their God, that brought them forth out of the land of Egypt, that I may dwell among them: I am the LORD their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 1, E'And thou shalt make an altar to burn incense upon: of shittim wood shalt thou make it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 2, E'A cubit shall be the length thereof, and a cubit the breadth thereof; foursquare shall it be: and two cubits shall be the height thereof: the horns thereof shall be of the same.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 3, E'And thou shalt overlay it with pure gold, the top thereof, and the sides thereof round about, and the horns thereof; and thou shalt make unto it a crown of gold round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 4, E'And two golden rings shalt thou make to it under the crown of it, by the two corners thereof, upon the two sides of it shalt thou make it; and they shall be for places for the staves to bear it withal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 5, E'And thou shalt make the staves of shittim wood, and overlay them with gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 6, E'And thou shalt put it before the vail that is by the ark of the testimony, before the mercy seat that is over the testimony, where I will meet with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 7, E'And Aaron shall burn thereon sweet incense every morning: when he dresseth the lamps, he shall burn incense upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 8, E'And when Aaron lighteth the lamps at even, he shall burn incense upon it, a perpetual incense before the LORD throughout your generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 9, E'Ye shall offer no strange incense thereon, nor burnt sacrifice, nor meat offering; neither shall ye pour drink offering thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 10, E'And Aaron shall make an atonement upon the horns of it once in a year with the blood of the sin offering of atonements: once in the year shall he make atonement upon it throughout your generations: it is most holy unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 11, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 12, E'When thou takest the sum of the children of Israel after their number, then shall they give every man a ransom for his soul unto the LORD, when thou numberest them; that there be no plague among them, when thou numberest them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 13, E'This they shall give, every one that passeth among them that are numbered, half a shekel after the shekel of the sanctuary: (a shekel is twenty gerahs:) an half shekel shall be the offering of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 14, E'Every one that passeth among them that are numbered, from twenty years old and above, shall give an offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 15, E'The rich shall not give more, and the poor shall not give less than half a shekel, when they give an offering unto the LORD, to make an atonement for your souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 16, E'And thou shalt take the atonement money of the children of Israel, and shalt appoint it for the service of the tabernacle of the congregation; that it may be a memorial unto the children of Israel before the LORD, to make an atonement for your souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 17, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 18, E'Thou shalt also make a laver of brass, and his foot also of brass, to wash withal: and thou shalt put it between the tabernacle of the congregation and the altar, and thou shalt put water therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 19, E'For Aaron and his sons shall wash their hands and their feet thereat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 20, E'When they go into the tabernacle of the congregation, they shall wash with water, that they die not; or when they come near to the altar to minister, to burn offering made by fire unto the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 21, E'So they shall wash their hands and their feet, that they die not: and it shall be a statute for ever to them, even to him and to his seed throughout their generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 22, E'Moreover the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 23, E'Take thou also unto thee principal spices, of pure myrrh five hundred shekels, and of sweet cinnamon half so much, even two hundred and fifty shekels, and of sweet calamus two hundred and fifty shekels,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 24, E'And of cassia five hundred shekels, after the shekel of the sanctuary, and of oil olive an hin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 25, E'And thou shalt make it an oil of holy ointment, an ointment compound after the art of the apothecary: it shall be an holy anointing oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 26, E'And thou shalt anoint the tabernacle of the congregation therewith, and the ark of the testimony,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 27, E'And the table and all his vessels, and the candlestick and his vessels, and the altar of incense,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 28, E'And the altar of burnt offering with all his vessels, and the laver and his foot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 29, E'And thou shalt sanctify them, that they may be most holy: whatsoever toucheth them shall be holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 30, E'And thou shalt anoint Aaron and his sons, and consecrate them, that they may minister unto me in the priest’s office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 31, E'And thou shalt speak unto the children of Israel, saying, This shall be an holy anointing oil unto me throughout your generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 32, E'Upon man’s flesh shall it not be poured, neither shall ye make any other like it, after the composition of it: it is holy, and it shall be holy unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 33, E'Whosoever compoundeth any like it, or whosoever putteth any of it upon a stranger, shall even be cut off from his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 34, E'And the LORD said unto Moses, Take unto thee sweet spices, stacte, and onycha, and galbanum; these sweet spices with pure frankincense: of each shall there be a like weight:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 35, E'And thou shalt make it a perfume, a confection after the art of the apothecary, tempered together, pure and holy:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 36, E'And thou shalt beat some of it very small, and put of it before the testimony in the tabernacle of the congregation, where I will meet with thee: it shall be unto you most holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 37, E'And as for the perfume which thou shalt make, ye shall not make to yourselves according to the composition thereof: it shall be unto thee holy for the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 30, 38, E'Whosoever shall make like unto that, to smell thereto, shall even be cut off from his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 2, E'See, I have called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 3, E'And I have filled him with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 4, E'To devise cunning works, to work in gold, and in silver, and in brass,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 5, E'And in cutting of stones, to set them, and in carving of timber, to work in all manner of workmanship.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 6, E'And I, behold, I have given with him Aholiab, the son of Ahisamach, of the tribe of Dan: and in the hearts of all that are wise hearted I have put wisdom, that they may make all that I have commanded thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 7, E'The tabernacle of the congregation, and the ark of the testimony, and the mercy seat that is thereupon, and all the furniture of the tabernacle,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 8, E'And the table and his furniture, and the pure candlestick with all his furniture, and the altar of incense,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 9, E'And the altar of burnt offering with all his furniture, and the laver and his foot,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 10, E'And the cloths of service, and the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest’s office,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 11, E'And the anointing oil, and sweet incense for the holy place: according to all that I have commanded thee shall they do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 12, E'And the LORD spake unto Moses, saying,')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Exodus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 13, E'Speak thou also unto the children of Israel, saying, Verily my sabbaths ye shall keep: for it is a sign between me and you throughout your generations; that ye may know that I am the LORD that doth sanctify you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 14, E'Ye shall keep the sabbath therefore; for it is holy unto you: every one that defileth it shall surely be put to death: for whosoever doeth any work therein, that soul shall be cut off from among his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 15, E'Six days may work be done; but in the seventh is the sabbath of rest, holy to the LORD: whosoever doeth any work in the sabbath day, he shall surely be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 16, E'Wherefore the children of Israel shall keep the sabbath, to observe the sabbath throughout their generations, for a perpetual covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 17, E'It is a sign between me and the children of Israel for ever: for in six days the LORD made heaven and earth, and on the seventh day he rested, and was refreshed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 31, 18, E'And he gave unto Moses, when he had made an end of communing with him upon mount Sinai, two tables of testimony, tables of stone, written with the finger of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 1, E'And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 2, E'And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 3, E'And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 4, E'And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel, which brought thee up out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 5, E'And when Aaron saw it, he built an altar before it; and Aaron made proclamation, and said, To morrow is a feast to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 6, E'And they rose up early on the morrow, and offered burnt offerings, and brought peace offerings; and the people sat down to eat and to drink, and rose up to play.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 7, E'And the LORD said unto Moses, Go, get thee down; for thy people, which thou broughtest out of the land of Egypt, have corrupted themselves:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 8, E'They have turned aside quickly out of the way which I commanded them: they have made them a molten calf, and have worshipped it, and have sacrificed thereunto, and said, These be thy gods, O Israel, which have brought thee up out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 9, E'And the LORD said unto Moses, I have seen this people, and, behold, it is a stiffnecked people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 10, E'Now therefore let me alone, that my wrath may wax hot against them, and that I may consume them: and I will make of thee a great nation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 11, E'And Moses besought the LORD his God, and said, LORD, why doth thy wrath wax hot against thy people, which thou hast brought forth out of the land of Egypt with great power, and with a mighty hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 12, E'Wherefore should the Egyptians speak, and say, For mischief did he bring them out, to slay them in the mountains, and to consume them from the face of the earth? Turn from thy fierce wrath, and repent of this evil against thy people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 13, E'Remember Abraham, Isaac, and Israel, thy servants, to whom thou swarest by thine own self, and saidst unto them, I will multiply your seed as the stars of heaven, and all this land that I have spoken of will I give unto your seed, and they shall inherit it for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 14, E'And the LORD repented of the evil which he thought to do unto his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 15, E'And Moses turned, and went down from the mount, and the two tables of the testimony were in his hand: the tables were written on both their sides; on the one side and on the other were they written.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 16, E'And the tables were the work of God, and the writing was the writing of God, graven upon the tables.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 17, E'And when Joshua heard the noise of the people as they shouted, he said unto Moses, There is a noise of war in the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 18, E'And he said, It is not the voice of them that shout for mastery, neither is it the voice of them that cry for being overcome: but the noise of them that sing do I hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 19, E'And it came to pass, as soon as he came nigh unto the camp, that he saw the calf, and the dancing: and Moses’ anger waxed hot, and he cast the tables out of his hands, and brake them beneath the mount.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 20, E'And he took the calf which they had made, and burnt it in the fire, and ground it to powder, and strawed it upon the water, and made the children of Israel drink of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 21, E'And Moses said unto Aaron, What did this people unto thee, that thou hast brought so great a sin upon them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 22, E'And Aaron said, Let not the anger of my lord wax hot: thou knowest the people, that they are set on mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 23, E'For they said unto me, Make us gods, which shall go before us: for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 24, E'And I said unto them, Whosoever hath any gold, let them break it off. So they gave it me: then I cast it into the fire, and there came out this calf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 25, E'And when Moses saw that the people were naked; (for Aaron had made them naked unto their shame among their enemies:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 26, E'Then Moses stood in the gate of the camp, and said, Who is on the LORD’s side? let him come unto me. And all the sons of Levi gathered themselves together unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 27, E'And he said unto them, Thus saith the LORD God of Israel, Put every man his sword by his side, and go in and out from gate to gate throughout the camp, and slay every man his brother, and every man his companion, and every man his neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 28, E'And the children of Levi did according to the word of Moses: and there fell of the people that day about three thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 29, E'For Moses had said, Consecrate yourselves today to the LORD, even every man upon his son, and upon his brother; that he may bestow upon you a blessing this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 30, E'And it came to pass on the morrow, that Moses said unto the people, Ye have sinned a great sin: and now I will go up unto the LORD; peradventure I shall make an atonement for your sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 31, E'And Moses returned unto the LORD, and said, Oh, this people have sinned a great sin, and have made them gods of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 32, E'Yet now, if thou wilt forgive their sin--; and if not, blot me, I pray thee, out of thy book which thou hast written.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 33, E'And the LORD said unto Moses, Whosoever hath sinned against me, him will I blot out of my book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 34, E'Therefore now go, lead the people unto the place of which I have spoken unto thee: behold, mine Angel shall go before thee: nevertheless in the day when I visit I will visit their sin upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 32, 35, E'And the LORD plagued the people, because they made the calf, which Aaron made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 1, E'And the LORD said unto Moses, Depart, and go up hence, thou and the people which thou hast brought up out of the land of Egypt, unto the land which I sware unto Abraham, to Isaac, and to Jacob, saying, Unto thy seed will I give it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 2, E'And I will send an angel before thee; and I will drive out the Canaanite, the Amorite, and the Hittite, and the Perizzite, the Hivite, and the Jebusite:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 3, E'Unto a land flowing with milk and honey: for I will not go up in the midst of thee; for thou art a stiffnecked people: lest I consume thee in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 4, E'And when the people heard these evil tidings, they mourned: and no man did put on him his ornaments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 5, E'For the LORD had said unto Moses, Say unto the children of Israel, Ye are a stiffnecked people: I will come up into the midst of thee in a moment, and consume thee: therefore now put off thy ornaments from thee, that I may know what to do unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 6, E'And the children of Israel stripped themselves of their ornaments by the mount Horeb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 7, E'And Moses took the tabernacle, and pitched it without the camp, afar off from the camp, and called it the Tabernacle of the congregation. And it came to pass, that every one which sought the LORD went out unto the tabernacle of the congregation, which was without the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 8, E'And it came to pass, when Moses went out unto the tabernacle, that all the people rose up, and stood every man at his tent door, and looked after Moses, until he was gone into the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 9, E'And it came to pass, as Moses entered into the tabernacle, the cloudy pillar descended, and stood at the door of the tabernacle, and the Lord talked with Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 10, E'And all the people saw the cloudy pillar stand at the tabernacle door: and all the people rose up and worshipped, every man in his tent door.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 11, E'And the LORD spake unto Moses face to face, as a man speaketh unto his friend. And he turned again into the camp: but his servant Joshua, the son of Nun, a young man, departed not out of the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 12, E'And Moses said unto the LORD, See, thou sayest unto me, Bring up this people: and thou hast not let me know whom thou wilt send with me. Yet thou hast said, I know thee by name, and thou hast also found grace in my sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 13, E'Now therefore, I pray thee, if I have found grace in thy sight, shew me now thy way, that I may know thee, that I may find grace in thy sight: and consider that this nation is thy people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 14, E'And he said, My presence shall go with thee, and I will give thee rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 15, E'And he said unto him, If thy presence go not with me, carry us not up hence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 16, E'For wherein shall it be known here that I and thy people have found grace in thy sight? is it not in that thou goest with us? so shall we be separated, I and thy people, from all the people that are upon the face of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 17, E'And the LORD said unto Moses, I will do this thing also that thou hast spoken: for thou hast found grace in my sight, and I know thee by name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 18, E'And he said, I beseech thee, shew me thy glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 19, E'And he said, I will make all my goodness pass before thee, and I will proclaim the name of the LORD before thee; and will be gracious to whom I will be gracious, and will shew mercy on whom I will shew mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 20, E'And he said, Thou canst not see my face: for there shall no man see me, and live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 21, E'And the LORD said, Behold, there is a place by me, and thou shalt stand upon a rock:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 22, E'And it shall come to pass, while my glory passeth by, that I will put thee in a clift of the rock, and will cover thee with my hand while I pass by:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 33, 23, E'And I will take away mine hand, and thou shalt see my back parts: but my face shall not be seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 1, E'And the LORD said unto Moses, Hew thee two tables of stone like unto the first: and I will write upon these tables the words that were in the first tables, which thou brakest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 2, E'And be ready in the morning, and come up in the morning unto mount Sinai, and present thyself there to me in the top of the mount.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 3, E'And no man shall come up with thee, neither let any man be seen throughout all the mount; neither let the flocks nor herds feed before that mount.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 4, E'And he hewed two tables of stone like unto the first; and Moses rose up early in the morning, and went up unto mount Sinai, as the LORD had commanded him, and took in his hand the two tables of stone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 5, E'And the LORD descended in the cloud, and stood with him there, and proclaimed the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 6, E'And the LORD passed by before him, and proclaimed, The LORD, The LORD God, merciful and gracious, longsuffering, and abundant in goodness and truth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 7, E'Keeping mercy for thousands, forgiving iniquity and transgression and sin, and that will by no means clear the guilty; visiting the iniquity of the fathers upon the children, and upon the children’s children, unto the third and to the fourth generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 8, E'And Moses made haste, and bowed his head toward the earth, and worshipped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 9, E'And he said, If now I have found grace in thy sight, O LORD, let my LORD, I pray thee, go among us; for it is a stiffnecked people; and pardon our iniquity and our sin, and take us for thine inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 10, E'And he said, Behold, I make a covenant: before all thy people I will do marvels, such as have not been done in all the earth, nor in any nation: and all the people among which thou art shall see the work of the LORD: for it is a terrible thing that I will do with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 11, E'Observe thou that which I command thee this day: behold, I drive out before thee the Amorite, and the Canaanite, and the Hittite, and the Perizzite, and the Hivite, and the Jebusite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 12, E'Take heed to thyself, lest thou make a covenant with the inhabitants of the land whither thou goest, lest it be for a snare in the midst of thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 13, E'But ye shall destroy their altars, break their images, and cut down their groves:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 14, E'For thou shalt worship no other god: for the LORD, whose name is Jealous, is a jealous God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 15, E'Lest thou make a covenant with the inhabitants of the land, and they go a whoring after their gods, and do sacrifice unto their gods, and one call thee, and thou eat of his sacrifice;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 16, E'And thou take of their daughters unto thy sons, and their daughters go a whoring after their gods, and make thy sons go a whoring after their gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 17, E'Thou shalt make thee no molten gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 18, E'The feast of unleavened bread shalt thou keep. Seven days thou shalt eat unleavened bread, as I commanded thee, in the time of the month Abib: for in the month Abib thou camest out from Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 19, E'All that openeth the matrix is mine; and every firstling among thy cattle, whether ox or sheep, that is male.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 20, E'But the firstling of an ass thou shalt redeem with a lamb: and if thou redeem him not, then shalt thou break his neck. All the firstborn of thy sons thou shalt redeem. And none shall appear before me empty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 21, E'Six days thou shalt work, but on the seventh day thou shalt rest: in earing time and in harvest thou shalt rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 22, E'And thou shalt observe the feast of weeks, of the firstfruits of wheat harvest, and the feast of ingathering at the year’s end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 23, E'Thrice in the year shall all your menchildren appear before the LORD God, the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 24, E'For I will cast out the nations before thee, and enlarge thy borders: neither shall any man desire thy land, when thou shalt go up to appear before the LORD thy God thrice in the year.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 25, E'Thou shalt not offer the blood of my sacrifice with leaven; neither shall the sacrifice of the feast of the passover be left unto the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 26, E'The first of the firstfruits of thy land thou shalt bring unto the house of the LORD thy God. Thou shalt not seethe a kid in his mother’s milk.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 27, E'And the LORD said unto Moses, Write thou these words: for after the tenor of these words I have made a covenant with thee and with Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 28, E'And he was there with the LORD forty days and forty nights; he did neither eat bread, nor drink water. And he wrote upon the tables the words of the covenant, the ten commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 29, E'And it came to pass, when Moses came down from mount Sinai with the two tables of testimony in Moses’ hand, when he came down from the mount, that Moses wist not that the skin of his face shone while he talked with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 30, E'And when Aaron and all the children of Israel saw Moses, behold, the skin of his face shone; and they were afraid to come nigh him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 31, E'And Moses called unto them; and Aaron and all the rulers of the congregation returned unto him: and Moses talked with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 32, E'And afterward all the children of Israel came nigh: and he gave them in commandment all that the LORD had spoken with him in mount Sinai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 33, E'And till Moses had done speaking with them, he put a vail on his face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 34, E'But when Moses went in before the LORD to speak with him, he took the vail off, until he came out. And he came out, and spake unto the children of Israel that which he was commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 34, 35, E'And the children of Israel saw the face of Moses, that the skin of Moses’ face shone: and Moses put the vail upon his face again, until he went in to speak with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 1, E'And Moses gathered all the congregation of the children of Israel together, and said unto them, These are the words which the LORD hath commanded, that ye should do them.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Exodus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 2, E'Six days shall work be done, but on the seventh day there shall be to you an holy day, a sabbath of rest to the LORD: whosoever doeth work therein shall be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 3, E'Ye shall kindle no fire throughout your habitations upon the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 4, E'And Moses spake unto all the congregation of the children of Israel, saying, This is the thing which the LORD commanded, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 5, E'Take ye from among you an offering unto the LORD: whosoever is of a willing heart, let him bring it, an offering of the LORD; gold, and silver, and brass,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 6, E'And blue, and purple, and scarlet, and fine linen, and goats’ hair,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 7, E'And rams’ skins dyed red, and badgers’ skins, and shittim wood,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 8, E'And oil for the light, and spices for anointing oil, and for the sweet incense,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 9, E'And onyx stones, and stones to be set for the ephod, and for the breastplate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 10, E'And every wise hearted among you shall come, and make all that the LORD hath commanded;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 11, E'The tabernacle, his tent, and his covering, his taches, and his boards, his bars, his pillars, and his sockets,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 12, E'The ark, and the staves thereof, with the mercy seat, and the vail of the covering,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 13, E'The table, and his staves, and all his vessels, and the shewbread,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 14, E'The candlestick also for the light, and his furniture, and his lamps, with the oil for the light,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 15, E'And the incense altar, and his staves, and the anointing oil, and the sweet incense, and the hanging for the door at the entering in of the tabernacle,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 16, E'The altar of burnt offering, with his brasen grate, his staves, and all his vessels, the laver and his foot,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 17, E'The hangings of the court, his pillars, and their sockets, and the hanging for the door of the court,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 18, E'The pins of the tabernacle, and the pins of the court, and their cords,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 19, E'The cloths of service, to do service in the holy place, the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest’s office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 20, E'And all the congregation of the children of Israel departed from the presence of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 21, E'And they came, every one whose heart stirred him up, and every one whom his spirit made willing, and they brought the LORD’s offering to the work of the tabernacle of the congregation, and for all his service, and for the holy garments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 22, E'And they came, both men and women, as many as were willing hearted, and brought bracelets, and earrings, and rings, and tablets, all jewels of gold: and every man that offered offered an offering of gold unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 23, E'And every man, with whom was found blue, and purple, and scarlet, and fine linen, and goats’ hair, and red skins of rams, and badgers’ skins, brought them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 24, E'Every one that did offer an offering of silver and brass brought the LORD’s offering: and every man, with whom was found shittim wood for any work of the service, brought it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 25, E'And all the women that were wise hearted did spin with their hands, and brought that which they had spun, both of blue, and of purple, and of scarlet, and of fine linen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 26, E'And all the women whose heart stirred them up in wisdom spun goats’ hair.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 27, E'And the rulers brought onyx stones, and stones to be set, for the ephod, and for the breastplate;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 28, E'And spice, and oil for the light, and for the anointing oil, and for the sweet incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 29, E'The children of Israel brought a willing offering unto the LORD, every man and woman, whose heart made them willing to bring for all manner of work, which the LORD had commanded to be made by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 30, E'And Moses said unto the children of Israel, See, the LORD hath called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 31, E'And he hath filled him with the spirit of God, in wisdom, in understanding, and in knowledge, and in all manner of workmanship;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 32, E'And to devise curious works, to work in gold, and in silver, and in brass,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 33, E'And in the cutting of stones, to set them, and in carving of wood, to make any manner of cunning work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 34, E'And he hath put in his heart that he may teach, both he, and Aholiab, the son of Ahisamach, of the tribe of Dan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 35, 35, E'Them hath he filled with wisdom of heart, to work all manner of work, of the engraver, and of the cunning workman, and of the embroiderer, in blue, and in purple, in scarlet, and in fine linen, and of the weaver, even of them that do any work, and of those that devise cunning work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 1, E'Then wrought Bezaleel and Aholiab, and every wise hearted man, in whom the LORD put wisdom and understanding to know how to work all manner of work for the service of the sanctuary, according to all that the LORD had commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 2, E'And Moses called Bezaleel and Aholiab, and every wise hearted man, in whose heart the LORD had put wisdom, even every one whose heart stirred him up to come unto the work to do it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 3, E'And they received of Moses all the offering, which the children of Israel had brought for the work of the service of the sanctuary, to make it withal. And they brought yet unto him free offerings every morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 4, E'And all the wise men, that wrought all the work of the sanctuary, came every man from his work which they made;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 5, E'And they spake unto Moses, saying, The people bring much more than enough for the service of the work, which the LORD commanded to make.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 6, E'And Moses gave commandment, and they caused it to be proclaimed throughout the camp, saying, Let neither man nor woman make any more work for the offering of the sanctuary. So the people were restrained from bringing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 7, E'For the stuff they had was sufficient for all the work to make it, and too much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 8, E'And every wise hearted man among them that wrought the work of the tabernacle made ten curtains of fine twined linen, and blue, and purple, and scarlet: with cherubims of cunning work made he them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 9, E'The length of one curtain was twenty and eight cubits, and the breadth of one curtain four cubits: the curtains were all of one size.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 10, E'And he coupled the five curtains one unto another: and the other five curtains he coupled one unto another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 11, E'And he made loops of blue on the edge of one curtain from the selvedge in the coupling: likewise he made in the uttermost side of another curtain, in the coupling of the second.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 12, E'Fifty loops made he in one curtain, and fifty loops made he in the edge of the curtain which was in the coupling of the second: the loops held one curtain to another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 13, E'And he made fifty taches of gold, and coupled the curtains one unto another with the taches: so it became one tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 14, E'And he made curtains of goats’ hair for the tent over the tabernacle: eleven curtains he made them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 15, E'The length of one curtain was thirty cubits, and four cubits was the breadth of one curtain: the eleven curtains were of one size.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 16, E'And he coupled five curtains by themselves, and six curtains by themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 17, E'And he made fifty loops upon the uttermost edge of the curtain in the coupling, and fifty loops made he upon the edge of the curtain which coupleth the second.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 18, E'And he made fifty taches of brass to couple the tent together, that it might be one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 19, E'And he made a covering for the tent of rams’ skins dyed red, and a covering of badgers’ skins above that.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 20, E'And he made boards for the tabernacle of shittim wood, standing up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 21, E'The length of a board was ten cubits, and the breadth of a board one cubit and a half.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 22, E'One board had two tenons, equally distant one from another: thus did he make for all the boards of the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 23, E'And he made boards for the tabernacle; twenty boards for the south side southward:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 24, E'And forty sockets of silver he made under the twenty boards; two sockets under one board for his two tenons, and two sockets under another board for his two tenons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 25, E'And for the other side of the tabernacle, which is toward the north corner, he made twenty boards,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 26, E'And their forty sockets of silver; two sockets under one board, and two sockets under another board.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 27, E'And for the sides of the tabernacle westward he made six boards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 28, E'And two boards made he for the corners of the tabernacle in the two sides.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 29, E'And they were coupled beneath, and coupled together at the head thereof, to one ring: thus he did to both of them in both the corners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 30, E'And there were eight boards; and their sockets were sixteen sockets of silver, under every board two sockets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 31, E'And he made bars of shittim wood; five for the boards of the one side of the tabernacle,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 32, E'And five bars for the boards of the other side of the tabernacle, and five bars for the boards of the tabernacle for the sides westward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 33, E'And he made the middle bar to shoot through the boards from the one end to the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 34, E'And he overlaid the boards with gold, and made their rings of gold to be places for the bars, and overlaid the bars with gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 35, E'And he made a vail of blue, and purple, and scarlet, and fine twined linen: with cherubims made he it of cunning work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 36, E'And he made thereunto four pillars of shittim wood, and overlaid them with gold: their hooks were of gold; and he cast for them four sockets of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 37, E'And he made an hanging for the tabernacle door of blue, and purple, and scarlet, and fine twined linen, of needlework;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 36, 38, E'And the five pillars of it with their hooks: and he overlaid their chapiters and their fillets with gold: but their five sockets were of brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 1, E'And Bezaleel made the ark of shittim wood: two cubits and a half was the length of it, and a cubit and a half the breadth of it, and a cubit and a half the height of it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 2, E'And he overlaid it with pure gold within and without, and made a crown of gold to it round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 3, E'And he cast for it four rings of gold, to be set by the four corners of it; even two rings upon the one side of it, and two rings upon the other side of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 4, E'And he made staves of shittim wood, and overlaid them with gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 5, E'And he put the staves into the rings by the sides of the ark, to bear the ark.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 6, E'And he made the mercy seat of pure gold: two cubits and a half was the length thereof, and one cubit and a half the breadth thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 7, E'And he made two cherubims of gold, beaten out of one piece made he them, on the two ends of the mercy seat;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 8, E'One cherub on the end on this side, and another cherub on the other end on that side: out of the mercy seat made he the cherubims on the two ends thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 9, E'And the cherubims spread out their wings on high, and covered with their wings over the mercy seat, with their faces one to another; even to the mercy seatward were the faces of the cherubims.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 10, E'And he made the table of shittim wood: two cubits was the length thereof, and a cubit the breadth thereof, and a cubit and a half the height thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 11, E'And he overlaid it with pure gold, and made thereunto a crown of gold round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 12, E'Also he made thereunto a border of an handbreadth round about; and made a crown of gold for the border thereof round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 13, E'And he cast for it four rings of gold, and put the rings upon the four corners that were in the four feet thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 14, E'Over against the border were the rings, the places for the staves to bear the table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 15, E'And he made the staves of shittim wood, and overlaid them with gold, to bear the table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 16, E'And he made the vessels which were upon the table, his dishes, and his spoons, and his bowls, and his covers to cover withal, of pure gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 17, E'And he made the candlestick of pure gold: of beaten work made he the candlestick; his shaft, and his branch, his bowls, his knops, and his flowers, were of the same:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 18, E'And six branches going out of the sides thereof; three branches of the candlestick out of the one side thereof, and three branches of the candlestick out of the other side thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 19, E'Three bowls made after the fashion of almonds in one branch, a knop and a flower; and three bowls made like almonds in another branch, a knop and a flower: so throughout the six branches going out of the candlestick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 20, E'And in the candlestick were four bowls made like almonds, his knops, and his flowers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 21, E'And a knop under two branches of the same, and a knop under two branches of the same, and a knop under two branches of the same, according to the six branches going out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 22, E'Their knops and their branches were of the same: all of it was one beaten work of pure gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 23, E'And he made his seven lamps, and his snuffers, and his snuffdishes, of pure gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 24, E'Of a talent of pure gold made he it, and all the vessels thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 25, E'And he made the incense altar of shittim wood: the length of it was a cubit, and the breadth of it a cubit; it was foursquare; and two cubits was the height of it; the horns thereof were of the same.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 26, E'And he overlaid it with pure gold, both the top of it, and the sides thereof round about, and the horns of it: also he made unto it a crown of gold round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 27, E'And he made two rings of gold for it under the crown thereof, by the two corners of it, upon the two sides thereof, to be places for the staves to bear it withal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 28, E'And he made the staves of shittim wood, and overlaid them with gold.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Exodus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 37, 29, E'And he made the holy anointing oil, and the pure incense of sweet spices, according to the work of the apothecary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 1, E'And he made the altar of burnt offering of shittim wood: five cubits was the length thereof, and five cubits the breadth thereof; it was foursquare; and three cubits the height thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 2, E'And he made the horns thereof on the four corners of it; the horns thereof were of the same: and he overlaid it with brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 3, E'And he made all the vessels of the altar, the pots, and the shovels, and the basons, and the fleshhooks, and the firepans: all the vessels thereof made he of brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 4, E'And he made for the altar a brasen grate of network under the compass thereof beneath unto the midst of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 5, E'And he cast four rings for the four ends of the grate of brass, to be places for the staves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 6, E'And he made the staves of shittim wood, and overlaid them with brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 7, E'And he put the staves into the rings on the sides of the altar, to bear it withal; he made the altar hollow with boards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 8, E'And he made the laver of brass, and the foot of it of brass, of the lookingglasses of the women assembling, which assembled at the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 9, E'And he made the court: on the south side southward the hangings of the court were of fine twined linen, an hundred cubits:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 10, E'Their pillars were twenty, and their brasen sockets twenty; the hooks of the pillars and their fillets were of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 11, E'And for the north side the hangings were an hundred cubits, their pillars were twenty, and their sockets of brass twenty; the hooks of the pillars and their fillets of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 12, E'And for the west side were hangings of fifty cubits, their pillars ten, and their sockets ten; the hooks of the pillars and their fillets of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 13, E'And for the east side eastward fifty cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 14, E'The hangings of the one side of the gate were fifteen cubits; their pillars three, and their sockets three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 15, E'And for the other side of the court gate, on this hand and that hand, were hangings of fifteen cubits; their pillars three, and their sockets three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 16, E'All the hangings of the court round about were of fine twined linen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 17, E'And the sockets for the pillars were of brass; the hooks of the pillars and their fillets of silver; and the overlaying of their chapiters of silver; and all the pillars of the court were filleted with silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 18, E'And the hanging for the gate of the court was needlework, of blue, and purple, and scarlet, and fine twined linen: and twenty cubits was the length, and the height in the breadth was five cubits, answerable to the hangings of the court.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 19, E'And their pillars were four, and their sockets of brass four; their hooks of silver, and the overlaying of their chapiters and their fillets of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 20, E'And all the pins of the tabernacle, and of the court round about, were of brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 21, E'This is the sum of the tabernacle, even of the tabernacle of testimony, as it was counted, according to the commandment of Moses, for the service of the Levites, by the hand of Ithamar, son to Aaron the priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 22, E'And Bezaleel the son of Uri, the son of Hur, of the tribe of Judah, made all that the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 23, E'And with him was Aholiab, son of Ahisamach, of the tribe of Dan, an engraver, and a cunning workman, and an embroiderer in blue, and in purple, and in scarlet, and fine linen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 24, E'All the gold that was occupied for the work in all the work of the holy place, even the gold of the offering, was twenty and nine talents, and seven hundred and thirty shekels, after the shekel of the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 25, E'And the silver of them that were numbered of the congregation was an hundred talents, and a thousand seven hundred and threescore and fifteen shekels, after the shekel of the sanctuary:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 26, E'A bekah for every man, that is, half a shekel, after the shekel of the sanctuary, for every one that went to be numbered, from twenty years old and upward, for six hundred thousand and three thousand and five hundred and fifty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 27, E'And of the hundred talents of silver were cast the sockets of the sanctuary, and the sockets of the vail; an hundred sockets of the hundred talents, a talent for a socket.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 28, E'And of the thousand seven hundred seventy and five shekels he made hooks for the pillars, and overlaid their chapiters, and filleted them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 29, E'And the brass of the offering was seventy talents, and two thousand and four hundred shekels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 30, E'And therewith he made the sockets to the door of the tabernacle of the congregation, and the brasen altar, and the brasen grate for it, and all the vessels of the altar,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 38, 31, E'And the sockets of the court round about, and the sockets of the court gate, and all the pins of the tabernacle, and all the pins of the court round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 1, E'And of the blue, and purple, and scarlet, they made cloths of service, to do service in the holy place, and made the holy garments for Aaron; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 2, E'And he made the ephod of gold, blue, and purple, and scarlet, and fine twined linen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 3, E'And they did beat the gold into thin plates, and cut it into wires, to work it in the blue, and in the purple, and in the scarlet, and in the fine linen, with cunning work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 4, E'They made shoulderpieces for it, to couple it together: by the two edges was it coupled together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 5, E'And the curious girdle of his ephod, that was upon it, was of the same, according to the work thereof; of gold, blue, and purple, and scarlet, and fine twined linen; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 6, E'And they wrought onyx stones inclosed in ouches of gold, graven, as signets are graven, with the names of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 7, E'And he put them on the shoulders of the ephod, that they should be stones for a memorial to the children of Israel; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 8, E'And he made the breastplate of cunning work, like the work of the ephod; of gold, blue, and purple, and scarlet, and fine twined linen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 9, E'It was foursquare; they made the breastplate double: a span was the length thereof, and a span the breadth thereof, being doubled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 10, E'And they set in it four rows of stones: the first row was a sardius, a topaz, and a carbuncle: this was the first row.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 11, E'And the second row, an emerald, a sapphire, and a diamond.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 12, E'And the third row, a ligure, an agate, and an amethyst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 13, E'And the fourth row, a beryl, an onyx, and a jasper: they were inclosed in ouches of gold in their inclosings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 14, E'And the stones were according to the names of the children of Israel, twelve, according to their names, like the engravings of a signet, every one with his name, according to the twelve tribes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 15, E'And they made upon the breastplate chains at the ends, of wreathen work of pure gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 16, E'And they made two ouches of gold, and two gold rings; and put the two rings in the two ends of the breastplate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 17, E'And they put the two wreathen chains of gold in the two rings on the ends of the breastplate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 18, E'And the two ends of the two wreathen chains they fastened in the two ouches, and put them on the shoulderpieces of the ephod, before it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 19, E'And they made two rings of gold, and put them on the two ends of the breastplate, upon the border of it, which was on the side of the ephod inward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 20, E'And they made two other golden rings, and put them on the two sides of the ephod underneath, toward the forepart of it, over against the other coupling thereof, above the curious girdle of the ephod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 21, E'And they did bind the breastplate by his rings unto the rings of the ephod with a lace of blue, that it might be above the curious girdle of the ephod, and that the breastplate might not be loosed from the ephod; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 22, E'And he made the robe of the ephod of woven work, all of blue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 23, E'And there was an hole in the midst of the robe, as the hole of an habergeon, with a band round about the hole, that it should not rend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 24, E'And they made upon the hems of the robe pomegranates of blue, and purple, and scarlet, and twined linen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 25, E'And they made bells of pure gold, and put the bells between the pomegranates upon the hem of the robe, round about between the pomegranates;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 26, E'A bell and a pomegranate, a bell and a pomegranate, round about the hem of the robe to minister in; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 27, E'And they made coats of fine linen of woven work for Aaron, and for his sons,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 28, E'And a mitre of fine linen, and goodly bonnets of fine linen, and linen breeches of fine twined linen,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 29, E'And a girdle of fine twined linen, and blue, and purple, and scarlet, of needlework; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 30, E'And they made the plate of the holy crown of pure gold, and wrote upon it a writing, like to the engravings of a signet, HOLINESS TO THE LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 31, E'And they tied unto it a lace of blue, to fasten it on high upon the mitre; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 32, E'Thus was all the work of the tabernacle of the tent of the congregation finished: and the children of Israel did according to all that the LORD commanded Moses, so did they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 33, E'And they brought the tabernacle unto Moses, the tent, and all his furniture, his taches, his boards, his bars, and his pillars, and his sockets,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 34, E'And the covering of rams’ skins dyed red, and the covering of badgers’ skins, and the vail of the covering,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 35, E'The ark of the testimony, and the staves thereof, and the mercy seat,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 36, E'The table, and all the vessels thereof, and the shewbread,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 37, E'The pure candlestick, with the lamps thereof, even with the lamps to be set in order, and all the vessels thereof, and the oil for light,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 38, E'And the golden altar, and the anointing oil, and the sweet incense, and the hanging for the tabernacle door,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 39, E'The brasen altar, and his grate of brass, his staves, and all his vessels, the laver and his foot,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 40, E'The hangings of the court, his pillars, and his sockets, and the hanging for the court gate, his cords, and his pins, and all the vessels of the service of the tabernacle, for the tent of the congregation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 41, E'The cloths of service to do service in the holy place, and the holy garments for Aaron the priest, and his sons’ garments, to minister in the priest’s office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 42, E'According to all that the LORD commanded Moses, so the children of Israel made all the work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 39, 43, E'And Moses did look upon all the work, and, behold, they had done it as the LORD had commanded, even so had they done it: and Moses blessed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 2, E'On the first day of the first month shalt thou set up the tabernacle of the tent of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 3, E'And thou shalt put therein the ark of the testimony, and cover the ark with the vail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 4, E'And thou shalt bring in the table, and set in order the things that are to be set in order upon it; and thou shalt bring in the candlestick, and light the lamps thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 5, E'And thou shalt set the altar of gold for the incense before the ark of the testimony, and put the hanging of the door to the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 6, E'And thou shalt set the altar of the burnt offering before the door of the tabernacle of the tent of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 7, E'And thou shalt set the laver between the tent of the congregation and the altar, and shalt put water therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 8, E'And thou shalt set up the court round about, and hang up the hanging at the court gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 9, E'And thou shalt take the anointing oil, and anoint the tabernacle, and all that is therein, and shalt hallow it, and all the vessels thereof: and it shall be holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 10, E'And thou shalt anoint the altar of the burnt offering, and all his vessels, and sanctify the altar: and it shall be an altar most holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 11, E'And thou shalt anoint the laver and his foot, and sanctify it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 12, E'And thou shalt bring Aaron and his sons unto the door of the tabernacle of the congregation, and wash them with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 13, E'And thou shalt put upon Aaron the holy garments, and anoint him, and sanctify him; that he may minister unto me in the priest’s office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 14, E'And thou shalt bring his sons, and clothe them with coats:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 15, E'And thou shalt anoint them, as thou didst anoint their father, that they may minister unto me in the priest’s office: for their anointing shall surely be an everlasting priesthood throughout their generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 16, E'Thus did Moses: according to all that the LORD commanded him, so did he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 17, E'And it came to pass in the first month in the second year, on the first day of the month, that the tabernacle was reared up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 18, E'And Moses reared up the tabernacle, and fastened his sockets, and set up the boards thereof, and put in the bars thereof, and reared up his pillars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 19, E'And he spread abroad the tent over the tabernacle, and put the covering of the tent above upon it; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 20, E'And he took and put the testimony into the ark, and set the staves on the ark, and put the mercy seat above upon the ark:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 21, E'And he brought the ark into the tabernacle, and set up the vail of the covering, and covered the ark of the testimony; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 22, E'And he put the table in the tent of the congregation, upon the side of the tabernacle northward, without the vail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 23, E'And he set the bread in order upon it before the LORD; as the LORD had commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 24, E'And he put the candlestick in the tent of the congregation, over against the table, on the side of the tabernacle southward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 25, E'And he lighted the lamps before the LORD; as the LORD commanded Moses.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Exodus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 26, E'And he put the golden altar in the tent of the congregation before the vail:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 27, E'And he burnt sweet incense thereon; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 28, E'And he set up the hanging at the door of the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 29, E'And he put the altar of burnt offering by the door of the tabernacle of the tent of the congregation, and offered upon it the burnt offering and the meat offering; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 30, E'And he set the laver between the tent of the congregation and the altar, and put water there, to wash withal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 31, E'And Moses and Aaron and his sons washed their hands and their feet thereat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 32, E'When they went into the tent of the congregation, and when they came near unto the altar, they washed; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 33, E'And he reared up the court round about the tabernacle and the altar, and set up the hanging of the court gate. So Moses finished the work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 34, E'Then a cloud covered the tent of the congregation, and the glory of the LORD filled the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 35, E'And Moses was not able to enter into the tent of the congregation, because the cloud abode thereon, and the glory of the LORD filled the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 36, E'And when the cloud was taken up from over the tabernacle, the children of Israel went onward in all their journeys:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 37, E'But if the cloud were not taken up, then they journeyed not till the day that it was taken up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2a9367d1-39d7-4a15-8f34-1c00c93bcd42', 40, 38, E'For the cloud of the LORD was upon the tabernacle by day, and fire was on it by night, in the sight of all the house of Israel, throughout all their journeys.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Exodus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 1, E'And the LORD called unto Moses, and spake unto him out of the tabernacle of the congregation, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 2, E'Speak unto the children of Israel, and say unto them, If any man of you bring an offering unto the LORD, ye shall bring your offering of the cattle, even of the herd, and of the flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 3, E'If his offering be a burnt sacrifice of the herd, let him offer a male without blemish: he shall offer it of his own voluntary will at the door of the tabernacle of the congregation before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 4, E'And he shall put his hand upon the head of the burnt offering; and it shall be accepted for him to make atonement for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 5, E'And he shall kill the bullock before the LORD: and the priests, Aaron’s sons, shall bring the blood, and sprinkle the blood round about upon the altar that is by the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 6, E'And he shall flay the burnt offering, and cut it into his pieces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 7, E'And the sons of Aaron the priest shall put fire upon the altar, and lay the wood in order upon the fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 8, E'And the priests, Aaron’s sons, shall lay the parts, the head, and the fat, in order upon the wood that is on the fire which is upon the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 9, E'But his inwards and his legs shall he wash in water: and the priest shall burn all on the altar, to be a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 10, E'And if his offering be of the flocks, namely, of the sheep, or of the goats, for a burnt sacrifice; he shall bring it a male without blemish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 11, E'And he shall kill it on the side of the altar northward before the LORD: and the priests, Aaron’s sons, shall sprinkle his blood round about upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 12, E'And he shall cut it into his pieces, with his head and his fat: and the priest shall lay them in order on the wood that is on the fire which is upon the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 13, E'But he shall wash the inwards and the legs with water: and the priest shall bring it all, and burn it upon the altar: it is a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 14, E'And if the burnt sacrifice for his offering to the LORD be of fowls, then he shall bring his offering of turtledoves, or of young pigeons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 15, E'And the priest shall bring it unto the altar, and wring off his head, and burn it on the altar; and the blood thereof shall be wrung out at the side of the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 16, E'And he shall pluck away his crop with his feathers, and cast it beside the altar on the east part, by the place of the ashes:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 1, 17, E'And he shall cleave it with the wings thereof, but shall not divide it asunder: and the priest shall burn it upon the altar, upon the wood that is upon the fire: it is a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 1, E'And when any will offer a meat offering unto the LORD, his offering shall be of fine flour; and he shall pour oil upon it, and put frankincense thereon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 2, E'And he shall bring it to Aaron’s sons the priests: and he shall take thereout his handful of the flour thereof, and of the oil thereof, with all the frankincense thereof; and the priest shall burn the memorial of it upon the altar, to be an offering made by fire, of a sweet savour unto the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 3, E'And the remnant of the meat offering shall be Aaron’s and his sons’: it is a thing most holy of the offerings of the LORD made by fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 4, E'And if thou bring an oblation of a meat offering baken in the oven, it shall be unleavened cakes of fine flour mingled with oil, or unleavened wafers anointed with oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 5, E'And if thy oblation be a meat offering baken in a pan, it shall be of fine flour unleavened, mingled with oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 6, E'Thou shalt part it in pieces, and pour oil thereon: it is a meat offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 7, E'And if thy oblation be a meat offering baken in the fryingpan, it shall be made of fine flour with oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 8, E'And thou shalt bring the meat offering that is made of these things unto the LORD: and when it is presented unto the priest, he shall bring it unto the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 9, E'And the priest shall take from the meat offering a memorial thereof, and shall burn it upon the altar: it is an offering made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 10, E'And that which is left of the meat offering shall be Aaron’s and his sons’: it is a thing most holy of the offerings of the LORD made by fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 11, E'No meat offering, which ye shall bring unto the LORD, shall be made with leaven: for ye shall burn no leaven, nor any honey, in any offering of the LORD made by fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 12, E'As for the oblation of the firstfruits, ye shall offer them unto the LORD: but they shall not be burnt on the altar for a sweet savour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 13, E'And every oblation of thy meat offering shalt thou season with salt; neither shalt thou suffer the salt of the covenant of thy God to be lacking from thy meat offering: with all thine offerings thou shalt offer salt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 14, E'And if thou offer a meat offering of thy firstfruits unto the LORD, thou shalt offer for the meat offering of thy firstfruits green ears of corn dried by the fire, even corn beaten out of full ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 15, E'And thou shalt put oil upon it, and lay frankincense thereon: it is a meat offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 2, 16, E'And the priest shall burn the memorial of it, part of the beaten corn thereof, and part of the oil thereof, with all the frankincense thereof: it is an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 1, E'And if his oblation be a sacrifice of peace offering, if he offer it of the herd; whether it be a male or female, he shall offer it without blemish before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 2, E'And he shall lay his hand upon the head of his offering, and kill it at the door of the tabernacle of the congregation: and Aaron’s sons the priests shall sprinkle the blood upon the altar round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 3, E'And he shall offer of the sacrifice of the peace offering an offering made by fire unto the LORD; the fat that covereth the inwards, and all the fat that is upon the inwards,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 4, E'And the two kidneys, and the fat that is on them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 5, E'And Aaron’s sons shall burn it on the altar upon the burnt sacrifice, which is upon the wood that is on the fire: it is an offering made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 6, E'And if his offering for a sacrifice of peace offering unto the LORD be of the flock; male or female, he shall offer it without blemish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 7, E'If he offer a lamb for his offering, then shall he offer it before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 8, E'And he shall lay his hand upon the head of his offering, and kill it before the tabernacle of the congregation: and Aaron’s sons shall sprinkle the blood thereof round about upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 9, E'And he shall offer of the sacrifice of the peace offering an offering made by fire unto the LORD; the fat thereof, and the whole rump, it shall he take off hard by the backbone; and the fat that covereth the inwards, and all the fat that is upon the inwards,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 10, E'And the two kidneys, and the fat that is upon them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 11, E'And the priest shall burn it upon the altar: it is the food of the offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 12, E'And if his offering be a goat, then he shall offer it before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 13, E'And he shall lay his hand upon the head of it, and kill it before the tabernacle of the congregation: and the sons of Aaron shall sprinkle the blood thereof upon the altar round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 14, E'And he shall offer thereof his offering, even an offering made by fire unto the LORD; the fat that covereth the inwards, and all the fat that is upon the inwards,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 15, E'And the two kidneys, and the fat that is upon them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 16, E'And the priest shall burn them upon the altar: it is the food of the offering made by fire for a sweet savour: all the fat is the LORD’s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 3, 17, E'It shall be a perpetual statute for your generations throughout all your dwellings, that ye eat neither fat nor blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 2, E'Speak unto the children of Israel, saying, If a soul shall sin through ignorance against any of the commandments of the LORD concerning things which ought not to be done, and shall do against any of them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 3, E'If the priest that is anointed do sin according to the sin of the people; then let him bring for his sin, which he hath sinned, a young bullock without blemish unto the LORD for a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 4, E'And he shall bring the bullock unto the door of the tabernacle of the congregation before the LORD; and shall lay his hand upon the bullock’s head, and kill the bullock before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 5, E'And the priest that is anointed shall take of the bullock’s blood, and bring it to the tabernacle of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 6, E'And the priest shall dip his finger in the blood, and sprinkle of the blood seven times before the LORD, before the vail of the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 7, E'And the priest shall put some of the blood upon the horns of the altar of sweet incense before the LORD, which is in the tabernacle of the congregation; and shall pour all the blood of the bullock at the bottom of the altar of the burnt offering, which is at the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 8, E'And he shall take off from it all the fat of the bullock for the sin offering; the fat that covereth the inwards, and all the fat that is upon the inwards,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 9, E'And the two kidneys, and the fat that is upon them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 10, E'As it was taken off from the bullock of the sacrifice of peace offerings: and the priest shall burn them upon the altar of the burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 11, E'And the skin of the bullock, and all his flesh, with his head, and with his legs, and his inwards, and his dung,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 12, E'Even the whole bullock shall he carry forth without the camp unto a clean place, where the ashes are poured out, and burn him on the wood with fire: where the ashes are poured out shall he be burnt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 13, E'And if the whole congregation of Israel sin through ignorance, and the thing be hid from the eyes of the assembly, and they have done somewhat against any of the commandments of the LORD concerning things which should not be done, and are guilty;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 14, E'When the sin, which they have sinned against it, is known, then the congregation shall offer a young bullock for the sin, and bring him before the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 15, E'And the elders of the congregation shall lay their hands upon the head of the bullock before the LORD: and the bullock shall be killed before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 16, E'And the priest that is anointed shall bring of the bullock’s blood to the tabernacle of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 17, E'And the priest shall dip his finger in some of the blood, and sprinkle it seven times before the LORD, even before the vail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 18, E'And he shall put some of the blood upon the horns of the altar which is before the LORD, that is in the tabernacle of the congregation, and shall pour out all the blood at the bottom of the altar of the burnt offering, which is at the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 19, E'And he shall take all his fat from him, and burn it upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 20, E'And he shall do with the bullock as he did with the bullock for a sin offering, so shall he do with this: and the priest shall make an atonement for them, and it shall be forgiven them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 21, E'And he shall carry forth the bullock without the camp, and burn him as he burned the first bullock: it is a sin offering for the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 22, E'When a ruler hath sinned, and done somewhat through ignorance against any of the commandments of the LORD his God concerning things which should not be done, and is guilty;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 23, E'Or if his sin, wherein he hath sinned, come to his knowledge; he shall bring his offering, a kid of the goats, a male without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 24, E'And he shall lay his hand upon the head of the goat, and kill it in the place where they kill the burnt offering before the LORD: it is a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 25, E'And the priest shall take of the blood of the sin offering with his finger, and put it upon the horns of the altar of burnt offering, and shall pour out his blood at the bottom of the altar of burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 26, E'And he shall burn all his fat upon the altar, as the fat of the sacrifice of peace offerings: and the priest shall make an atonement for him as concerning his sin, and it shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 27, E'And if any one of the common people sin through ignorance, while he doeth somewhat against any of the commandments of the LORD concerning things which ought not to be done, and be guilty;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 28, E'Or if his sin, which he hath sinned, come to his knowledge: then he shall bring his offering, a kid of the goats, a female without blemish, for his sin which he hath sinned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 29, E'And he shall lay his hand upon the head of the sin offering, and slay the sin offering in the place of the burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 30, E'And the priest shall take of the blood thereof with his finger, and put it upon the horns of the altar of burnt offering, and shall pour out all the blood thereof at the bottom of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 31, E'And he shall take away all the fat thereof, as the fat is taken away from off the sacrifice of peace offerings; and the priest shall burn it upon the altar for a sweet savour unto the LORD; and the priest shall make an atonement for him, and it shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 32, E'And if he bring a lamb for a sin offering, he shall bring it a female without blemish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 33, E'And he shall lay his hand upon the head of the sin offering, and slay it for a sin offering in the place where they kill the burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 34, E'And the priest shall take of the blood of the sin offering with his finger, and put it upon the horns of the altar of burnt offering, and shall pour out all the blood thereof at the bottom of the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 4, 35, E'And he shall take away all the fat thereof, as the fat of the lamb is taken away from the sacrifice of the peace offerings; and the priest shall burn them upon the altar, according to the offerings made by fire unto the LORD: and the priest shall make an atonement for his sin that he hath committed, and it shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 1, E'And if a soul sin, and hear the voice of swearing, and is a witness, whether he hath seen or known of it; if he do not utter it, then he shall bear his iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 2, E'Or if a soul touch any unclean thing, whether it be a carcase of an unclean beast, or a carcase of unclean cattle, or the carcase of unclean creeping things, and if it be hidden from him; he also shall be unclean, and guilty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 3, E'Or if he touch the uncleanness of man, whatsoever uncleanness it be that a man shall be defiled withal, and it be hid from him; when he knoweth of it, then he shall be guilty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 4, E'Or if a soul swear, pronouncing with his lips to do evil, or to do good, whatsoever it be that a man shall pronounce with an oath, and it be hid from him; when he knoweth of it, then he shall be guilty in one of these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 5, E'And it shall be, when he shall be guilty in one of these things, that he shall confess that he hath sinned in that thing:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 6, E'And he shall bring his trespass offering unto the LORD for his sin which he hath sinned, a female from the flock, a lamb or a kid of the goats, for a sin offering; and the priest shall make an atonement for him concerning his sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 7, E'And if he be not able to bring a lamb, then he shall bring for his trespass, which he hath committed, two turtledoves, or two young pigeons, unto the LORD; one for a sin offering, and the other for a burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 8, E'And he shall bring them unto the priest, who shall offer that which is for the sin offering first, and wring off his head from his neck, but shall not divide it asunder:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 9, E'And he shall sprinkle of the blood of the sin offering upon the side of the altar; and the rest of the blood shall be wrung out at the bottom of the altar: it is a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 10, E'And he shall offer the second for a burnt offering, according to the manner: and the priest shall make an atonement for him for his sin which he hath sinned, and it shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 11, E'But if he be not able to bring two turtledoves, or two young pigeons, then he that sinned shall bring for his offering the tenth part of an ephah of fine flour for a sin offering; he shall put no oil upon it, neither shall he put any frankincense thereon: for it is a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 12, E'Then shall he bring it to the priest, and the priest shall take his handful of it, even a memorial thereof, and burn it on the altar, according to the offerings made by fire unto the LORD: it is a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 13, E'And the priest shall make an atonement for him as touching his sin that he hath sinned in one of these, and it shall be forgiven him: and the remnant shall be the priest’s, as a meat offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 14, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 15, E'If a soul commit a trespass, and sin through ignorance, in the holy things of the LORD; then he shall bring for his trespass unto the LORD a ram without blemish out of the flocks, with thy estimation by shekels of silver, after the shekel of the sanctuary, for a trespass offering:')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 16, E'And he shall make amends for the harm that he hath done in the holy thing, and shall add the fifth part thereto, and give it unto the priest: and the priest shall make an atonement for him with the ram of the trespass offering, and it shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 17, E'And if a soul sin, and commit any of these things which are forbidden to be done by the commandments of the LORD; though he wist it not, yet is he guilty, and shall bear his iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 18, E'And he shall bring a ram without blemish out of the flock, with thy estimation, for a trespass offering, unto the priest: and the priest shall make an atonement for him concerning his ignorance wherein he erred and wist it not, and it shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 5, 19, E'It is a trespass offering: he hath certainly trespassed against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 2, E'If a soul sin, and commit a trespass against the LORD, and lie unto his neighbour in that which was delivered him to keep, or in fellowship, or in a thing taken away by violence, or hath deceived his neighbour;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 3, E'Or have found that which was lost, and lieth concerning it, and sweareth falsely; in any of all these that a man doeth, sinning therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 4, E'Then it shall be, because he hath sinned, and is guilty, that he shall restore that which he took violently away, or the thing which he hath deceitfully gotten, or that which was delivered him to keep, or the lost thing which he found,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 5, E'Or all that about which he hath sworn falsely; he shall even restore it in the principal, and shall add the fifth part more thereto, and give it unto him to whom it appertaineth, in the day of his trespass offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 6, E'And he shall bring his trespass offering unto the LORD, a ram without blemish out of the flock, with thy estimation, for a trespass offering, unto the priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 7, E'And the priest shall make an atonement for him before the LORD: and it shall be forgiven him for any thing of all that he hath done in trespassing therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 8, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 9, E'Command Aaron and his sons, saying, This is the law of the burnt offering: It is the burnt offering, because of the burning upon the altar all night unto the morning, and the fire of the altar shall be burning in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 10, E'And the priest shall put on his linen garment, and his linen breeches shall he put upon his flesh, and take up the ashes which the fire hath consumed with the burnt offering on the altar, and he shall put them beside the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 11, E'And he shall put off his garments, and put on other garments, and carry forth the ashes without the camp unto a clean place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 12, E'And the fire upon the altar shall be burning in it; it shall not be put out: and the priest shall burn wood on it every morning, and lay the burnt offering in order upon it; and he shall burn thereon the fat of the peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 13, E'The fire shall ever be burning upon the altar; it shall never go out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 14, E'And this is the law of the meat offering: the sons of Aaron shall offer it before the LORD, before the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 15, E'And he shall take of it his handful, of the flour of the meat offering, and of the oil thereof, and all the frankincense which is upon the meat offering, and shall burn it upon the altar for a sweet savour, even the memorial of it, unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 16, E'And the remainder thereof shall Aaron and his sons eat: with unleavened bread shall it be eaten in the holy place; in the court of the tabernacle of the congregation they shall eat it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 17, E'It shall not be baken with leaven. I have given it unto them for their portion of my offerings made by fire; it is most holy, as is the sin offering, and as the trespass offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 18, E'All the males among the children of Aaron shall eat of it. It shall be a statute for ever in your generations concerning the offerings of the LORD made by fire: every one that toucheth them shall be holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 19, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 20, E'This is the offering of Aaron and of his sons, which they shall offer unto the LORD in the day when he is anointed; the tenth part of an ephah of fine flour for a meat offering perpetual, half of it in the morning, and half thereof at night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 21, E'In a pan it shall be made with oil; and when it is baken, thou shalt bring it in: and the baken pieces of the meat offering shalt thou offer for a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 22, E'And the priest of his sons that is anointed in his stead shall offer it: it is a statute for ever unto the LORD; it shall be wholly burnt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 23, E'For every meat offering for the priest shall be wholly burnt: it shall not be eaten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 24, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 25, E'Speak unto Aaron and to his sons, saying, This is the law of the sin offering: In the place where the burnt offering is killed shall the sin offering be killed before the LORD: it is most holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 26, E'The priest that offereth it for sin shall eat it: in the holy place shall it be eaten, in the court of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 27, E'Whatsoever shall touch the flesh thereof shall be holy: and when there is sprinkled of the blood thereof upon any garment, thou shalt wash that whereon it was sprinkled in the holy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 28, E'But the earthen vessel wherein it is sodden shall be broken: and if it be sodden in a brasen pot, it shall be both scoured, and rinsed in water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 29, E'All the males among the priests shall eat thereof: it is most holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 6, 30, E'And no sin offering, whereof any of the blood is brought into the tabernacle of the congregation to reconcile withal in the holy place, shall be eaten: it shall be burnt in the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 1, E'Likewise this is the law of the trespass offering: it is most holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 2, E'In the place where they kill the burnt offering shall they kill the trespass offering: and the blood thereof shall he sprinkle round about upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 3, E'And he shall offer of it all the fat thereof; the rump, and the fat that covereth the inwards,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 4, E'And the two kidneys, and the fat that is on them, which is by the flanks, and the caul that is above the liver, with the kidneys, it shall he take away:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 5, E'And the priest shall burn them upon the altar for an offering made by fire unto the LORD: it is a trespass offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 6, E'Every male among the priests shall eat thereof: it shall be eaten in the holy place: it is most holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 7, E'As the sin offering is, so is the trespass offering: there is one law for them: the priest that maketh atonement therewith shall have it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 8, E'And the priest that offereth any man’s burnt offering, even the priest shall have to himself the skin of the burnt offering which he hath offered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 9, E'And all the meat offering that is baken in the oven, and all that is dressed in the fryingpan, and in the pan, shall be the priest’s that offereth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 10, E'And every meat offering, mingled with oil, and dry, shall all the sons of Aaron have, one as much as another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 11, E'And this is the law of the sacrifice of peace offerings, which he shall offer unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 12, E'If he offer it for a thanksgiving, then he shall offer with the sacrifice of thanksgiving unleavened cakes mingled with oil, and unleavened wafers anointed with oil, and cakes mingled with oil, of fine flour, fried.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 13, E'Besides the cakes, he shall offer for his offering leavened bread with the sacrifice of thanksgiving of his peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 14, E'And of it he shall offer one out of the whole oblation for an heave offering unto the LORD, and it shall be the priest’s that sprinkleth the blood of the peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 15, E'And the flesh of the sacrifice of his peace offerings for thanksgiving shall be eaten the same day that it is offered; he shall not leave any of it until the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 16, E'But if the sacrifice of his offering be a vow, or a voluntary offering, it shall be eaten the same day that he offereth his sacrifice: and on the morrow also the remainder of it shall be eaten:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 17, E'But the remainder of the flesh of the sacrifice on the third day shall be burnt with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 18, E'And if any of the flesh of the sacrifice of his peace offerings be eaten at all on the third day, it shall not be accepted, neither shall it be imputed unto him that offereth it: it shall be an abomination, and the soul that eateth of it shall bear his iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 19, E'And the flesh that toucheth any unclean thing shall not be eaten; it shall be burnt with fire: and as for the flesh, all that be clean shall eat thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 20, E'But the soul that eateth of the flesh of the sacrifice of peace offerings, that pertain unto the LORD, having his uncleanness upon him, even that soul shall be cut off from his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 21, E'Moreover the soul that shall touch any unclean thing, as the uncleanness of man, or any unclean beast, or any abominable unclean thing, and eat of the flesh of the sacrifice of peace offerings, which pertain unto the LORD, even that soul shall be cut off from his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 22, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 23, E'Speak unto the children of Israel, saying, Ye shall eat no manner of fat, of ox, or of sheep, or of goat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 24, E'And the fat of the beast that dieth of itself, and the fat of that which is torn with beasts, may be used in any other use: but ye shall in no wise eat of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 25, E'For whosoever eateth the fat of the beast, of which men offer an offering made by fire unto the LORD, even the soul that eateth it shall be cut off from his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 26, E'Moreover ye shall eat no manner of blood, whether it be of fowl or of beast, in any of your dwellings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 27, E'Whatsoever soul it be that eateth any manner of blood, even that soul shall be cut off from his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 28, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 29, E'Speak unto the children of Israel, saying, He that offereth the sacrifice of his peace offerings unto the LORD shall bring his oblation unto the LORD of the sacrifice of his peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 30, E'His own hands shall bring the offerings of the LORD made by fire, the fat with the breast, it shall he bring, that the breast may be waved for a wave offering before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 31, E'And the priest shall burn the fat upon the altar: but the breast shall be Aaron’s and his sons’.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 32, E'And the right shoulder shall ye give unto the priest for an heave offering of the sacrifices of your peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 33, E'He among the sons of Aaron, that offereth the blood of the peace offerings, and the fat, shall have the right shoulder for his part.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 34, E'For the wave breast and the heave shoulder have I taken of the children of Israel from off the sacrifices of their peace offerings, and have given them unto Aaron the priest and unto his sons by a statute for ever from among the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 35, E'This is the portion of the anointing of Aaron, and of the anointing of his sons, out of the offerings of the LORD made by fire, in the day when he presented them to minister unto the LORD in the priest’s office;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 36, E'Which the LORD commanded to be given them of the children of Israel, in the day that he anointed them, by a statute for ever throughout their generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 37, E'This is the law of the burnt offering, of the meat offering, and of the sin offering, and of the trespass offering, and of the consecrations, and of the sacrifice of the peace offerings;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 7, 38, E'Which the LORD commanded Moses in mount Sinai, in the day that he commanded the children of Israel to offer their oblations unto the LORD, in the wilderness of Sinai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 2, E'Take Aaron and his sons with him, and the garments, and the anointing oil, and a bullock for the sin offering, and two rams, and a basket of unleavened bread;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 3, E'And gather thou all the congregation together unto the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 4, E'And Moses did as the LORD commanded him; and the assembly was gathered together unto the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 5, E'And Moses said unto the congregation, This is the thing which the LORD commanded to be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 6, E'And Moses brought Aaron and his sons, and washed them with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 7, E'And he put upon him the coat, and girded him with the girdle, and clothed him with the robe, and put the ephod upon him, and he girded him with the curious girdle of the ephod, and bound it unto him therewith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 8, E'And he put the breastplate upon him: also he put in the breastplate the Urim and the Thummim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 9, E'And he put the mitre upon his head; also upon the mitre, even upon his forefront, did he put the golden plate, the holy crown; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 10, E'And Moses took the anointing oil, and anointed the tabernacle and all that was therein, and sanctified them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 11, E'And he sprinkled thereof upon the altar seven times, and anointed the altar and all his vessels, both the laver and his foot, to sanctify them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 12, E'And he poured of the anointing oil upon Aaron’s head, and anointed him, to sanctify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 13, E'And Moses brought Aaron’s sons, and put coats upon them, and girded them with girdles, and put bonnets upon them; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 14, E'And he brought the bullock for the sin offering: and Aaron and his sons laid their hands upon the head of the bullock for the sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 15, E'And he slew it; and Moses took the blood, and put it upon the horns of the altar round about with his finger, and purified the altar, and poured the blood at the bottom of the altar, and sanctified it, to make reconciliation upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 16, E'And he took all the fat that was upon the inwards, and the caul above the liver, and the two kidneys, and their fat, and Moses burned it upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 17, E'But the bullock, and his hide, his flesh, and his dung, he burnt with fire without the camp; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 18, E'And he brought the ram for the burnt offering: and Aaron and his sons laid their hands upon the head of the ram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 19, E'And he killed it; and Moses sprinkled the blood upon the altar round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 20, E'And he cut the ram into pieces; and Moses burnt the head, and the pieces, and the fat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 21, E'And he washed the inwards and the legs in water; and Moses burnt the whole ram upon the altar: it was a burnt sacrifice for a sweet savour, and an offering made by fire unto the LORD; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 22, E'And he brought the other ram, the ram of consecration: and Aaron and his sons laid their hands upon the head of the ram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 23, E'And he slew it; and Moses took of the blood of it, and put it upon the tip of Aaron’s right ear, and upon the thumb of his right hand, and upon the great toe of his right foot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 24, E'And he brought Aaron’s sons, and Moses put of the blood upon the tip of their right ear, and upon the thumbs of their right hands, and upon the great toes of their right feet: and Moses sprinkled the blood upon the altar round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 25, E'And he took the fat, and the rump, and all the fat that was upon the inwards, and the caul above the liver, and the two kidneys, and their fat, and the right shoulder:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 26, E'And out of the basket of unleavened bread, that was before the LORD, he took one unleavened cake, and a cake of oiled bread, and one wafer, and put them on the fat, and upon the right shoulder:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 27, E'And he put all upon Aaron’s hands, and upon his sons’ hands, and waved them for a wave offering before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 28, E'And Moses took them from off their hands, and burnt them on the altar upon the burnt offering: they were consecrations for a sweet savour: it is an offering made by fire unto the LORD.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 29, E'And Moses took the breast, and waved it for a wave offering before the LORD: for of the ram of consecration it was Moses’ part; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 30, E'And Moses took of the anointing oil, and of the blood which was upon the altar, and sprinkled it upon Aaron, and upon his garments, and upon his sons, and upon his sons’ garments with him; and sanctified Aaron, and his garments, and his sons, and his sons’ garments with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 31, E'And Moses said unto Aaron and to his sons, Boil the flesh at the door of the tabernacle of the congregation: and there eat it with the bread that is in the basket of consecrations, as I commanded, saying, Aaron and his sons shall eat it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 32, E'And that which remaineth of the flesh and of the bread shall ye burn with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 33, E'And ye shall not go out of the door of the tabernacle of the congregation in seven days, until the days of your consecration be at an end: for seven days shall he consecrate you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 34, E'As he hath done this day, so the LORD hath commanded to do, to make an atonement for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 35, E'Therefore shall ye abide at the door of the tabernacle of the congregation day and night seven days, and keep the charge of the LORD, that ye die not: for so I am commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 8, 36, E'So Aaron and his sons did all things which the LORD commanded by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 1, E'And it came to pass on the eighth day, that Moses called Aaron and his sons, and the elders of Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 2, E'And he said unto Aaron, Take thee a young calf for a sin offering, and a ram for a burnt offering, without blemish, and offer them before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 3, E'And unto the children of Israel thou shalt speak, saying, Take ye a kid of the goats for a sin offering; and a calf and a lamb, both of the first year, without blemish, for a burnt offering;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 4, E'Also a bullock and a ram for peace offerings, to sacrifice before the LORD; and a meat offering mingled with oil: for to day the LORD will appear unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 5, E'And they brought that which Moses commanded before the tabernacle of the congregation: and all the congregation drew near and stood before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 6, E'And Moses said, This is the thing which the LORD commanded that ye should do: and the glory of the LORD shall appear unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 7, E'And Moses said unto Aaron, Go unto the altar, and offer thy sin offering, and thy burnt offering, and make an atonement for thyself, and for the people: and offer the offering of the people, and make an atonement for them; as the LORD commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 8, E'Aaron therefore went unto the altar, and slew the calf of the sin offering, which was for himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 9, E'And the sons of Aaron brought the blood unto him: and he dipped his finger in the blood, and put it upon the horns of the altar, and poured out the blood at the bottom of the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 10, E'But the fat, and the kidneys, and the caul above the liver of the sin offering, he burnt upon the altar; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 11, E'And the flesh and the hide he burnt with fire without the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 12, E'And he slew the burnt offering; and Aaron’s sons presented unto him the blood, which he sprinkled round about upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 13, E'And they presented the burnt offering unto him, with the pieces thereof, and the head: and he burnt them upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 14, E'And he did wash the inwards and the legs, and burnt them upon the burnt offering on the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 15, E'And he brought the people’s offering, and took the goat, which was the sin offering for the people, and slew it, and offered it for sin, as the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 16, E'And he brought the burnt offering, and offered it according to the manner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 17, E'And he brought the meat offering, and took an handful thereof, and burnt it upon the altar, beside the burnt sacrifice of the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 18, E'He slew also the bullock and the ram for a sacrifice of peace offerings, which was for the people: and Aaron’s sons presented unto him the blood, which he sprinkled upon the altar round about,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 19, E'And the fat of the bullock and of the ram, the rump, and that which covereth the inwards, and the kidneys, and the caul above the liver:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 20, E'And they put the fat upon the breasts, and he burnt the fat upon the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 21, E'And the breasts and the right shoulder Aaron waved for a wave offering before the LORD; as Moses commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 22, E'And Aaron lifted up his hand toward the people, and blessed them, and came down from offering of the sin offering, and the burnt offering, and peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 23, E'And Moses and Aaron went into the tabernacle of the congregation, and came out, and blessed the people: and the glory of the LORD appeared unto all the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 9, 24, E'And there came a fire out from before the LORD, and consumed upon the altar the burnt offering and the fat: which when all the people saw, they shouted, and fell on their faces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 1, E'And Nadab and Abihu, the sons of Aaron, took either of them his censer, and put fire therein, and put incense thereon, and offered strange fire before the LORD, which he commanded them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 2, E'And there went out fire from the LORD, and devoured them, and they died before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 3, E'Then Moses said unto Aaron, This is it that the LORD spake, saying, I will be sanctified in them that come nigh me, and before all the people I will be glorified. And Aaron held his peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 4, E'And Moses called Mishael and Elzaphan, the sons of Uzziel the uncle of Aaron, and said unto them, Come near, carry your brethren from before the sanctuary out of the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 5, E'So they went near, and carried them in their coats out of the camp; as Moses had said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 6, E'And Moses said unto Aaron, and unto Eleazar and unto Ithamar, his sons, Uncover not your heads, neither rend your clothes; lest ye die, and lest wrath come upon all the people: but let your brethren, the whole house of Israel, bewail the burning which the LORD hath kindled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 7, E'And ye shall not go out from the door of the tabernacle of the congregation, lest ye die: for the anointing oil of the LORD is upon you. And they did according to the word of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 8, E'And the LORD spake unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 9, E'Do not drink wine nor strong drink, thou, nor thy sons with thee, when ye go into the tabernacle of the congregation, lest ye die: it shall be a statute for ever throughout your generations:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 10, E'And that ye may put difference between holy and unholy, and between unclean and clean;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 11, E'And that ye may teach the children of Israel all the statutes which the LORD hath spoken unto them by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 12, E'And Moses spake unto Aaron, and unto Eleazar and unto Ithamar, his sons that were left, Take the meat offering that remaineth of the offerings of the LORD made by fire, and eat it without leaven beside the altar: for it is most holy:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 13, E'And ye shall eat it in the holy place, because it is thy due, and thy sons’ due, of the sacrifices of the LORD made by fire: for so I am commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 14, E'And the wave breast and heave shoulder shall ye eat in a clean place; thou, and thy sons, and thy daughters with thee: for they be thy due, and thy sons’ due, which are given out of the sacrifices of peace offerings of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 15, E'The heave shoulder and the wave breast shall they bring with the offerings made by fire of the fat, to wave it for a wave offering before the LORD; and it shall be thine, and thy sons’ with thee, by a statute for ever; as the LORD hath commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 16, E'And Moses diligently sought the goat of the sin offering, and, behold, it was burnt: and he was angry with Eleazar and Ithamar, the sons of Aaron which were left alive, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 17, E'Wherefore have ye not eaten the sin offering in the holy place, seeing it is most holy, and God hath given it you to bear the iniquity of the congregation, to make atonement for them before the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 18, E'Behold, the blood of it was not brought in within the holy place: ye should indeed have eaten it in the holy place, as I commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 19, E'And Aaron said unto Moses, Behold, this day have they offered their sin offering and their burnt offering before the LORD; and such things have befallen me: and if I had eaten the sin offering to day, should it have been accepted in the sight of the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 10, 20, E'And when Moses heard that, he was content.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 1, E'And the LORD spake unto Moses and to Aaron, saying unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 2, E'Speak unto the children of Israel, saying, These are the beasts which ye shall eat among all the beasts that are on the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 3, E'Whatsoever parteth the hoof, and is clovenfooted, and cheweth the cud, among the beasts, that shall ye eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 4, E'Nevertheless these shall ye not eat of them that chew the cud, or of them that divide the hoof: as the camel, because he cheweth the cud, but divideth not the hoof; he is unclean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 5, E'And the coney, because he cheweth the cud, but divideth not the hoof; he is unclean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 6, E'And the hare, because he cheweth the cud, but divideth not the hoof; he is unclean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 7, E'And the swine, though he divide the hoof, and be clovenfooted, yet he cheweth not the cud; he is unclean to you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 8, E'Of their flesh shall ye not eat, and their carcase shall ye not touch; they are unclean to you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 9, E'These shall ye eat of all that are in the waters: whatsoever hath fins and scales in the waters, in the seas, and in the rivers, them shall ye eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 10, E'And all that have not fins and scales in the seas, and in the rivers, of all that move in the waters, and of any living thing which is in the waters, they shall be an abomination unto you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 11, E'They shall be even an abomination unto you; ye shall not eat of their flesh, but ye shall have their carcases in abomination.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 12, E'Whatsoever hath no fins nor scales in the waters, that shall be an abomination unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 13, E'And these are they which ye shall have in abomination among the fowls; they shall not be eaten, they are an abomination: the eagle, and the ossifrage, and the ospray,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 14, E'And the vulture, and the kite after his kind;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 15, E'Every raven after his kind;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 16, E'And the owl, and the night hawk, and the cuckow, and the hawk after his kind,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 17, E'And the little owl, and the cormorant, and the great owl,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 18, E'And the swan, and the pelican, and the gier eagle,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 19, E'And the stork, the heron after her kind, and the lapwing, and the bat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 20, E'All fowls that creep, going upon all four, shall be an abomination unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 21, E'Yet these may ye eat of every flying creeping thing that goeth upon all four, which have legs above their feet, to leap withal upon the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 22, E'Even these of them ye may eat; the locust after his kind, and the bald locust after his kind, and the beetle after his kind, and the grasshopper after his kind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 23, E'But all other flying creeping things, which have four feet, shall be an abomination unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 24, E'And for these ye shall be unclean: whosoever toucheth the carcase of them shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 25, E'And whosoever beareth ought of the carcase of them shall wash his clothes, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 26, E'The carcases of every beast which divideth the hoof, and is not clovenfooted, nor cheweth the cud, are unclean unto you: every one that toucheth them shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 27, E'And whatsoever goeth upon his paws, among all manner of beasts that go on all four, those are unclean unto you: whoso toucheth their carcase shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 28, E'And he that beareth the carcase of them shall wash his clothes, and be unclean until the even: they are unclean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 29, E'These also shall be unclean unto you among the creeping things that creep upon the earth; the weasel, and the mouse, and the tortoise after his kind,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 30, E'And the ferret, and the chameleon, and the lizard, and the snail, and the mole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 31, E'These are unclean to you among all that creep: whosoever doth touch them, when they be dead, shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 32, E'And upon whatsoever any of them, when they are dead, doth fall, it shall be unclean; whether it be any vessel of wood, or raiment, or skin, or sack, whatsoever vessel it be, wherein any work is done, it must be put into water, and it shall be unclean until the even; so it shall be cleansed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 33, E'And every earthen vessel, whereinto any of them falleth, whatsoever is in it shall be unclean; and ye shall break it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 34, E'Of all meat which may be eaten, that on which such water cometh shall be unclean: and all drink that may be drunk in every such vessel shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 35, E'And every thing whereupon any part of their carcase falleth shall be unclean; whether it be oven, or ranges for pots, they shall be broken down: for they are unclean, and shall be unclean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 36, E'Nevertheless a fountain or pit, wherein there is plenty of water, shall be clean: but that which toucheth their carcase shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 37, E'And if any part of their carcase fall upon any sowing seed which is to be sown, it shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 38, E'But if any water be put upon the seed, and any part of their carcase fall thereon, it shall be unclean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 39, E'And if any beast, of which ye may eat, die; he that toucheth the carcase thereof shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 40, E'And he that eateth of the carcase of it shall wash his clothes, and be unclean until the even: he also that beareth the carcase of it shall wash his clothes, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 41, E'And every creeping thing that creepeth upon the earth shall be an abomination; it shall not be eaten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 42, E'Whatsoever goeth upon the belly, and whatsoever goeth upon all four, or whatsoever hath more feet among all creeping things that creep upon the earth, them ye shall not eat; for they are an abomination.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 43, E'Ye shall not make yourselves abominable with any creeping thing that creepeth, neither shall ye make yourselves unclean with them, that ye should be defiled thereby.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 44, E'For I am the LORD your God: ye shall therefore sanctify yourselves, and ye shall be holy; for I am holy: neither shall ye defile yourselves with any manner of creeping thing that creepeth upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 45, E'For I am the LORD that bringeth you up out of the land of Egypt, to be your God: ye shall therefore be holy, for I am holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 46, E'This is the law of the beasts, and of the fowl, and of every living creature that moveth in the waters, and of every creature that creepeth upon the earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 11, 47, E'To make a difference between the unclean and the clean, and between the beast that may be eaten and the beast that may not be eaten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 1, E'And the LORD spake unto Moses, saying,')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 2, E'Speak unto the children of Israel, saying, If a woman have conceived seed, and born a man child: then she shall be unclean seven days; according to the days of the separation for her infirmity shall she be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 3, E'And in the eighth day the flesh of his foreskin shall be circumcised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 4, E'And she shall then continue in the blood of her purifying three and thirty days; she shall touch no hallowed thing, nor come into the sanctuary, until the days of her purifying be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 5, E'But if she bear a maid child, then she shall be unclean two weeks, as in her separation: and she shall continue in the blood of her purifying threescore and six days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 6, E'And when the days of her purifying are fulfilled, for a son, or for a daughter, she shall bring a lamb of the first year for a burnt offering, and a young pigeon, or a turtledove, for a sin offering, unto the door of the tabernacle of the congregation, unto the priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 7, E'Who shall offer it before the LORD, and make an atonement for her; and she shall be cleansed from the issue of her blood. This is the law for her that hath born a male or a female.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 12, 8, E'And if she be not able to bring a lamb, then she shall bring two turtles, or two young pigeons; the one for the burnt offering, and the other for a sin offering: and the priest shall make an atonement for her, and she shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 1, E'And the LORD spake unto Moses and Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 2, E'When a man shall have in the skin of his flesh a rising, a scab, or bright spot, and it be in the skin of his flesh like the plague of leprosy; then he shall be brought unto Aaron the priest, or unto one of his sons the priests:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 3, E'And the priest shall look on the plague in the skin of the flesh: and when the hair in the plague is turned white, and the plague in sight be deeper than the skin of his flesh, it is a plague of leprosy: and the priest shall look on him, and pronounce him unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 4, E'If the bright spot be white in the skin of his flesh, and in sight be not deeper than the skin, and the hair thereof be not turned white; then the priest shall shut up him that hath the plague seven days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 5, E'And the priest shall look on him the seventh day: and, behold, if the plague in his sight be at a stay, and the plague spread not in the skin; then the priest shall shut him up seven days more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 6, E'And the priest shall look on him again the seventh day: and, behold, if the plague be somewhat dark, and the plague spread not in the skin, the priest shall pronounce him clean: it is but a scab: and he shall wash his clothes, and be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 7, E'But if the scab spread much abroad in the skin, after that he hath been seen of the priest for his cleansing, he shall be seen of the priest again:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 8, E'And if the priest see that, behold, the scab spreadeth in the skin, then the priest shall pronounce him unclean: it is a leprosy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 9, E'When the plague of leprosy is in a man, then he shall be brought unto the priest;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 10, E'And the priest shall see him: and, behold, if the rising be white in the skin, and it have turned the hair white, and there be quick raw flesh in the rising;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 11, E'It is an old leprosy in the skin of his flesh, and the priest shall pronounce him unclean, and shall not shut him up: for he is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 12, E'And if a leprosy break out abroad in the skin, and the leprosy cover all the skin of him that hath the plague from his head even to his foot, wheresoever the priest looketh;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 13, E'Then the priest shall consider: and, behold, if the leprosy have covered all his flesh, he shall pronounce him clean that hath the plague: it is all turned white: he is clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 14, E'But when raw flesh appeareth in him, he shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 15, E'And the priest shall see the raw flesh, and pronounce him to be unclean: for the raw flesh is unclean: it is a leprosy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 16, E'Or if the raw flesh turn again, and be changed unto white, he shall come unto the priest;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 17, E'And the priest shall see him: and, behold, if the plague be turned into white; then the priest shall pronounce him clean that hath the plague: he is clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 18, E'The flesh also, in which, even in the skin thereof, was a boil, and is healed,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 19, E'And in the place of the boil there be a white rising, or a bright spot, white, and somewhat reddish, and it be shewed to the priest;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 20, E'And if, when the priest seeth it, behold, it be in sight lower than the skin, and the hair thereof be turned white; the priest shall pronounce him unclean: it is a plague of leprosy broken out of the boil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 21, E'But if the priest look on it, and, behold, there be no white hairs therein, and if it be not lower than the skin, but be somewhat dark; then the priest shall shut him up seven days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 22, E'And if it spread much abroad in the skin, then the priest shall pronounce him unclean: it is a plague.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 23, E'But if the bright spot stay in his place, and spread not, it is a burning boil; and the priest shall pronounce him clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 24, E'Or if there be any flesh, in the skin whereof there is a hot burning, and the quick flesh that burneth have a white bright spot, somewhat reddish, or white;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 25, E'Then the priest shall look upon it: and, behold, if the hair in the bright spot be turned white, and it be in sight deeper than the skin; it is a leprosy broken out of the burning: wherefore the priest shall pronounce him unclean: it is the plague of leprosy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 26, E'But if the priest look on it, and, behold, there be no white hair in the bright spot, and it be no lower than the other skin, but be somewhat dark; then the priest shall shut him up seven days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 27, E'And the priest shall look upon him the seventh day: and if it be spread much abroad in the skin, then the priest shall pronounce him unclean: it is the plague of leprosy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 28, E'And if the bright spot stay in his place, and spread not in the skin, but it be somewhat dark; it is a rising of the burning, and the priest shall pronounce him clean: for it is an inflammation of the burning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 29, E'If a man or woman have a plague upon the head or the beard;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 30, E'Then the priest shall see the plague: and, behold, if it be in sight deeper than the skin; and there be in it a yellow thin hair; then the priest shall pronounce him unclean: it is a dry scall, even a leprosy upon the head or beard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 31, E'And if the priest look on the plague of the scall, and, behold, it be not in sight deeper than the skin, and that there is no black hair in it; then the priest shall shut up him that hath the plague of the scall seven days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 32, E'And in the seventh day the priest shall look on the plague: and, behold, if the scall spread not, and there be in it no yellow hair, and the scall be not in sight deeper than the skin;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 33, E'He shall be shaven, but the scall shall he not shave; and the priest shall shut up him that hath the scall seven days more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 34, E'And in the seventh day the priest shall look on the scall: and, behold, if the scall be not spread in the skin, nor be in sight deeper than the skin; then the priest shall pronounce him clean: and he shall wash his clothes, and be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 35, E'But if the scall spread much in the skin after his cleansing;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 36, E'Then the priest shall look on him: and, behold, if the scall be spread in the skin, the priest shall not seek for yellow hair; he is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 37, E'But if the scall be in his sight at a stay, and that there is black hair grown up therein; the scall is healed, he is clean: and the priest shall pronounce him clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 38, E'If a man also or a woman have in the skin of their flesh bright spots, even white bright spots;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 39, E'Then the priest shall look: and, behold, if the bright spots in the skin of their flesh be darkish white; it is a freckled spot that groweth in the skin; he is clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 40, E'And the man whose hair is fallen off his head, he is bald; yet is he clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 41, E'And he that hath his hair fallen off from the part of his head toward his face, he is forehead bald: yet is he clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 42, E'And if there be in the bald head, or bald forehead, a white reddish sore; it is a leprosy sprung up in his bald head, or his bald forehead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 43, E'Then the priest shall look upon it: and, behold, if the rising of the sore be white reddish in his bald head, or in his bald forehead, as the leprosy appeareth in the skin of the flesh;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 44, E'He is a leprous man, he is unclean: the priest shall pronounce him utterly unclean; his plague is in his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 45, E'And the leper in whom the plague is, his clothes shall be rent, and his head bare, and he shall put a covering upon his upper lip, and shall cry, Unclean, unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 46, E'All the days wherein the plague shall be in him he shall be defiled; he is unclean: he shall dwell alone; without the camp shall his habitation be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 47, E'The garment also that the plague of leprosy is in, whether it be a woollen garment, or a linen garment;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 48, E'Whether it be in the warp, or woof; of linen, or of woollen; whether in a skin, or in any thing made of skin;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 49, E'And if the plague be greenish or reddish in the garment, or in the skin, either in the warp, or in the woof, or in any thing of skin; it is a plague of leprosy, and shall be shewed unto the priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 50, E'And the priest shall look upon the plague, and shut up it that hath the plague seven days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 51, E'And he shall look on the plague on the seventh day: if the plague be spread in the garment, either in the warp, or in the woof, or in a skin, or in any work that is made of skin; the plague is a fretting leprosy; it is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 52, E'He shall therefore burn that garment, whether warp or woof, in woollen or in linen, or any thing of skin, wherein the plague is: for it is a fretting leprosy; it shall be burnt in the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 53, E'And if the priest shall look, and, behold, the plague be not spread in the garment, either in the warp, or in the woof, or in any thing of skin;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 54, E'Then the priest shall command that they wash the thing wherein the plague is, and he shall shut it up seven days more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 55, E'And the priest shall look on the plague, after that it is washed: and, behold, if the plague have not changed his colour, and the plague be not spread; it is unclean; thou shalt burn it in the fire; it is fret inward, whether it be bare within or without.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 56, E'And if the priest look, and, behold, the plague be somewhat dark after the washing of it; then he shall rend it out of the garment, or out of the skin, or out of the warp, or out of the woof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 57, E'And if it appear still in the garment, either in the warp, or in the woof, or in any thing of skin; it is a spreading plague: thou shalt burn that wherein the plague is with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 58, E'And the garment, either warp, or woof, or whatsoever thing of skin it be, which thou shalt wash, if the plague be departed from them, then it shall be washed the second time, and shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 13, 59, E'This is the law of the plague of leprosy in a garment of woollen or linen, either in the warp, or woof, or any thing of skins, to pronounce it clean, or to pronounce it unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 2, E'This shall be the law of the leper in the day of his cleansing: He shall be brought unto the priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 3, E'And the priest shall go forth out of the camp; and the priest shall look, and, behold, if the plague of leprosy be healed in the leper;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 4, E'Then shall the priest command to take for him that is to be cleansed two birds alive and clean, and cedar wood, and scarlet, and hyssop:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 5, E'And the priest shall command that one of the birds be killed in an earthen vessel over running water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 6, E'As for the living bird, he shall take it, and the cedar wood, and the scarlet, and the hyssop, and shall dip them and the living bird in the blood of the bird that was killed over the running water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 7, E'And he shall sprinkle upon him that is to be cleansed from the leprosy seven times, and shall pronounce him clean, and shall let the living bird loose into the open field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 8, E'And he that is to be cleansed shall wash his clothes, and shave off all his hair, and wash himself in water, that he may be clean: and after that he shall come into the camp, and shall tarry abroad out of his tent seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 9, E'But it shall be on the seventh day, that he shall shave all his hair off his head and his beard and his eyebrows, even all his hair he shall shave off: and he shall wash his clothes, also he shall wash his flesh in water, and he shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 10, E'And on the eighth day he shall take two he lambs without blemish, and one ewe lamb of the first year without blemish, and three tenth deals of fine flour for a meat offering, mingled with oil, and one log of oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 11, E'And the priest that maketh him clean shall present the man that is to be made clean, and those things, before the LORD, at the door of the tabernacle of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 12, E'And the priest shall take one he lamb, and offer him for a trespass offering, and the log of oil, and wave them for a wave offering before the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 13, E'And he shall slay the lamb in the place where he shall kill the sin offering and the burnt offering, in the holy place: for as the sin offering is the priest’s, so is the trespass offering: it is most holy:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 14, E'And the priest shall take some of the blood of the trespass offering, and the priest shall put it upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 15, E'And the priest shall take some of the log of oil, and pour it into the palm of his own left hand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 16, E'And the priest shall dip his right finger in the oil that is in his left hand, and shall sprinkle of the oil with his finger seven times before the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 17, E'And of the rest of the oil that is in his hand shall the priest put upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot, upon the blood of the trespass offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 18, E'And the remnant of the oil that is in the priest’s hand he shall pour upon the head of him that is to be cleansed: and the priest shall make an atonement for him before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 19, E'And the priest shall offer the sin offering, and make an atonement for him that is to be cleansed from his uncleanness; and afterward he shall kill the burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 20, E'And the priest shall offer the burnt offering and the meat offering upon the altar: and the priest shall make an atonement for him, and he shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 21, E'And if he be poor, and cannot get so much; then he shall take one lamb for a trespass offering to be waved, to make an atonement for him, and one tenth deal of fine flour mingled with oil for a meat offering, and a log of oil;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 22, E'And two turtledoves, or two young pigeons, such as he is able to get; and the one shall be a sin offering, and the other a burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 23, E'And he shall bring them on the eighth day for his cleansing unto the priest, unto the door of the tabernacle of the congregation, before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 24, E'And the priest shall take the lamb of the trespass offering, and the log of oil, and the priest shall wave them for a wave offering before the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 25, E'And he shall kill the lamb of the trespass offering, and the priest shall take some of the blood of the trespass offering, and put it upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 26, E'And the priest shall pour of the oil into the palm of his own left hand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 27, E'And the priest shall sprinkle with his right finger some of the oil that is in his left hand seven times before the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 28, E'And the priest shall put of the oil that is in his hand upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot, upon the place of the blood of the trespass offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 29, E'And the rest of the oil that is in the priest’s hand he shall put upon the head of him that is to be cleansed, to make an atonement for him before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 30, E'And he shall offer the one of the turtledoves, or of the young pigeons, such as he can get;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 31, E'Even such as he is able to get, the one for a sin offering, and the other for a burnt offering, with the meat offering: and the priest shall make an atonement for him that is to be cleansed before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 32, E'This is the law of him in whom is the plague of leprosy, whose hand is not able to get that which pertaineth to his cleansing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 33, E'And the LORD spake unto Moses and unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 34, E'When ye be come into the land of Canaan, which I give to you for a possession, and I put the plague of leprosy in a house of the land of your possession;')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 35, E'And he that owneth the house shall come and tell the priest, saying, It seemeth to me there is as it were a plague in the house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 36, E'Then the priest shall command that they empty the house, before the priest go into it to see the plague, that all that is in the house be not made unclean: and afterward the priest shall go in to see the house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 37, E'And he shall look on the plague, and, behold, if the plague be in the walls of the house with hollow strakes, greenish or reddish, which in sight are lower than the wall;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 38, E'Then the priest shall go out of the house to the door of the house, and shut up the house seven days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 39, E'And the priest shall come again the seventh day, and shall look: and, behold, if the plague be spread in the walls of the house;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 40, E'Then the priest shall command that they take away the stones in which the plague is, and they shall cast them into an unclean place without the city:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 41, E'And he shall cause the house to be scraped within round about, and they shall pour out the dust that they scrape off without the city into an unclean place:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 42, E'And they shall take other stones, and put them in the place of those stones; and he shall take other morter, and shall plaister the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 43, E'And if the plague come again, and break out in the house, after that he hath taken away the stones, and after he hath scraped the house, and after it is plaistered;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 44, E'Then the priest shall come and look, and, behold, if the plague be spread in the house, it is a fretting leprosy in the house: it is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 45, E'And he shall break down the house, the stones of it, and the timber thereof, and all the morter of the house; and he shall carry them forth out of the city into an unclean place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 46, E'Moreover he that goeth into the house all the while that it is shut up shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 47, E'And he that lieth in the house shall wash his clothes; and he that eateth in the house shall wash his clothes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 48, E'And if the priest shall come in, and look upon it, and, behold, the plague hath not spread in the house, after the house was plaistered: then the priest shall pronounce the house clean, because the plague is healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 49, E'And he shall take to cleanse the house two birds, and cedar wood, and scarlet, and hyssop:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 50, E'And he shall kill the one of the birds in an earthen vessel over running water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 51, E'And he shall take the cedar wood, and the hyssop, and the scarlet, and the living bird, and dip them in the blood of the slain bird, and in the running water, and sprinkle the house seven times:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 52, E'And he shall cleanse the house with the blood of the bird, and with the running water, and with the living bird, and with the cedar wood, and with the hyssop, and with the scarlet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 53, E'But he shall let go the living bird out of the city into the open fields, and make an atonement for the house: and it shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 54, E'This is the law for all manner of plague of leprosy, and scall,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 55, E'And for the leprosy of a garment, and of a house,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 56, E'And for a rising, and for a scab, and for a bright spot:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 14, 57, E'To teach when it is unclean, and when it is clean: this is the law of leprosy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 1, E'And the LORD spake unto Moses and to Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 2, E'Speak unto the children of Israel, and say unto them, When any man hath a running issue out of his flesh, because of his issue he is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 3, E'And this shall be his uncleanness in his issue: whether his flesh run with his issue, or his flesh be stopped from his issue, it is his uncleanness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 4, E'Every bed, whereon he lieth that hath the issue, is unclean: and every thing, whereon he sitteth, shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 5, E'And whosoever toucheth his bed shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 6, E'And he that sitteth on any thing whereon he sat that hath the issue shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 7, E'And he that toucheth the flesh of him that hath the issue shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 8, E'And if he that hath the issue spit upon him that is clean; then he shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 9, E'And what saddle soever he rideth upon that hath the issue shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 10, E'And whosoever toucheth any thing that was under him shall be unclean until the even: and he that beareth any of those things shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 11, E'And whomsoever he toucheth that hath the issue, and hath not rinsed his hands in water, he shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 12, E'And the vessel of earth, that he toucheth which hath the issue, shall be broken: and every vessel of wood shall be rinsed in water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 13, E'And when he that hath an issue is cleansed of his issue; then he shall number to himself seven days for his cleansing, and wash his clothes, and bathe his flesh in running water, and shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 14, E'And on the eighth day he shall take to him two turtledoves, or two young pigeons, and come before the LORD unto the door of the tabernacle of the congregation, and give them unto the priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 15, E'And the priest shall offer them, the one for a sin offering, and the other for a burnt offering; and the priest shall make an atonement for him before the LORD for his issue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 16, E'And if any man’s seed of copulation go out from him, then he shall wash all his flesh in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 17, E'And every garment, and every skin, whereon is the seed of copulation, shall be washed with water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 18, E'The woman also with whom man shall lie with seed of copulation, they shall both bathe themselves in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 19, E'And if a woman have an issue, and her issue in her flesh be blood, she shall be put apart seven days: and whosoever toucheth her shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 20, E'And every thing that she lieth upon in her separation shall be unclean: every thing also that she sitteth upon shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 21, E'And whosoever toucheth her bed shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 22, E'And whosoever toucheth any thing that she sat upon shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 23, E'And if it be on her bed, or on any thing whereon she sitteth, when he toucheth it, he shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 24, E'And if any man lie with her at all, and her flowers be upon him, he shall be unclean seven days; and all the bed whereon he lieth shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 25, E'And if a woman have an issue of her blood many days out of the time of her separation, or if it run beyond the time of her separation; all the days of the issue of her uncleanness shall be as the days of her separation: she shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 26, E'Every bed whereon she lieth all the days of her issue shall be unto her as the bed of her separation: and whatsoever she sitteth upon shall be unclean, as the uncleanness of her separation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 27, E'And whosoever toucheth those things shall be unclean, and shall wash his clothes, and bathe himself in water, and be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 28, E'But if she be cleansed of her issue, then she shall number to herself seven days, and after that she shall be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 29, E'And on the eighth day she shall take unto her two turtles, or two young pigeons, and bring them unto the priest, to the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 30, E'And the priest shall offer the one for a sin offering, and the other for a burnt offering; and the priest shall make an atonement for her before the LORD for the issue of her uncleanness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 31, E'Thus shall ye separate the children of Israel from their uncleanness; that they die not in their uncleanness, when they defile my tabernacle that is among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 32, E'This is the law of him that hath an issue, and of him whose seed goeth from him, and is defiled therewith;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 15, 33, E'And of her that is sick of her flowers, and of him that hath an issue, of the man, and of the woman, and of him that lieth with her that is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 1, E'And the LORD spake unto Moses after the death of the two sons of Aaron, when they offered before the LORD, and died;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 2, E'And the LORD said unto Moses, Speak unto Aaron thy brother, that he come not at all times into the holy place within the vail before the mercy seat, which is upon the ark; that he die not: for I will appear in the cloud upon the mercy seat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 3, E'Thus shall Aaron come into the holy place: with a young bullock for a sin offering, and a ram for a burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 4, E'He shall put on the holy linen coat, and he shall have the linen breeches upon his flesh, and shall be girded with a linen girdle, and with the linen mitre shall he be attired: these are holy garments; therefore shall he wash his flesh in water, and so put them on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 5, E'And he shall take of the congregation of the children of Israel two kids of the goats for a sin offering, and one ram for a burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 6, E'And Aaron shall offer his bullock of the sin offering, which is for himself, and make an atonement for himself, and for his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 7, E'And he shall take the two goats, and present them before the LORD at the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 8, E'And Aaron shall cast lots upon the two goats; one lot for the LORD, and the other lot for the scapegoat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 9, E'And Aaron shall bring the goat upon which the LORD’s lot fell, and offer him for a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 10, E'But the goat, on which the lot fell to be the scapegoat, shall be presented alive before the LORD, to make an atonement with him, and to let him go for a scapegoat into the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 11, E'And Aaron shall bring the bullock of the sin offering, which is for himself, and shall make an atonement for himself, and for his house, and shall kill the bullock of the sin offering which is for himself:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 12, E'And he shall take a censer full of burning coals of fire from off the altar before the LORD, and his hands full of sweet incense beaten small, and bring it within the vail:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 13, E'And he shall put the incense upon the fire before the LORD, that the cloud of the incense may cover the mercy seat that is upon the testimony, that he die not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 14, E'And he shall take of the blood of the bullock, and sprinkle it with his finger upon the mercy seat eastward; and before the mercy seat shall he sprinkle of the blood with his finger seven times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 15, E'Then shall he kill the goat of the sin offering, that is for the people, and bring his blood within the vail, and do with that blood as he did with the blood of the bullock, and sprinkle it upon the mercy seat, and before the mercy seat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 16, E'And he shall make an atonement for the holy place, because of the uncleanness of the children of Israel, and because of their transgressions in all their sins: and so shall he do for the tabernacle of the congregation, that remaineth among them in the midst of their uncleanness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 17, E'And there shall be no man in the tabernacle of the congregation when he goeth in to make an atonement in the holy place, until he come out, and have made an atonement for himself, and for his household, and for all the congregation of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 18, E'And he shall go out unto the altar that is before the LORD, and make an atonement for it; and shall take of the blood of the bullock, and of the blood of the goat, and put it upon the horns of the altar round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 19, E'And he shall sprinkle of the blood upon it with his finger seven times, and cleanse it, and hallow it from the uncleanness of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 20, E'And when he hath made an end of reconciling the holy place, and the tabernacle of the congregation, and the altar, he shall bring the live goat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 21, E'And Aaron shall lay both his hands upon the head of the live goat, and confess over him all the iniquities of the children of Israel, and all their transgressions in all their sins, putting them upon the head of the goat, and shall send him away by the hand of a fit man into the wilderness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 22, E'And the goat shall bear upon him all their iniquities unto a land not inhabited: and he shall let go the goat in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 23, E'And Aaron shall come into the tabernacle of the congregation, and shall put off the linen garments, which he put on when he went into the holy place, and shall leave them there:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 24, E'And he shall wash his flesh with water in the holy place, and put on his garments, and come forth, and offer his burnt offering, and the burnt offering of the people, and make an atonement for himself, and for the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 25, E'And the fat of the sin offering shall he burn upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 26, E'And he that let go the goat for the scapegoat shall wash his clothes, and bathe his flesh in water, and afterward come into the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 27, E'And the bullock for the sin offering, and the goat for the sin offering, whose blood was brought in to make atonement in the holy place, shall one carry forth without the camp; and they shall burn in the fire their skins, and their flesh, and their dung.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 28, E'And he that burneth them shall wash his clothes, and bathe his flesh in water, and afterward he shall come into the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 29, E'And this shall be a statute for ever unto you: that in the seventh month, on the tenth day of the month, ye shall afflict your souls, and do no work at all, whether it be one of your own country, or a stranger that sojourneth among you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 30, E'For on that day shall the priest make an atonement for you, to cleanse you, that ye may be clean from all your sins before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 31, E'It shall be a sabbath of rest unto you, and ye shall afflict your souls, by a statute for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 32, E'And the priest, whom he shall anoint, and whom he shall consecrate to minister in the priest’s office in his father’s stead, shall make the atonement, and shall put on the linen clothes, even the holy garments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 33, E'And he shall make an atonement for the holy sanctuary, and he shall make an atonement for the tabernacle of the congregation, and for the altar, and he shall make an atonement for the priests, and for all the people of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 16, 34, E'And this shall be an everlasting statute unto you, to make an atonement for the children of Israel for all their sins once a year. And he did as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 2, E'Speak unto Aaron, and unto his sons, and unto all the children of Israel, and say unto them; This is the thing which the LORD hath commanded, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 3, E'What man soever there be of the house of Israel, that killeth an ox, or lamb, or goat, in the camp, or that killeth it out of the camp,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 4, E'And bringeth it not unto the door of the tabernacle of the congregation, to offer an offering unto the LORD before the tabernacle of the LORD; blood shall be imputed unto that man; he hath shed blood; and that man shall be cut off from among his people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 5, E'To the end that the children of Israel may bring their sacrifices, which they offer in the open field, even that they may bring them unto the LORD, unto the door of the tabernacle of the congregation, unto the priest, and offer them for peace offerings unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 6, E'And the priest shall sprinkle the blood upon the altar of the LORD at the door of the tabernacle of the congregation, and burn the fat for a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 7, E'And they shall no more offer their sacrifices unto devils, after whom they have gone a whoring. This shall be a statute for ever unto them throughout their generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 8, E'And thou shalt say unto them, Whatsoever man there be of the house of Israel, or of the strangers which sojourn among you, that offereth a burnt offering or sacrifice,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 9, E'And bringeth it not unto the door of the tabernacle of the congregation, to offer it unto the LORD; even that man shall be cut off from among his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 10, E'And whatsoever man there be of the house of Israel, or of the strangers that sojourn among you, that eateth any manner of blood; I will even set my face against that soul that eateth blood, and will cut him off from among his people.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 11, E'For the life of the flesh is in the blood: and I have given it to you upon the altar to make an atonement for your souls: for it is the blood that maketh an atonement for the soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 12, E'Therefore I said unto the children of Israel, No soul of you shall eat blood, neither shall any stranger that sojourneth among you eat blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 13, E'And whatsoever man there be of the children of Israel, or of the strangers that sojourn among you, which hunteth and catcheth any beast or fowl that may be eaten; he shall even pour out the blood thereof, and cover it with dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 14, E'For it is the life of all flesh; the blood of it is for the life thereof: therefore I said unto the children of Israel, Ye shall eat the blood of no manner of flesh: for the life of all flesh is the blood thereof: whosoever eateth it shall be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 15, E'And every soul that eateth that which died of itself, or that which was torn with beasts, whether it be one of your own country, or a stranger, he shall both wash his clothes, and bathe himself in water, and be unclean until the even: then shall he be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 17, 16, E'But if he wash them not, nor bathe his flesh; then he shall bear his iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 2, E'Speak unto the children of Israel, and say unto them, I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 3, E'After the doings of the land of Egypt, wherein ye dwelt, shall ye not do: and after the doings of the land of Canaan, whither I bring you, shall ye not do: neither shall ye walk in their ordinances.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 4, E'Ye shall do my judgments, and keep mine ordinances, to walk therein: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 5, E'Ye shall therefore keep my statutes, and my judgments: which if a man do, he shall live in them: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 6, E'None of you shall approach to any that is near of kin to him, to uncover their nakedness: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 7, E'The nakedness of thy father, or the nakedness of thy mother, shalt thou not uncover: she is thy mother; thou shalt not uncover her nakedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 8, E'The nakedness of thy father’s wife shalt thou not uncover: it is thy father’s nakedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 9, E'The nakedness of thy sister, the daughter of thy father, or daughter of thy mother, whether she be born at home, or born abroad, even their nakedness thou shalt not uncover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 10, E'The nakedness of thy son’s daughter, or of thy daughter’s daughter, even their nakedness thou shalt not uncover: for theirs is thine own nakedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 11, E'The nakedness of thy father’s wife’s daughter, begotten of thy father, she is thy sister, thou shalt not uncover her nakedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 12, E'Thou shalt not uncover the nakedness of thy father’s sister: she is thy father’s near kinswoman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 13, E'Thou shalt not uncover the nakedness of thy mother’s sister: for she is thy mother’s near kinswoman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 14, E'Thou shalt not uncover the nakedness of thy father’s brother, thou shalt not approach to his wife: she is thine aunt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 15, E'Thou shalt not uncover the nakedness of thy daughter in law: she is thy son’s wife; thou shalt not uncover her nakedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 16, E'Thou shalt not uncover the nakedness of thy brother’s wife: it is thy brother’s nakedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 17, E'Thou shalt not uncover the nakedness of a woman and her daughter, neither shalt thou take her son’s daughter, or her daughter’s daughter, to uncover her nakedness; for they are her near kinswomen: it is wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 18, E'Neither shalt thou take a wife to her sister, to vex her, to uncover her nakedness, beside the other in her life time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 19, E'Also thou shalt not approach unto a woman to uncover her nakedness, as long as she is put apart for her uncleanness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 20, E'Moreover thou shalt not lie carnally with thy neighbour’s wife, to defile thyself with her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 21, E'And thou shalt not let any of thy seed pass through the fire to Molech, neither shalt thou profane the name of thy God: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 22, E'Thou shalt not lie with mankind, as with womankind: it is abomination.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 23, E'Neither shalt thou lie with any beast to defile thyself therewith: neither shall any woman stand before a beast to lie down thereto: it is confusion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 24, E'Defile not ye yourselves in any of these things: for in all these the nations are defiled which I cast out before you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 25, E'And the land is defiled: therefore I do visit the iniquity thereof upon it, and the land itself vomiteth out her inhabitants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 26, E'Ye shall therefore keep my statutes and my judgments, and shall not commit any of these abominations; neither any of your own nation, nor any stranger that sojourneth among you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 27, E'(For all these abominations have the men of the land done, which were before you, and the land is defiled;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 28, E'That the land spue not you out also, when ye defile it, as it spued out the nations that were before you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 29, E'For whosoever shall commit any of these abominations, even the souls that commit them shall be cut off from among their people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 18, 30, E'Therefore shall ye keep mine ordinance, that ye commit not any one of these abominable customs, which were committed before you, and that ye defile not yourselves therein: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 2, E'Speak unto all the congregation of the children of Israel, and say unto them, Ye shall be holy: for I the LORD your God am holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 3, E'Ye shall fear every man his mother, and his father, and keep my sabbaths: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 4, E'Turn ye not unto idols, nor make to yourselves molten gods: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 5, E'And if ye offer a sacrifice of peace offerings unto the LORD, ye shall offer it at your own will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 6, E'It shall be eaten the same day ye offer it, and on the morrow: and if ought remain until the third day, it shall be burnt in the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 7, E'And if it be eaten at all on the third day, it is abominable; it shall not be accepted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 8, E'Therefore every one that eateth it shall bear his iniquity, because he hath profaned the hallowed thing of the LORD: and that soul shall be cut off from among his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 9, E'And when ye reap the harvest of your land, thou shalt not wholly reap the corners of thy field, neither shalt thou gather the gleanings of thy harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 10, E'And thou shalt not glean thy vineyard, neither shalt thou gather every grape of thy vineyard; thou shalt leave them for the poor and stranger: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 11, E'Ye shall not steal, neither deal falsely, neither lie one to another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 12, E'And ye shall not swear by my name falsely, neither shalt thou profane the name of thy God: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 13, E'Thou shalt not defraud thy neighbour, neither rob him: the wages of him that is hired shall not abide with thee all night until the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 14, E'Thou shalt not curse the deaf, nor put a stumblingblock before the blind, but shalt fear thy God: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 15, E'Ye shall do no unrighteousness in judgment: thou shalt not respect the person of the poor, nor honor the person of the mighty: but in righteousness shalt thou judge thy neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 16, E'Thou shalt not go up and down as a talebearer among thy people: neither shalt thou stand against the blood of thy neighbour: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 17, E'Thou shalt not hate thy brother in thine heart: thou shalt in any wise rebuke thy neighbour, and not suffer sin upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 18, E'Thou shalt not avenge, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 19, E'Ye shall keep my statutes. Thou shalt not let thy cattle gender with a diverse kind: thou shalt not sow thy field with mingled seed: neither shall a garment mingled of linen and woollen come upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 20, E'And whosoever lieth carnally with a woman, that is a bondmaid, betrothed to an husband, and not at all redeemed, nor freedom given her; she shall be scourged; they shall not be put to death, because she was not free.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 21, E'And he shall bring his trespass offering unto the LORD, unto the door of the tabernacle of the congregation, even a ram for a trespass offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 22, E'And the priest shall make an atonement for him with the ram of the trespass offering before the LORD for his sin which he hath done: and the sin which he hath done shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 23, E'And when ye shall come into the land, and shall have planted all manner of trees for food, then ye shall count the fruit thereof as uncircumcised: three years shall it be as uncircumcised unto you: it shall not be eaten of.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 24, E'But in the fourth year all the fruit thereof shall be holy to praise the LORD withal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 25, E'And in the fifth year shall ye eat of the fruit thereof, that it may yield unto you the increase thereof: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 26, E'Ye shall not eat any thing with the blood: neither shall ye use enchantment, nor observe times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 27, E'Ye shall not round the corners of your heads, neither shalt thou mar the corners of thy beard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 28, E'Ye shall not make any cuttings in your flesh for the dead, nor print any marks upon you: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 29, E'Do not prostitute thy daughter, to cause her to be a whore; lest the land fall to whoredom, and the land become full of wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 30, E'Ye shall keep my sabbaths, and reverence my sanctuary: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 31, E'Regard not them that have familiar spirits, neither seek after wizards, to be defiled by them: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 32, E'Thou shalt rise up before the hoary head, and honour the face of the old man, and fear thy God: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 33, E'And if a stranger sojourn with thee in your land, ye shall not vex him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 34, E'But the stranger that dwelleth with you shall be unto you as one born among you, and thou shalt love him as thyself; for ye were strangers in the land of Egypt: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 35, E'Ye shall do no unrighteousness in judgment, in meteyard, in weight, or in measure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 36, E'Just balances, just weights, a just ephah, and a just hin, shall ye have: I am the LORD your God, which brought you out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 19, 37, E'Therefore shall ye observe all my statutes, and all my judgments, and do them: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 2, E'Again, thou shalt say to the children of Israel, Whosoever he be of the children of Israel, or of the strangers that sojourn in Israel, that giveth any of his seed unto Molech; he shall surely be put to death: the people of the land shall stone him with stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 3, E'And I will set my face against that man, and will cut him off from among his people; because he hath given of his seed unto Molech, to defile my sanctuary, and to profane my holy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 4, E'And if the people of the land do any ways hide their eyes from the man, when he giveth of his seed unto Molech, and kill him not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 5, E'Then I will set my face against that man, and against his family, and will cut him off, and all that go a whoring after him, to commit whoredom with Molech, from among their people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 6, E'And the soul that turneth after such as have familiar spirits, and after wizards, to go a whoring after them, I will even set my face against that soul, and will cut him off from among his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 7, E'Sanctify yourselves therefore, and be ye holy: for I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 8, E'And ye shall keep my statutes, and do them: I am the LORD which sanctify you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 9, E'For every one that curseth his father or his mother shall be surely put to death: he hath cursed his father or his mother; his blood shall be upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 10, E'And the man that committeth adultery with another man’s wife, even he that committeth adultery with his neighbour’s wife, the adulterer and the adulteress shall surely be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 11, E'And the man that lieth with his father’s wife hath uncovered his father’s nakedness: both of them shall surely be put to death; their blood shall be upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 12, E'And if a man lie with his daughter in law, both of them shall surely be put to death: they have wrought confusion; their blood shall be upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 13, E'If a man also lie with mankind, as he lieth with a woman, both of them have committed an abomination: they shall surely be put to death; their blood shall be upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 14, E'And if a man take a wife and her mother, it is wickedness: they shall be burnt with fire, both he and they; that there be no wickedness among you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 15, E'And if a man lie with a beast, he shall surely be put to death: and ye shall slay the beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 16, E'And if a woman approach unto any beast, and lie down thereto, thou shalt kill the woman, and the beast: they shall surely be put to death; their blood shall be upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 17, E'And if a man shall take his sister, his father’s daughter, or his mother’s daughter, and see her nakedness, and she see his nakedness; it is a wicked thing; and they shall be cut off in the sight of their people: he hath uncovered his sister’s nakedness; he shall bear his iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 18, E'And if a man shall lie with a woman having her sickness, and shall uncover her nakedness; he hath discovered her fountain, and she hath uncovered the fountain of her blood: and both of them shall be cut off from among their people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 19, E'And thou shalt not uncover the nakedness of thy mother’s sister, nor of thy father’s sister: for he uncovereth his near kin: they shall bear their iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 20, E'And if a man shall lie with his uncle’s wife, he hath uncovered his uncle’s nakedness: they shall bear their sin; they shall die childless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 21, E'And if a man shall take his brother’s wife, it is an unclean thing: he hath uncovered his brother’s nakedness; they shall be childless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 22, E'Ye shall therefore keep all my statutes, and all my judgments, and do them: that the land, whither I bring you to dwell therein, spue you not out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 23, E'And ye shall not walk in the manners of the nation, which I cast out before you: for they committed all these things, and therefore I abhorred them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 24, E'But I have said unto you, Ye shall inherit their land, and I will give it unto you to possess it, a land that floweth with milk and honey: I am the LORD your God, which have separated you from other people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 25, E'Ye shall therefore put difference between clean beasts and unclean, and between unclean fowls and clean: and ye shall not make your souls abominable by beast, or by fowl, or by any manner of living thing that creepeth on the ground, which I have separated from you as unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 26, E'And ye shall be holy unto me: for I the LORD am holy, and have severed you from other people, that ye should be mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 20, 27, E'A man also or woman that hath a familiar spirit, or that is a wizard, shall surely be put to death: they shall stone them with stones: their blood shall be upon them.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 1, E'And the LORD said unto Moses, Speak unto the priests the sons of Aaron, and say unto them, There shall none be defiled for the dead among his people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 2, E'But for his kin, that is near unto him, that is, for his mother, and for his father, and for his son, and for his daughter, and for his brother,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 3, E'And for his sister a virgin, that is nigh unto him, which hath had no husband; for her may he be defiled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 4, E'But he shall not defile himself, being a chief man among his people, to profane himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 5, E'They shall not make baldness upon their head, neither shall they shave off the corner of their beard, nor make any cuttings in their flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 6, E'They shall be holy unto their God, and not profane the name of their God: for the offerings of the LORD made by fire, and the bread of their God, they do offer: therefore they shall be holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 7, E'They shall not take a wife that is a whore, or profane; neither shall they take a woman put away from her husband: for he is holy unto his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 8, E'Thou shalt sanctify him therefore; for he offereth the bread of thy God: he shall be holy unto thee: for I the LORD, which sanctify you, am holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 9, E'And the daughter of any priest, if she profane herself by playing the whore, she profaneth her father: she shall be burnt with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 10, E'And he that is the high priest among his brethren, upon whose head the anointing oil was poured, and that is consecrated to put on the garments, shall not uncover his head, nor rend his clothes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 11, E'Neither shall he go in to any dead body, nor defile himself for his father, or for his mother;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 12, E'Neither shall he go out of the sanctuary, nor profane the sanctuary of his God; for the crown of the anointing oil of his God is upon him: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 13, E'And he shall take a wife in her virginity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 14, E'A widow, or a divorced woman, or profane, or an harlot, these shall he not take: but he shall take a virgin of his own people to wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 15, E'Neither shall he profane his seed among his people: for I the LORD do sanctify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 16, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 17, E'Speak unto Aaron, saying, Whosoever he be of thy seed in their generations that hath any blemish, let him not approach to offer the bread of his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 18, E'For whatsoever man he be that hath a blemish, he shall not approach: a blind man, or a lame, or he that hath a flat nose, or any thing superfluous,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 19, E'Or a man that is brokenfooted, or brokenhanded,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 20, E'Or crookbackt, or a dwarf, or that hath a blemish in his eye, or be scurvy, or scabbed, or hath his stones broken;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 21, E'No man that hath a blemish of the seed of Aaron the priest shall come nigh to offer the offerings of the LORD made by fire: he hath a blemish; he shall not come nigh to offer the bread of his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 22, E'He shall eat the bread of his God, both of the most holy, and of the holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 23, E'Only he shall not go in unto the vail, nor come nigh unto the altar, because he hath a blemish; that he profane not my sanctuaries: for I the LORD do sanctify them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 21, 24, E'And Moses told it unto Aaron, and to his sons, and unto all the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 2, E'Speak unto Aaron and to his sons, that they separate themselves from the holy things of the children of Israel, and that they profane not my holy name in those things which they hallow unto me: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 3, E'Say unto them, Whosoever he be of all your seed among your generations, that goeth unto the holy things, which the children of Israel hallow unto the LORD, having his uncleanness upon him, that soul shall be cut off from my presence: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 4, E'What man soever of the seed of Aaron is a leper, or hath a running issue; he shall not eat of the holy things, until he be clean. And whoso toucheth any thing that is unclean by the dead, or a man whose seed goeth from him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 5, E'Or whosoever toucheth any creeping thing, whereby he may be made unclean, or a man of whom he may take uncleanness, whatsoever uncleanness he hath;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 6, E'The soul which hath touched any such shall be unclean until even, and shall not eat of the holy things, unless he wash his flesh with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 7, E'And when the sun is down, he shall be clean, and shall afterward eat of the holy things; because it is his food.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 8, E'That which dieth of itself, or is torn with beasts, he shall not eat to defile himself therewith: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 9, E'They shall therefore keep mine ordinance, lest they bear sin for it, and die therefore, if they profane it: I the LORD do sanctify them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 10, E'There shall no stranger eat of the holy thing: a sojourner of the priest, or an hired servant, shall not eat of the holy thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 11, E'But if the priest buy any soul with his money, he shall eat of it, and he that is born in his house: they shall eat of his meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 12, E'If the priest’s daughter also be married unto a stranger, she may not eat of an offering of the holy things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 13, E'But if the priest’s daughter be a widow, or divorced, and have no child, and is returned unto her father’s house, as in her youth, she shall eat of her father’s meat: but there shall no stranger eat thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 14, E'And if a man eat of the holy thing unwittingly, then he shall put the fifth part thereof unto it, and shall give it unto the priest with the holy thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 15, E'And they shall not profane the holy things of the children of Israel, which they offer unto the LORD;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 16, E'Or suffer them to bear the iniquity of trespass, when they eat their holy things: for I the LORD do sanctify them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 17, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 18, E'Speak unto Aaron, and to his sons, and unto all the children of Israel, and say unto them, Whatsoever he be of the house of Israel, or of the strangers in Israel, that will offer his oblation for all his vows, and for all his freewill offerings, which they will offer unto the LORD for a burnt offering;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 19, E'Ye shall offer at your own will a male without blemish, of the beeves, of the sheep, or of the goats.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 20, E'But whatsoever hath a blemish, that shall ye not offer: for it shall not be acceptable for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 21, E'And whosoever offereth a sacrifice of peace offerings unto the LORD to accomplish his vow, or a freewill offering in beeves or sheep, it shall be perfect to be accepted; there shall be no blemish therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 22, E'Blind, or broken, or maimed, or having a wen, or scurvy, or scabbed, ye shall not offer these unto the LORD, nor make an offering by fire of them upon the altar unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 23, E'Either a bullock or a lamb that hath any thing superfluous or lacking in his parts, that mayest thou offer for a freewill offering; but for a vow it shall not be accepted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 24, E'Ye shall not offer unto the LORD that which is bruised, or crushed, or broken, or cut; neither shall ye make any offering thereof in your land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 25, E'Neither from a stranger’s hand shall ye offer the bread of your God of any of these; because their corruption is in them, and blemishes be in them: they shall not be accepted for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 26, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 27, E'When a bullock, or a sheep, or a goat, is brought forth, then it shall be seven days under the dam; and from the eighth day and thenceforth it shall be accepted for an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 28, E'And whether it be cow or ewe, ye shall not kill it and her young both in one day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 29, E'And when ye will offer a sacrifice of thanksgiving unto the LORD, offer it at your own will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 30, E'On the same day it shall be eaten up; ye shall leave none of it until the morrow: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 31, E'Therefore shall ye keep my commandments, and do them: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 32, E'Neither shall ye profane my holy name; but I will be hallowed among the children of Israel: I am the LORD which hallow you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 22, 33, E'That brought you out of the land of Egypt, to be your God: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 2, E'Speak unto the children of Israel, and say unto them, Concerning the feasts of the LORD, which ye shall proclaim to be holy convocations, even these are my feasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 3, E'Six days shall work be done: but the seventh day is the sabbath of rest, an holy convocation; ye shall do no work therein: it is the sabbath of the LORD in all your dwellings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 4, E'These are the feasts of the LORD, even holy convocations, which ye shall proclaim in their seasons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 5, E'In the fourteenth day of the first month at even is the LORD’s passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 6, E'And on the fifteenth day of the same month is the feast of unleavened bread unto the LORD: seven days ye must eat unleavened bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 7, E'In the first day ye shall have an holy convocation: ye shall do no servile work therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 8, E'But ye shall offer an offering made by fire unto the LORD seven days: in the seventh day is an holy convocation: ye shall do no servile work therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 9, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 10, E'Speak unto the children of Israel, and say unto them, When ye be come into the land which I give unto you, and shall reap the harvest thereof, then ye shall bring a sheaf of the firstfruits of your harvest unto the priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 11, E'And he shall wave the sheaf before the LORD, to be accepted for you: on the morrow after the sabbath the priest shall wave it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 12, E'And ye shall offer that day when ye wave the sheaf an he lamb without blemish of the first year for a burnt offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 13, E'And the meat offering thereof shall be two tenth deals of fine flour mingled with oil, an offering made by fire unto the LORD for a sweet savour: and the drink offering thereof shall be of wine, the fourth part of an hin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 14, E'And ye shall eat neither bread, nor parched corn, nor green ears, until the selfsame day that ye have brought an offering unto your God: it shall be a statute for ever throughout your generations in all your dwellings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 15, E'And ye shall count unto you from the morrow after the sabbath, from the day that ye brought the sheaf of the wave offering; seven sabbaths shall be complete:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 16, E'Even unto the morrow after the seventh sabbath shall ye number fifty days; and ye shall offer a new meat offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 17, E'Ye shall bring out of your habitations two wave loaves of two tenth deals: they shall be of fine flour; they shall be baken with leaven; they are the firstfruits unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 18, E'And ye shall offer with the bread seven lambs without blemish of the first year, and one young bullock, and two rams: they shall be for a burnt offering unto the LORD, with their meat offering, and their drink offerings, even an offering made by fire, of sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 19, E'Then ye shall sacrifice one kid of the goats for a sin offering, and two lambs of the first year for a sacrifice of peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 20, E'And the priest shall wave them with the bread of the firstfruits for a wave offering before the LORD, with the two lambs: they shall be holy to the LORD for the priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 21, E'And ye shall proclaim on the selfsame day, that it may be an holy convocation unto you: ye shall do no servile work therein: it shall be a statute for ever in all your dwellings throughout your generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 22, E'And when ye reap the harvest of your land, thou shalt not make clean riddance of the corners of thy field when thou reapest, neither shalt thou gather any gleaning of thy harvest: thou shalt leave them unto the poor, and to the stranger: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 23, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 24, E'Speak unto the children of Israel, saying, In the seventh month, in the first day of the month, shall ye have a sabbath, a memorial of blowing of trumpets, an holy convocation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 25, E'Ye shall do no servile work therein: but ye shall offer an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 26, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 27, E'Also on the tenth day of this seventh month there shall be a day of atonement: it shall be an holy convocation unto you; and ye shall afflict your souls, and offer an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 28, E'And ye shall do no work in that same day: for it is a day of atonement, to make an atonement for you before the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 29, E'For whatsoever soul it be that shall not be afflicted in that same day, he shall be cut off from among his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 30, E'And whatsoever soul it be that doeth any work in that same day, the same soul will I destroy from among his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 31, E'Ye shall do no manner of work: it shall be a statute for ever throughout your generations in all your dwellings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 32, E'It shall be unto you a sabbath of rest, and ye shall afflict your souls: in the ninth day of the month at even, from even unto even, shall ye celebrate your sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 33, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 34, E'Speak unto the children of Israel, saying, The fifteenth day of this seventh month shall be the feast of tabernacles for seven days unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 35, E'On the first day shall be an holy convocation: ye shall do no servile work therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 36, E'Seven days ye shall offer an offering made by fire unto the LORD: on the eighth day shall be an holy convocation unto you; and ye shall offer an offering made by fire unto the LORD: it is a solemn assembly; and ye shall do no servile work therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 37, E'These are the feasts of the LORD, which ye shall proclaim to be holy convocations, to offer an offering made by fire unto the LORD, a burnt offering, and a meat offering, a sacrifice, and drink offerings, every thing upon his day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 38, E'Beside the sabbaths of the LORD, and beside your gifts, and beside all your vows, and beside all your freewill offerings, which ye give unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 39, E'Also in the fifteenth day of the seventh month, when ye have gathered in the fruit of the land, ye shall keep a feast unto the LORD seven days: on the first day shall be a sabbath, and on the eighth day shall be a sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 40, E'And ye shall take you on the first day the boughs of goodly trees, branches of palm trees, and the boughs of thick trees, and willows of the brook; and ye shall rejoice before the LORD your God seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 41, E'And ye shall keep it a feast unto the LORD seven days in the year. It shall be a statute for ever in your generations: ye shall celebrate it in the seventh month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 42, E'Ye shall dwell in booths seven days; all that are Israelites born shall dwell in booths:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 43, E'That your generations may know that I made the children of Israel to dwell in booths, when I brought them out of the land of Egypt: I am the LORD your God.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 23, 44, E'And Moses declared unto the children of Israel the feasts of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 2, E'Command the children of Israel, that they bring unto thee pure oil olive beaten for the light, to cause the lamps to burn continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 3, E'Without the vail of the testimony, in the tabernacle of the congregation, shall Aaron order it from the evening unto the morning before the LORD continually: it shall be a statute for ever in your generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 4, E'He shall order the lamps upon the pure candlestick before the LORD continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 5, E'And thou shalt take fine flour, and bake twelve cakes thereof: two tenth deals shall be in one cake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 6, E'And thou shalt set them in two rows, six on a row, upon the pure table before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 7, E'And thou shalt put pure frankincense upon each row, that it may be on the bread for a memorial, even an offering made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 8, E'Every sabbath he shall set it in order before the LORD continually, being taken from the children of Israel by an everlasting covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 9, E'And it shall be Aaron’s and his sons’; and they shall eat it in the holy place: for it is most holy unto him of the offerings of the LORD made by fire by a perpetual statute.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 10, E'And the son of an Israelitish woman, whose father was an Egyptian, went out among the children of Israel: and this son of the Israelitish woman and a man of Israel strove together in the camp;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 11, E'And the Israelitish woman’s son blasphemed the name of the Lord, and cursed. And they brought him unto Moses: (and his mother’s name was Shelomith, the daughter of Dibri, of the tribe of Dan:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 12, E'And they put him in ward, that the mind of the LORD might be shewed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 13, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 14, E'Bring forth him that hath cursed without the camp; and let all that heard him lay their hands upon his head, and let all the congregation stone him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 15, E'And thou shalt speak unto the children of Israel, saying, Whosoever curseth his God shall bear his sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 16, E'And he that blasphemeth the name of the LORD, he shall surely be put to death, and all the congregation shall certainly stone him: as well the stranger, as he that is born in the land, when he blasphemeth the name of the Lord, shall be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 17, E'And he that killeth any man shall surely be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 18, E'And he that killeth a beast shall make it good; beast for beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 19, E'And if a man cause a blemish in his neighbour; as he hath done, so shall it be done to him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 20, E'Breach for breach, eye for eye, tooth for tooth: as he hath caused a blemish in a man, so shall it be done to him again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 21, E'And he that killeth a beast, he shall restore it: and he that killeth a man, he shall be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 22, E'Ye shall have one manner of law, as well for the stranger, as for one of your own country: for I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 24, 23, E'And Moses spake to the children of Israel, that they should bring forth him that had cursed out of the camp, and stone him with stones. And the children of Israel did as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 1, E'And the LORD spake unto Moses in mount Sinai, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 2, E'Speak unto the children of Israel, and say unto them, When ye come into the land which I give you, then shall the land keep a sabbath unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 3, E'Six years thou shalt sow thy field, and six years thou shalt prune thy vineyard, and gather in the fruit thereof;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 4, E'But in the seventh year shall be a sabbath of rest unto the land, a sabbath for the LORD: thou shalt neither sow thy field, nor prune thy vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 5, E'That which groweth of its own accord of thy harvest thou shalt not reap, neither gather the grapes of thy vine undressed: for it is a year of rest unto the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 6, E'And the sabbath of the land shall be meat for you; for thee, and for thy servant, and for thy maid, and for thy hired servant, and for thy stranger that sojourneth with thee,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 7, E'And for thy cattle, and for the beast that are in thy land, shall all the increase thereof be meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 8, E'And thou shalt number seven sabbaths of years unto thee, seven times seven years; and the space of the seven sabbaths of years shall be unto thee forty and nine years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 9, E'Then shalt thou cause the trumpet of the jubile to sound on the tenth day of the seventh month, in the day of atonement shall ye make the trumpet sound throughout all your land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 10, E'And ye shall hallow the fiftieth year, and proclaim liberty throughout all the land unto all the inhabitants thereof: it shall be a jubile unto you; and ye shall return every man unto his possession, and ye shall return every man unto his family.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 11, E'A jubile shall that fiftieth year be unto you: ye shall not sow, neither reap that which groweth of itself in it, nor gather the grapes in it of thy vine undressed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 12, E'For it is the jubile; it shall be holy unto you: ye shall eat the increase thereof out of the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 13, E'In the year of this jubile ye shall return every man unto his possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 14, E'And if thou sell ought unto thy neighbour, or buyest ought of thy neighbour’s hand, ye shall not oppress one another:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 15, E'According to the number of years after the jubile thou shalt buy of thy neighbour, and according unto the number of years of the fruits he shall sell unto thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 16, E'According to the multitude of years thou shalt increase the price thereof, and according to the fewness of years thou shalt diminish the price of it: for according to the number of the years of the fruits doth he sell unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 17, E'Ye shall not therefore oppress one another; but thou shalt fear thy God:for I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 18, E'Wherefore ye shall do my statutes, and keep my judgments, and do them; and ye shall dwell in the land in safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 19, E'And the land shall yield her fruit, and ye shall eat your fill, and dwell therein in safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 20, E'And if ye shall say, What shall we eat the seventh year? behold, we shall not sow, nor gather in our increase:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 21, E'Then I will command my blessing upon you in the sixth year, and it shall bring forth fruit for three years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 22, E'And ye shall sow the eighth year, and eat yet of old fruit until the ninth year; until her fruits come in ye shall eat of the old store.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 23, E'The land shall not be sold for ever: for the land is mine; for ye are strangers and sojourners with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 24, E'And in all the land of your possession ye shall grant a redemption for the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 25, E'If thy brother be waxen poor, and hath sold away some of his possession, and if any of his kin come to redeem it, then shall he redeem that which his brother sold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 26, E'And if the man have none to redeem it, and himself be able to redeem it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 27, E'Then let him count the years of the sale thereof, and restore the overplus unto the man to whom he sold it; that he may return unto his possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 28, E'But if he be not able to restore it to him, then that which is sold shall remain in the hand of him that hath bought it until the year of jubile: and in the jubile it shall go out, and he shall return unto his possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 29, E'And if a man sell a dwelling house in a walled city, then he may redeem it within a whole year after it is sold; within a full year may he redeem it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 30, E'And if it be not redeemed within the space of a full year, then the house that is in the walled city shall be established for ever to him that bought it throughout his generations: it shall not go out in the jubile.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 31, E'But the houses of the villages which have no wall round about them shall be counted as the fields of the country: they may be redeemed, and they shall go out in the jubile.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 32, E'Notwithstanding the cities of the Levites, and the houses of the cities of their possession, may the Levites redeem at any time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 33, E'And if a man purchase of the Levites, then the house that was sold, and the city of his possession, shall go out in the year of jubile: for the houses of the cities of the Levites are their possession among the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 34, E'But the field of the suburbs of their cities may not be sold; for it is their perpetual possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 35, E'And if thy brother be waxen poor, and fallen in decay with thee; then thou shalt relieve him: yea, though he be a stranger, or a sojourner; that he may live with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 36, E'Take thou no usury of him, or increase: but fear thy God; that thy brother may live with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 37, E'Thou shalt not give him thy money upon usury, nor lend him thy victuals for increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 38, E'I am the LORD your God, which brought you forth out of the land of Egypt, to give you the land of Canaan, and to be your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 39, E'And if thy brother that dwelleth by thee be waxen poor, and be sold unto thee; thou shalt not compel him to serve as a bondservant:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 40, E'But as an hired servant, and as a sojourner, he shall be with thee, and shall serve thee unto the year of jubile:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 41, E'And then shall he depart from thee, both he and his children with him, and shall return unto his own family, and unto the possession of his fathers shall he return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 42, E'For they are my servants, which I brought forth out of the land of Egypt: they shall not be sold as bondmen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 43, E'Thou shalt not rule over him with rigour; but shalt fear thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 44, E'Both thy bondmen, and thy bondmaids, which thou shalt have, shall be of the heathen that are round about you; of them shall ye buy bondmen and bondmaids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 45, E'Moreover of the children of the strangers that do sojourn among you, of them shall ye buy, and of their families that are with you, which they begat in your land: and they shall be your possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 46, E'And ye shall take them as an inheritance for your children after you, to inherit them for a possession; they shall be your bondmen for ever: but over your brethren the children of Israel, ye shall not rule one over another with rigour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 47, E'And if a sojourner or stranger wax rich by thee, and thy brother that dwelleth by him wax poor, and sell himself unto the stranger or sojourner by thee, or to the stock of the stranger’s family:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 48, E'After that he is sold he may be redeemed again; one of his brethren may redeem him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 49, E'Either his uncle, or his uncle’s son, may redeem him, or any that is nigh of kin unto him of his family may redeem him; or if he be able, he may redeem himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 50, E'And he shall reckon with him that bought him from the year that he was sold to him unto the year of jubile: and the price of his sale shall be according unto the number of years, according to the time of an hired servant shall it be with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 51, E'If there be yet many years behind, according unto them he shall give again the price of his redemption out of the money that he was bought for.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 52, E'And if there remain but few years unto the year of jubile, then he shall count with him, and according unto his years shall he give him again the price of his redemption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 53, E'And as a yearly hired servant shall he be with him: and the other shall not rule with rigour over him in thy sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 54, E'And if he be not redeemed in these years, then he shall go out in the year of jubile, both he, and his children with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 25, 55, E'For unto me the children of Israel are servants; they are my servants whom I brought forth out of the land of Egypt: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 1, E'Ye shall make you no idols nor graven image, neither rear you up a standing image, neither shall ye set up any image of stone in your land, to bow down unto it: for I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 2, E'Ye shall keep my sabbaths, and reverence my sanctuary: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 3, E'If ye walk in my statutes, and keep my commandments, and do them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 4, E'Then I will give you rain in due season, and the land shall yield her increase, and the trees of the field shall yield their fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 5, E'And your threshing shall reach unto the vintage, and the vintage shall reach unto the sowing time: and ye shall eat your bread to the full, and dwell in your land safely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 6, E'And I will give peace in the land, and ye shall lie down, and none shall make you afraid: and I will rid evil beasts out of the land, neither shall the sword go through your land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 7, E'And ye shall chase your enemies, and they shall fall before you by the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 8, E'And five of you shall chase an hundred, and an hundred of you shall put ten thousand to flight: and your enemies shall fall before you by the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 9, E'For I will have respect unto you, and make you fruitful, and multiply you, and establish my covenant with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 10, E'And ye shall eat old store, and bring forth the old because of the new.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 11, E'And I will set my tabernacle among you: and my soul shall not abhor you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 12, E'And I will walk among you, and will be your God, and ye shall be my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 13, E'I am the LORD your God, which brought you forth out of the land of Egypt, that ye should not be their bondmen; and I have broken the bands of your yoke, and made you go upright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 14, E'But if ye will not hearken unto me, and will not do all these commandments;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 15, E'And if ye shall despise my statutes, or if your soul abhor my judgments, so that ye will not do all my commandments, but that ye break my covenant:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 16, E'I also will do this unto you; I will even appoint over you terror, consumption, and the burning ague, that shall consume the eyes, and cause sorrow of heart: and ye shall sow your seed in vain, for your enemies shall eat it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 17, E'And I will set my face against you, and ye shall be slain before your enemies: they that hate you shall reign over you; and ye shall flee when none pursueth you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 18, E'And if ye will not yet for all this hearken unto me, then I will punish you seven times more for your sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 19, E'And I will break the pride of your power; and I will make your heaven as iron, and your earth as brass:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 20, E'And your strength shall be spent in vain: for your land shall not yield her increase, neither shall the trees of the land yield their fruits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 21, E'And if ye walk contrary unto me, and will not hearken unto me; I will bring seven times more plagues upon you according to your sins.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 22, E'I will also send wild beasts among you, which shall rob you of your children, and destroy your cattle, and make you few in number; and your high ways shall be desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 23, E'And if ye will not be reformed by me by these things, but will walk contrary unto me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 24, E'Then will I also walk contrary unto you, and will punish you yet seven times for your sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 25, E'And I will bring a sword upon you, that shall avenge the quarrel of my covenant: and when ye are gathered together within your cities, I will send the pestilence among you; and ye shall be delivered into the hand of the enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 26, E'And when I have broken the staff of your bread, ten women shall bake your bread in one oven, and they shall deliver you your bread again by weight: and ye shall eat, and not be satisfied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 27, E'And if ye will not for all this hearken unto me, but walk contrary unto me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 28, E'Then I will walk contrary unto you also in fury; and I, even I, will chastise you seven times for your sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 29, E'And ye shall eat the flesh of your sons, and the flesh of your daughters shall ye eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 30, E'And I will destroy your high places, and cut down your images, and cast your carcases upon the carcases of your idols, and my soul shall abhor you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 31, E'And I will make your cities waste, and bring your sanctuaries unto desolation, and I will not smell the savour of your sweet odours.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 32, E'And I will bring the land into desolation: and your enemies which dwell therein shall be astonished at it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 33, E'And I will scatter you among the heathen, and will draw out a sword after you: and your land shall be desolate, and your cities waste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 34, E'Then shall the land enjoy her sabbaths, as long as it lieth desolate, and ye be in your enemies’ land; even then shall the land rest, and enjoy her sabbaths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 35, E'As long as it lieth desolate it shall rest; because it did not rest in your sabbaths, when ye dwelt upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 36, E'And upon them that are left alive of you I will send a faintness into their hearts in the lands of their enemies; and the sound of a shaken leaf shall chase them; and they shall flee, as fleeing from a sword; and they shall fall when none pursueth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 37, E'And they shall fall one upon another, as it were before a sword, when none pursueth: and ye shall have no power to stand before your enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 38, E'And ye shall perish among the heathen, and the land of your enemies shall eat you up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 39, E'And they that are left of you shall pine away in their iniquity in your enemies’ lands; and also in the iniquities of their fathers shall they pine away with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 40, E'If they shall confess their iniquity, and the iniquity of their fathers, with their trespass which they trespassed against me, and that also they have walked contrary unto me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 41, E'And that I also have walked contrary unto them, and have brought them into the land of their enemies; if then their uncircumcised hearts be humbled, and they then accept of the punishment of their iniquity:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 42, E'Then will I remember my covenant with Jacob, and also my covenant with Isaac, and also my covenant with Abraham will I remember; and I will remember the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 43, E'The land also shall be left of them, and shall enjoy her sabbaths, while she lieth desolate without them: and they shall accept of the punishment of their iniquity: because, even because they despised my judgments, and because their soul abhorred my statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 44, E'And yet for all that, when they be in the land of their enemies, I will not cast them away, neither will I abhor them, to destroy them utterly, and to break my covenant with them: for I am the LORD their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 45, E'But I will for their sakes remember the covenant of their ancestors, whom I brought forth out of the land of Egypt in the sight of the heathen, that I might be their God: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 26, 46, E'These are the statutes and judgments and laws, which the LORD made between him and the children of Israel in mount Sinai by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 2, E'Speak unto the children of Israel, and say unto them, When a man shall make a singular vow, the persons shall be for the LORD by thy estimation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 3, E'And thy estimation shall be of the male from twenty years old even unto sixty years old, even thy estimation shall be fifty shekels of silver, after the shekel of the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 4, E'And if it be a female, then thy estimation shall be thirty shekels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 5, E'And if it be from five years old even unto twenty years old, then thy estimation shall be of the male twenty shekels, and for the female ten shekels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 6, E'And if it be from a month old even unto five years old, then thy estimation shall be of the male five shekels of silver, and for the female thy estimation shall be three shekels of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 7, E'And if it be from sixty years old and above; if it be a male, then thy estimation shall be fifteen shekels, and for the female ten shekels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 8, E'But if he be poorer than thy estimation, then he shall present himself before the priest, and the priest shall value him; according to his ability that vowed shall the priest value him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 9, E'And if it be a beast, whereof men bring an offering unto the LORD, all that any man giveth of such unto the LORD shall be holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 10, E'He shall not alter it, nor change it, a good for a bad, or a bad for a good: and if he shall at all change beast for beast, then it and the exchange thereof shall be holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 11, E'And if it be any unclean beast, of which they do not offer a sacrifice unto the LORD, then he shall present the beast before the priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 12, E'And the priest shall value it, whether it be good or bad: as thou valuest it, who art the priest, so shall it be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 13, E'But if he will at all redeem it, then he shall add a fifth part thereof unto thy estimation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 14, E'And when a man shall sanctify his house to be holy unto the LORD, then the priest shall estimate it, whether it be good or bad: as the priest shall estimate it, so shall it stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 15, E'And if he that sanctified it will redeem his house, then he shall add the fifth part of the money of thy estimation unto it, and it shall be his.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 16, E'And if a man shall sanctify unto the LORD some part of a field of his possession, then thy estimation shall be according to the seed thereof: an homer of barley seed shall be valued at fifty shekels of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 17, E'If he sanctify his field from the year of jubile, according to thy estimation it shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 18, E'But if he sanctify his field after the jubile, then the priest shall reckon unto him the money according to the years that remain, even unto the year of the jubile, and it shall be abated from thy estimation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 19, E'And if he that sanctified the field will in any wise redeem it, then he shall add the fifth part of the money of thy estimation unto it, and it shall be assured to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 20, E'And if he will not redeem the field, or if he have sold the field to another man, it shall not be redeemed any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 21, E'But the field, when it goeth out in the jubile, shall be holy unto the LORD, as a field devoted; the possession thereof shall be the priest’s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 22, E'And if a man sanctify unto the LORD a field which he hath bought, which is not of the fields of his possession;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 23, E'Then the priest shall reckon unto him the worth of thy estimation, even unto the year of the jubile: and he shall give thine estimation in that day, as a holy thing unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 24, E'In the year of the jubile the field shall return unto him of whom it was bought, even to him to whom the possession of the land did belong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 25, E'And all thy estimations shall be according to the shekel of the sanctuary: twenty gerahs shall be the shekel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 26, E'Only the firstling of the beasts, which should be the LORD’s firstling, no man shall sanctify it; whether it be ox, or sheep: it is the LORD’s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 27, E'And if it be of an unclean beast, then he shall redeem it according to thine estimation, and shall add a fifth part of it thereto: or if it be not redeemed, then it shall be sold according to thy estimation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 28, E'Notwithstanding no devoted thing, that a man shall devote unto the LORD of all that he hath, both of man and beast, and of the field of his possession, shall be sold or redeemed: every devoted thing is most holy unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 29, E'None devoted, which shall be devoted of men, shall be redeemed; but shall surely be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 30, E'And all the tithe of the land, whether of the seed of the land, or of the fruit of the tree, is the LORD’s: it is holy unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 31, E'And if a man will at all redeem ought of his tithes, he shall add thereto the fifth part thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 32, E'And concerning the tithe of the herd, or of the flock, even of whatsoever passeth under the rod, the tenth shall be holy unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 33, E'He shall not search whether it be good or bad, neither shall he change it: and if he change it at all, then both it and the change thereof shall be holy; it shall not be redeemed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0bb75f1e-73ae-4cb1-814b-76660e8be37f', 27, 34, E'These are the commandments, which the LORD commanded Moses for the children of Israel in mount Sinai.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Leviticus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 1, E'And the LORD spake unto Moses in the wilderness of Sinai, in the tabernacle of the congregation, on the first day of the second month, in the second year after they were come out of the land of Egypt, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 2, E'Take ye the sum of all the congregation of the children of Israel, after their families, by the house of their fathers, with the number of their names, every male by their polls;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 3, E'From twenty years old and upward, all that are able to go forth to war in Israel: thou and Aaron shall number them by their armies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 4, E'And with you there shall be a man of every tribe; every one head of the house of his fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 5, E'And these are the names of the men that shall stand with you: of the tribe of Reuben; Elizur the son of Shedeur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 6, E'Of Simeon; Shelumiel the son of Zurishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 7, E'Of Judah; Nahshon the son of Amminadab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 8, E'Of Issachar; Nethaneel the son of Zuar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 9, E'Of Zebulun; Eliab the son of Helon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 10, E'Of the children of Joseph: of Ephraim; Elishama the son of Ammihud: of Manasseh; Gamaliel the son of Pedahzur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 11, E'Of Benjamin; Abidan the son of Gideoni.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 12, E'Of Dan; Ahiezer the son of Ammishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 13, E'Of Asher; Pagiel the son of Ocran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 14, E'Of Gad; Eliasaph the son of Deuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 15, E'Of Naphtali; Ahira the son of Enan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 16, E'These were the renowned of the congregation, princes of the tribes of their fathers, heads of thousands in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 17, E'And Moses and Aaron took these men which are expressed by their names:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 18, E'And they assembled all the congregation together on the first day of the second month, and they declared their pedigrees after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, by their polls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 19, E'As the LORD commanded Moses, so he numbered them in the wilderness of Sinai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 20, E'And the children of Reuben, Israel’s eldest son, by their generations, after their families, by the house of their fathers, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 21, E'Those that were numbered of them, even of the tribe of Reuben, were forty and six thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 22, E'Of the children of Simeon, by their generations, after their families, by the house of their fathers, those that were numbered of them, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 23, E'Those that were numbered of them, even of the tribe of Simeon, were fifty and nine thousand and three hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 24, E'Of the children of Gad, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 25, E'Those that were numbered of them, even of the tribe of Gad, were forty and five thousand six hundred and fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 26, E'Of the children of Judah, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 27, E'Those that were numbered of them, even of the tribe of Judah, were threescore and fourteen thousand and six hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 28, E'Of the children of Issachar, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 29, E'Those that were numbered of them, even of the tribe of Issachar, were fifty and four thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 30, E'Of the children of Zebulun, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 31, E'Those that were numbered of them, even of the tribe of Zebulun, were fifty and seven thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 32, E'Of the children of Joseph, namely, of the children of Ephraim, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 33, E'Those that were numbered of them, even of the tribe of Ephraim, were forty thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 34, E'Of the children of Manasseh, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 35, E'Those that were numbered of them, even of the tribe of Manasseh, were thirty and two thousand and two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 36, E'Of the children of Benjamin, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 37, E'Those that were numbered of them, even of the tribe of Benjamin, were thirty and five thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 38, E'Of the children of Dan, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 39, E'Those that were numbered of them, even of the tribe of Dan, were threescore and two thousand and seven hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 40, E'Of the children of Asher, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 41, E'Those that were numbered of them, even of the tribe of Asher, were forty and one thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 42, E'Of the children of Naphtali, throughout their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 43, E'Those that were numbered of them, even of the tribe of Naphtali, were fifty and three thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 44, E'These are those that were numbered, which Moses and Aaron numbered, and the princes of Israel, being twelve men: each one was for the house of his fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 45, E'So were all those that were numbered of the children of Israel, by the house of their fathers, from twenty years old and upward, all that were able to go forth to war in Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 46, E'Even all they that were numbered were six hundred thousand and three thousand and five hundred and fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 47, E'But the Levites after the tribe of their fathers were not numbered among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 48, E'For the LORD had spoken unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 49, E'Only thou shalt not number the tribe of Levi, neither take the sum of them among the children of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 50, E'But thou shalt appoint the Levites over the tabernacle of testimony, and over all the vessels thereof, and over all things that belong to it: they shall bear the tabernacle, and all the vessels thereof; and they shall minister unto it, and shall encamp round about the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 51, E'And when the tabernacle setteth forward, the Levites shall take it down: and when the tabernacle is to be pitched, the Levites shall set it up: and the stranger that cometh nigh shall be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 52, E'And the children of Israel shall pitch their tents, every man by his own camp, and every man by his own standard, throughout their hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 53, E'But the Levites shall pitch round about the tabernacle of testimony, that there be no wrath upon the congregation of the children of Israel: and the Levites shall keep the charge of the tabernacle of testimony.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 1, 54, E'And the children of Israel did according to all that the LORD commanded Moses, so did they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 1, E'And the LORD spake unto Moses and unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 2, E'Every man of the children of Israel shall pitch by his own standard, with the ensign of their father’s house: far off about the tabernacle of the congregation shall they pitch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 3, E'And on the east side toward the rising of the sun shall they of the standard of the camp of Judah pitch throughout their armies: and Nahshon the son of Amminadab shall be captain of the children of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 4, E'And his host, and those that were numbered of them, were threescore and fourteen thousand and six hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 5, E'And those that do pitch next unto him shall be the tribe of Issachar: and Nethaneel the son of Zuar shall be captain of the children of Issachar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 6, E'And his host, and those that were numbered thereof, were fifty and four thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 7, E'Then the tribe of Zebulun: and Eliab the son of Helon shall be captain of the children of Zebulun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 8, E'And his host, and those that were numbered thereof, were fifty and seven thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 9, E'All that were numbered in the camp of Judah were an hundred thousand and fourscore thousand and six thousand and four hundred, throughout their armies. These shall first set forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 10, E'On the south side shall be the standard of the camp of Reuben according to their armies: and the captain of the children of Reuben shall be Elizur the son of Shedeur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 11, E'And his host, and those that were numbered thereof, were forty and six thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 12, E'And those which pitch by him shall be the tribe of Simeon: and the captain of the children of Simeon shall be Shelumiel the son of Zurishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 13, E'And his host, and those that were numbered of them, were fifty and nine thousand and three hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 14, E'Then the tribe of Gad: and the captain of the sons of Gad shall be Eliasaph the son of Reuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 15, E'And his host, and those that were numbered of them, were forty and five thousand and six hundred and fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 16, E'All that were numbered in the camp of Reuben were an hundred thousand and fifty and one thousand and four hundred and fifty, throughout their armies. And they shall set forth in the second rank.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 17, E'Then the tabernacle of the congregation shall set forward with the camp of the Levites in the midst of the camp: as they encamp, so shall they set forward, every man in his place by their standards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 18, E'On the west side shall be the standard of the camp of Ephraim according to their armies: and the captain of the sons of Ephraim shall be Elishama the son of Ammihud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 19, E'And his host, and those that were numbered of them, were forty thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 20, E'And by him shall be the tribe of Manasseh: and the captain of the children of Manasseh shall be Gamaliel the son of Pedahzur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 21, E'And his host, and those that were numbered of them, were thirty and two thousand and two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 22, E'Then the tribe of Benjamin: and the captain of the sons of Benjamin shall be Abidan the son of Gideoni.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 23, E'And his host, and those that were numbered of them, were thirty and five thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 24, E'All that were numbered of the camp of Ephraim were an hundred thousand and eight thousand and an hundred, throughout their armies. And they shall go forward in the third rank.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 25, E'The standard of the camp of Dan shall be on the north side by their armies: and the captain of the children of Dan shall be Ahiezer the son of Ammishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 26, E'And his host, and those that were numbered of them, were threescore and two thousand and seven hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 27, E'And those that encamp by him shall be the tribe of Asher: and the captain of the children of Asher shall be Pagiel the son of Ocran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 28, E'And his host, and those that were numbered of them, were forty and one thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 29, E'Then the tribe of Naphtali: and the captain of the children of Naphtali shall be Ahira the son of Enan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 30, E'And his host, and those that were numbered of them, were fifty and three thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 31, E'All they that were numbered in the camp of Dan were an hundred thousand and fifty and seven thousand and six hundred. They shall go hindmost with their standards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 32, E'These are those which were numbered of the children of Israel by the house of their fathers: all those that were numbered of the camps throughout their hosts were six hundred thousand and three thousand and five hundred and fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 33, E'But the Levites were not numbered among the children of Israel; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 2, 34, E'And the children of Israel did according to all that the LORD commanded Moses: so they pitched by their standards, and so they set forward, every one after their families, according to the house of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 1, E'These also are the generations of Aaron and Moses in the day that the LORD spake with Moses in mount Sinai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 2, E'And these are the names of the sons of Aaron; Nadab the firstborn, and Abihu, Eleazar, and Ithamar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 3, E'These are the names of the sons of Aaron, the priests which were anointed, whom he consecrated to minister in the priest’s office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 4, E'And Nadab and Abihu died before the LORD, when they offered strange fire before the LORD, in the wilderness of Sinai, and they had no children: and Eleazar and Ithamar ministered in the priest’s office in the sight of Aaron their father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 5, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 6, E'Bring the tribe of Levi near, and present them before Aaron the priest, that they may minister unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 7, E'And they shall keep his charge, and the charge of the whole congregation before the tabernacle of the congregation, to do the service of the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 8, E'And they shall keep all the instruments of the tabernacle of the congregation, and the charge of the children of Israel, to do the service of the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 9, E'And thou shalt give the Levites unto Aaron and to his sons: they are wholly given unto him out of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 10, E'And thou shalt appoint Aaron and his sons, and they shall wait on their priest’s office: and the stranger that cometh nigh shall be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 11, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 12, E'And I, behold, I have taken the Levites from among the children of Israel instead of all the firstborn that openeth the matrix among the children of Israel: therefore the Levites shall be mine;')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 13, E'Because all the firstborn are mine; for on the day that I smote all the firstborn in the land of Egypt I hallowed unto me all the firstborn in Israel, both man and beast: mine shall they be: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 14, E'And the LORD spake unto Moses in the wilderness of Sinai, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 15, E'Number the children of Levi after the house of their fathers, by their families: every male from a month old and upward shalt thou number them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 16, E'And Moses numbered them according to the word of the LORD, as he was commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 17, E'And these were the sons of Levi by their names; Gershon, and Kohath, and Merari.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 18, E'And these are the names of the sons of Gershon by their families; Libni, and Shimei.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 19, E'And the sons of Kohath by their families; Amram, and Izehar, Hebron, and Uzziel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 20, E'And the sons of Merari by their families; Mahli, and Mushi. These are the families of the Levites according to the house of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 21, E'Of Gershon was the family of the Libnites, and the family of the Shimites: these are the families of the Gershonites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 22, E'Those that were numbered of them, according to the number of all the males, from a month old and upward, even those that were numbered of them were seven thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 23, E'The families of the Gershonites shall pitch behind the tabernacle westward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 24, E'And the chief of the house of the father of the Gershonites shall be Eliasaph the son of Lael.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 25, E'And the charge of the sons of Gershon in the tabernacle of the congregation shall be the tabernacle, and the tent, the covering thereof, and the hanging for the door of the tabernacle of the congregation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 26, E'And the hangings of the court, and the curtain for the door of the court, which is by the tabernacle, and by the altar round about, and the cords of it for all the service thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 27, E'And of Kohath was the family of the Amramites, and the family of the Izeharites, and the family of the Hebronites, and the family of the Uzzielites: these are the families of the Kohathites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 28, E'In the number of all the males, from a month old and upward, were eight thousand and six hundred, keeping the charge of the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 29, E'The families of the sons of Kohath shall pitch on the side of the tabernacle southward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 30, E'And the chief of the house of the father of the families of the Kohathites shall be Elizaphan the son of Uzziel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 31, E'And their charge shall be the ark, and the table, and the candlestick, and the altars, and the vessels of the sanctuary wherewith they minister, and the hanging, and all the service thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 32, E'And Eleazar the son of Aaron the priest shall be chief over the chief of the Levites, and have the oversight of them that keep the charge of the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 33, E'Of Merari was the family of the Mahlites, and the family of the Mushites: these are the families of Merari.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 34, E'And those that were numbered of them, according to the number of all the males, from a month old and upward, were six thousand and two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 35, E'And the chief of the house of the father of the families of Merari was Zuriel the son of Abihail: these shall pitch on the side of the tabernacle northward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 36, E'And under the custody and charge of the sons of Merari shall be the boards of the tabernacle, and the bars thereof, and the pillars thereof, and the sockets thereof, and all the vessels thereof, and all that serveth thereto,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 37, E'And the pillars of the court round about, and their sockets, and their pins, and their cords.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 38, E'But those that encamp before the tabernacle toward the east, even before the tabernacle of the congregation eastward, shall be Moses, and Aaron and his sons, keeping the charge of the sanctuary for the charge of the children of Israel; and the stranger that cometh nigh shall be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 39, E'All that were numbered of the Levites, which Moses and Aaron numbered at the commandment of the LORD, throughout their families, all the males from a month old and upward, were twenty and two thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 40, E'And the LORD said unto Moses, Number all the firstborn of the males of the children of Israel from a month old and upward, and take the number of their names.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 41, E'And thou shalt take the Levites for me (I am the LORD) instead of all the firstborn among the children of Israel; and the cattle of the Levites instead of all the firstlings among the cattle of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 42, E'And Moses numbered, as the LORD commanded him, all the firstborn among the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 43, E'And all the firstborn males by the number of names, from a month old and upward, of those that were numbered of them, were twenty and two thousand two hundred and threescore and thirteen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 44, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 45, E'Take the Levites instead of all the firstborn among the children of Israel, and the cattle of the Levites instead of their cattle; and the Levites shall be mine: I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 46, E'And for those that are to be redeemed of the two hundred and threescore and thirteen of the firstborn of the children of Israel, which are more than the Levites;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 47, E'Thou shalt even take five shekels apiece by the poll, after the shekel of the sanctuary shalt thou take them: (the shekel is twenty gerahs:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 48, E'And thou shalt give the money, wherewith the odd number of them is to be redeemed, unto Aaron and to his sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 49, E'And Moses took the redemption money of them that were over and above them that were redeemed by the Levites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 50, E'Of the firstborn of the children of Israel took he the money; a thousand three hundred and threescore and five shekels, after the shekel of the sanctuary:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 3, 51, E'And Moses gave the money of them that were redeemed unto Aaron and to his sons, according to the word of the LORD, as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 1, E'And the LORD spake unto Moses and unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 2, E'Take the sum of the sons of Kohath from among the sons of Levi, after their families, by the house of their fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 3, E'From thirty years old and upward even until fifty years old, all that enter into the host, to do the work in the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 4, E'This shall be the service of the sons of Kohath in the tabernacle of the congregation, about the most holy things:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 5, E'And when the camp setteth forward, Aaron shall come, and his sons, and they shall take down the covering vail, and cover the ark of testimony with it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 6, E'And shall put thereon the covering of badgers’ skins, and shall spread over it a cloth wholly of blue, and shall put in the staves thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 7, E'And upon the table of shewbread they shall spread a cloth of blue, and put thereon the dishes, and the spoons, and the bowls, and covers to cover withal: and the continual bread shall be thereon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 8, E'And they shall spread upon them a cloth of scarlet, and cover the same with a covering of badgers’ skins, and shall put in the staves thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 9, E'And they shall take a cloth of blue, and cover the candlestick of the light, and his lamps, and his tongs, and his snuffdishes, and all the oil vessels thereof, wherewith they minister unto it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 10, E'And they shall put it and all the vessels thereof within a covering of badgers’ skins, and shall put it upon a bar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 11, E'And upon the golden altar they shall spread a cloth of blue, and cover it with a covering of badgers’ skins, and shall put to the staves thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 12, E'And they shall take all the instruments of ministry, wherewith they minister in the sanctuary, and put them in a cloth of blue, and cover them with a covering of badgers’ skins, and shall put them on a bar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 13, E'And they shall take away the ashes from the altar, and spread a purple cloth thereon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 14, E'And they shall put upon it all the vessels thereof, wherewith they minister about it, even the censers, the fleshhooks, and the shovels, and the basons, all the vessels of the altar; and they shall spread upon it a covering of badgers’ skins, and put to the staves of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 15, E'And when Aaron and his sons have made an end of covering the sanctuary, and all the vessels of the sanctuary, as the camp is to set forward; after that, the sons of Kohath shall come to bear it: but they shall not touch any holy thing, lest they die. These things are the burden of the sons of Kohath in the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 16, E'And to the office of Eleazar the son of Aaron the priest pertaineth the oil for the light, and the sweet incense, and the daily meat offering, and the anointing oil, and the oversight of all the tabernacle, and of all that therein is, in the sanctuary, and in the vessels thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 17, E'And the LORD spake unto Moses and unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 18, E'Cut ye not off the tribe of the families of the Kohathites from among the Levites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 19, E'But thus do unto them, that they may live, and not die, when they approach unto the most holy things: Aaron and his sons shall go in, and appoint them every one to his service and to his burden:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 20, E'But they shall not go in to see when the holy things are covered, lest they die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 21, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 22, E'Take also the sum of the sons of Gershon, throughout the houses of their fathers, by their families;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 23, E'From thirty years old and upward until fifty years old shalt thou number them; all that enter in to perform the service, to do the work in the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 24, E'This is the service of the families of the Gershonites, to serve, and for burdens:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 25, E'And they shall bear the curtains of the tabernacle, and the tabernacle of the congregation, his covering, and the covering of the badgers’ skins that is above upon it, and the hanging for the door of the tabernacle of the congregation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 26, E'And the hangings of the court, and the hanging for the door of the gate of the court, which is by the tabernacle and by the altar round about, and their cords, and all the instruments of their service, and all that is made for them: so shall they serve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 27, E'At the appointment of Aaron and his sons shall be all the service of the sons of the Gershonites, in all their burdens, and in all their service: and ye shall appoint unto them in charge all their burdens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 28, E'This is the service of the families of the sons of Gershon in the tabernacle of the congregation: and their charge shall be under the hand of Ithamar the son of Aaron the priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 29, E'As for the sons of Merari, thou shalt number them after their families, by the house of their fathers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 30, E'From thirty years old and upward even unto fifty years old shalt thou number them, every one that entereth into the service, to do the work of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 31, E'And this is the charge of their burden, according to all their service in the tabernacle of the congregation; the boards of the tabernacle, and the bars thereof, and the pillars thereof, and sockets thereof,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 32, E'And the pillars of the court round about, and their sockets, and their pins, and their cords, with all their instruments, and with all their service: and by name ye shall reckon the instruments of the charge of their burden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 33, E'This is the service of the families of the sons of Merari, according to all their service, in the tabernacle of the congregation, under the hand of Ithamar the son of Aaron the priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 34, E'And Moses and Aaron and the chief of the congregation numbered the sons of the Kohathites after their families, and after the house of their fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 35, E'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 36, E'And those that were numbered of them by their families were two thousand seven hundred and fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 37, E'These were they that were numbered of the families of the Kohathites, all that might do service in the tabernacle of the congregation, which Moses and Aaron did number according to the commandment of the LORD by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 38, E'And those that were numbered of the sons of Gershon, throughout their families, and by the house of their fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 39, E'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 40, E'Even those that were numbered of them, throughout their families, by the house of their fathers, were two thousand and six hundred and thirty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 41, E'These are they that were numbered of the families of the sons of Gershon, of all that might do service in the tabernacle of the congregation, whom Moses and Aaron did number according to the commandment of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 42, E'And those that were numbered of the families of the sons of Merari, throughout their families, by the house of their fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 43, E'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 44, E'Even those that were numbered of them after their families, were three thousand and two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 45, E'These be those that were numbered of the families of the sons of Merari, whom Moses and Aaron numbered according to the word of the LORD by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 46, E'All those that were numbered of the Levites, whom Moses and Aaron and the chief of Israel numbered, after their families, and after the house of their fathers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 47, E'From thirty years old and upward even unto fifty years old, every one that came to do the service of the ministry, and the service of the burden in the tabernacle of the congregation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 48, E'Even those that were numbered of them, were eight thousand and five hundred and fourscore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 4, 49, E'According to the commandment of the LORD they were numbered by the hand of Moses, every one according to his service, and according to his burden: thus were they numbered of him, as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 2, E'Command the children of Israel, that they put out of the camp every leper, and every one that hath an issue, and whosoever is defiled by the dead:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 3, E'Both male and female shall ye put out, without the camp shall ye put them; that they defile not their camps, in the midst whereof I dwell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 4, E'And the children of Israel did so, and put them out without the camp: as the LORD spake unto Moses, so did the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 5, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 6, E'Speak unto the children of Israel, When a man or woman shall commit any sin that men commit, to do a trespass against the LORD, and that person be guilty;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 7, E'Then they shall confess their sin which they have done: and he shall recompense his trespass with the principal thereof, and add unto it the fifth part thereof, and give it unto him against whom he hath trespassed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 8, E'But if the man have no kinsman to recompense the trespass unto, let the trespass be recompensed unto the LORD, even to the priest; beside the ram of the atonement, whereby an atonement shall be made for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 9, E'And every offering of all the holy things of the children of Israel, which they bring unto the priest, shall be his.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 10, E'And every man’s hallowed things shall be his: whatsoever any man giveth the priest, it shall be his.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 11, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 12, E'Speak unto the children of Israel, and say unto them, If any man’s wife go aside, and commit a trespass against him,')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 13, E'And a man lie with her carnally, and it be hid from the eyes of her husband, and be kept close, and she be defiled, and there be no witness against her, neither she be taken with the manner;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 14, E'And the spirit of jealousy come upon him, and he be jealous of his wife, and she be defiled: or if the spirit of jealousy come upon him, and he be jealous of his wife, and she be not defiled:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 15, E'Then shall the man bring his wife unto the priest, and he shall bring her offering for her, the tenth part of an ephah of barley meal; he shall pour no oil upon it, nor put frankincense thereon; for it is an offering of jealousy, an offering of memorial, bringing iniquity to remembrance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 16, E'And the priest shall bring her near, and set her before the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 17, E'And the priest shall take holy water in an earthen vessel; and of the dust that is in the floor of the tabernacle the priest shall take, and put it into the water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 18, E'And the priest shall set the woman before the LORD, and uncover the woman’s head, and put the offering of memorial in her hands, which is the jealousy offering: and the priest shall have in his hand the bitter water that causeth the curse:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 19, E'And the priest shall charge her by an oath, and say unto the woman, If no man have lain with thee, and if thou hast not gone aside to uncleanness with another instead of thy husband, be thou free from this bitter water that causeth the curse:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 20, E'But if thou hast gone aside to another instead of thy husband, and if thou be defiled, and some man have lain with thee beside thine husband:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 21, E'Then the priest shall charge the woman with an oath of cursing, and the priest shall say unto the woman, The LORD make thee a curse and an oath among thy people, when the LORD doth make thy thigh to rot, and thy belly to swell;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 22, E'And this water that causeth the curse shall go into thy bowels, to make thy belly to swell, and thy thigh to rot: And the woman shall say, Amen, amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 23, E'And the priest shall write these curses in a book, and he shall blot them out with the bitter water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 24, E'And he shall cause the woman to drink the bitter water that causeth the curse: and the water that causeth the curse shall enter into her, and become bitter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 25, E'Then the priest shall take the jealousy offering out of the woman’s hand, and shall wave the offering before the LORD, and offer it upon the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 26, E'And the priest shall take an handful of the offering, even the memorial thereof, and burn it upon the altar, and afterward shall cause the woman to drink the water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 27, E'And when he hath made her to drink the water, then it shall come to pass, that, if she be defiled, and have done trespass against her husband, that the water that causeth the curse shall enter into her, and become bitter, and her belly shall swell, and her thigh shall rot: and the woman shall be a curse among her people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 28, E'And if the woman be not defiled, but be clean; then she shall be free, and shall conceive seed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 29, E'This is the law of jealousies, when a wife goeth aside to another instead of her husband, and is defiled;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 30, E'Or when the spirit of jealousy cometh upon him, and he be jealous over his wife, and shall set the woman before the LORD, and the priest shall execute upon her all this law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 5, 31, E'Then shall the man be guiltless from iniquity, and this woman shall bear her iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 2, E'Speak unto the children of Israel, and say unto them, When either man or woman shall separate themselves to vow a vow of a Nazarite, to separate themselves unto the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 3, E'He shall separate himself from wine and strong drink, and shall drink no vinegar of wine, or vinegar of strong drink, neither shall he drink any liquor of grapes, nor eat moist grapes, or dried.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 4, E'All the days of his separation shall he eat nothing that is made of the vine tree, from the kernels even to the husk.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 5, E'All the days of the vow of his separation there shall no razor come upon his head: until the days be fulfilled, in the which he separateth himself unto the LORD, he shall be holy, and shall let the locks of the hair of his head grow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 6, E'All the days that he separateth himself unto the LORD he shall come at no dead body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 7, E'He shall not make himself unclean for his father, or for his mother, for his brother, or for his sister, when they die: because the consecration of his God is upon his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 8, E'All the days of his separation he is holy unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 9, E'And if any man die very suddenly by him, and he hath defiled the head of his consecration; then he shall shave his head in the day of his cleansing, on the seventh day shall he shave it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 10, E'And on the eighth day he shall bring two turtles, or two young pigeons, to the priest, to the door of the tabernacle of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 11, E'And the priest shall offer the one for a sin offering, and the other for a burnt offering, and make an atonement for him, for that he sinned by the dead, and shall hallow his head that same day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 12, E'And he shall consecrate unto the LORD the days of his separation, and shall bring a lamb of the first year for a trespass offering: but the days that were before shall be lost, because his separation was defiled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 13, E'And this is the law of the Nazarite, when the days of his separation are fulfilled: he shall be brought unto the door of the tabernacle of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 14, E'And he shall offer his offering unto the LORD, one he lamb of the first year without blemish for a burnt offering, and one ewe lamb of the first year without blemish for a sin offering, and one ram without blemish for peace offerings,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 15, E'And a basket of unleavened bread, cakes of fine flour mingled with oil, and wafers of unleavened bread anointed with oil, and their meat offering, and their drink offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 16, E'And the priest shall bring them before the LORD, and shall offer his sin offering, and his burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 17, E'And he shall offer the ram for a sacrifice of peace offerings unto the LORD, with the basket of unleavened bread: the priest shall offer also his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 18, E'And the Nazarite shall shave the head of his separation at the door of the tabernacle of the congregation, and shall take the hair of the head of his separation, and put it in the fire which is under the sacrifice of the peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 19, E'And the priest shall take the sodden shoulder of the ram, and one unleavened cake out of the basket, and one unleavened wafer, and shall put them upon the hands of the Nazarite, after the hair of his separation is shaven:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 20, E'And the priest shall wave them for a wave offering before the LORD: this is holy for the priest, with the wave breast and heave shoulder: and after that the Nazarite may drink wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 21, E'This is the law of the Nazarite who hath vowed, and of his offering unto the LORD for his separation, beside that that his hand shall get: according to the vow which he vowed, so he must do after the law of his separation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 22, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 23, E'Speak unto Aaron and unto his sons, saying, On this wise ye shall bless the children of Israel, saying unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 24, E'The LORD bless thee, and keep thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 25, E'The LORD make his face shine upon thee, and be gracious unto thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 26, E'The LORD lift up his countenance upon thee, and give thee peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 6, 27, E'And they shall put my name upon the children of Israel; and I will bless them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 1, E'And it came to pass on the day that Moses had fully set up the tabernacle, and had anointed it, and sanctified it, and all the instruments thereof, both the altar and all the vessels thereof, and had anointed them, and sanctified them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 2, E'That the princes of Israel, heads of the house of their fathers, who were the princes of the tribes, and were over them that were numbered, offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 3, E'And they brought their offering before the LORD, six covered wagons, and twelve oxen; a wagon for two of the princes, and for each one an ox: and they brought them before the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 4, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 5, E'Take it of them, that they may be to do the service of the tabernacle of the congregation; and thou shalt give them unto the Levites, to every man according to his service.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 6, E'And Moses took the wagons and the oxen, and gave them unto the Levites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 7, E'Two wagons and four oxen he gave unto the sons of Gershon, according to their service:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 8, E'And four wagons and eight oxen he gave unto the sons of Merari, according unto their service, under the hand of Ithamar the son of Aaron the priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 9, E'But unto the sons of Kohath he gave none: because the service of the sanctuary belonging unto them was that they should bear upon their shoulders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 10, E'And the princes offered for dedicating of the altar in the day that it was anointed, even the princes offered their offering before the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 11, E'And the LORD said unto Moses, They shall offer their offering, each prince on his day, for the dedicating of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 12, E'And he that offered his offering the first day was Nahshon the son of Amminadab, of the tribe of Judah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 13, E'And his offering was one silver charger, the weight thereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them were full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 14, E'One spoon of ten shekels of gold, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 15, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 16, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 17, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nahshon the son of Amminadab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 18, E'On the second day Nethaneel the son of Zuar, prince of Issachar, did offer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 19, E'He offered for his offering one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 20, E'One spoon of gold of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 21, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 22, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 23, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nethaneel the son of Zuar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 24, E'On the third day Eliab the son of Helon, prince of the children of Zebulun, did offer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 25, E'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 26, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 27, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 28, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 29, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliab the son of Helon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 30, E'On the fourth day Elizur the son of Shedeur, prince of the children of Reuben, did offer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 31, E'His offering was one silver charger of the weight of an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 32, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 33, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 34, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 35, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Elizur the son of Shedeur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 36, E'On the fifth day Shelumiel the son of Zurishaddai, prince of the children of Simeon, did offer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 37, E'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 38, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 39, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 40, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 41, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Shelumiel the son of Zurishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 42, E'On the sixth day Eliasaph the son of Deuel, prince of the children of Gad, offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 43, E'His offering was one silver charger of the weight of an hundred and thirty shekels, a silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 44, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 45, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 46, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 47, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliasaph the son of Deuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 48, E'On the seventh day Elishama the son of Ammihud, prince of the children of Ephraim, offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 49, E'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 50, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 51, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 52, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 53, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Elishama the son of Ammihud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 54, E'On the eighth day offered Gamaliel the son of Pedahzur, prince of the children of Manasseh:')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 55, E'His offering was one silver charger of the weight of an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 56, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 57, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 58, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 59, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Gamaliel the son of Pedahzur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 60, E'On the ninth day Abidan the son of Gideoni, prince of the children of Benjamin, offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 61, E'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 62, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 63, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 64, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 65, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Abidan the son of Gideoni.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 66, E'On the tenth day Ahiezer the son of Ammishaddai, prince of the children of Dan, offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 67, E'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 68, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 69, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 70, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 71, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Ahiezer the son of Ammishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 72, E'On the eleventh day Pagiel the son of Ocran, prince of the children of Asher, offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 73, E'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 74, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 75, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 76, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 77, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Pagiel the son of Ocran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 78, E'On the twelfth day Ahira the son of Enan, prince of the children of Naphtali, offered:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 79, E'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 80, E'One golden spoon of ten shekels, full of incense:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 81, E'One young bullock, one ram, one lamb of the first year, for a burnt offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 82, E'One kid of the goats for a sin offering:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 83, E'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Ahira the son of Enan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 84, E'This was the dedication of the altar, in the day when it was anointed, by the princes of Israel: twelve chargers of silver, twelve silver bowls, twelve spoons of gold:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 85, E'Each charger of silver weighing an hundred and thirty shekels, each bowl seventy: all the silver vessels weighed two thousand and four hundred shekels, after the shekel of the sanctuary:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 86, E'The golden spoons were twelve, full of incense, weighing ten shekels apiece, after the shekel of the sanctuary: all the gold of the spoons was an hundred and twenty shekels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 87, E'All the oxen for the burnt offering were twelve bullocks, the rams twelve, the lambs of the first year twelve, with their meat offering: and the kids of the goats for sin offering twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 88, E'And all the oxen for the sacrifice of the peace offerings were twenty and four bullocks, the rams sixty, the he goats sixty, the lambs of the first year sixty. This was the dedication of the altar, after that it was anointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 7, 89, E'And when Moses was gone into the tabernacle of the congregation to speak with him, then he heard the voice of one speaking unto him from off the mercy seat that was upon the ark of testimony, from between the two cherubims: and he spake unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 2, E'Speak unto Aaron, and say unto him, When thou lightest the lamps, the seven lamps shall give light over against the candlestick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 3, E'And Aaron did so; he lighted the lamps thereof over against the candlestick, as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 4, E'And this work of the candlestick was of beaten gold, unto the shaft thereof, unto the flowers thereof, was beaten work: according unto the pattern which the LORD had shewed Moses, so he made the candlestick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 5, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 6, E'Take the Levites from among the children of Israel, and cleanse them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 7, E'And thus shalt thou do unto them, to cleanse them: Sprinkle water of purifying upon them, and let them shave all their flesh, and let them wash their clothes, and so make themselves clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 8, E'Then let them take a young bullock with his meat offering, even fine flour mingled with oil, and another young bullock shalt thou take for a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 9, E'And thou shalt bring the Levites before the tabernacle of the congregation: and thou shalt gather the whole assembly of the children of Israel together:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 10, E'And thou shalt bring the Levites before the LORD: and the children of Israel shall put their hands upon the Levites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 11, E'And Aaron shall offer the Levites before the LORD for an offering of the children of Israel, that they may execute the service of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 12, E'And the Levites shall lay their hands upon the heads of the bullocks: and thou shalt offer the one for a sin offering, and the other for a burnt offering, unto the LORD, to make an atonement for the Levites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 13, E'And thou shalt set the Levites before Aaron, and before his sons, and offer them for an offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 14, E'Thus shalt thou separate the Levites from among the children of Israel: and the Levites shall be mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 15, E'And after that shall the Levites go in to do the service of the tabernacle of the congregation: and thou shalt cleanse them, and offer them for an offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 16, E'For they are wholly given unto me from among the children of Israel; instead of such as open every womb, even instead of the firstborn of all the children of Israel, have I taken them unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 17, E'For all the firstborn of the children of Israel are mine, both man and beast: on the day that I smote every firstborn in the land of Egypt I sanctified them for myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 18, E'And I have taken the Levites for all the firstborn of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 19, E'And I have given the Levites as a gift to Aaron and to his sons from among the children of Israel, to do the service of the children of Israel in the tabernacle of the congregation, and to make an atonement for the children of Israel: that there be no plague among the children of Israel, when the children of Israel come nigh unto the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 20, E'And Moses, and Aaron, and all the congregation of the children of Israel, did to the Levites according unto all that the LORD commanded Moses concerning the Levites, so did the children of Israel unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 21, E'And the Levites were purified, and they washed their clothes; and Aaron offered them as an offering before the LORD; and Aaron made an atonement for them to cleanse them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 22, E'And after that went the Levites in to do their service in the tabernacle of the congregation before Aaron, and before his sons: as the LORD had commanded Moses concerning the Levites, so did they unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 23, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 24, E'This is it that belongeth unto the Levites: from twenty and five years old and upward they shall go in to wait upon the service of the tabernacle of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 25, E'And from the age of fifty years they shall cease waiting upon the service thereof, and shall serve no more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 8, 26, E'But shall minister with their brethren in the tabernacle of the congregation, to keep the charge, and shall do no service. Thus shalt thou do unto the Levites touching their charge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 1, E'And the LORD spake unto Moses in the wilderness of Sinai, in the first month of the second year after they were come out of the land of Egypt, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 2, E'Let the children of Israel also keep the passover at his appointed season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 3, E'In the fourteenth day of this month, at even, ye shall keep it in his appointed season: according to all the rites of it, and according to all the ceremonies thereof, shall ye keep it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 4, E'And Moses spake unto the children of Israel, that they should keep the passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 5, E'And they kept the passover on the fourteenth day of the first month at even in the wilderness of Sinai: according to all that the LORD commanded Moses, so did the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 6, E'And there were certain men, who were defiled by the dead body of a man, that they could not keep the passover on that day: and they came before Moses and before Aaron on that day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 7, E'And those men said unto him, We are defiled by the dead body of a man: wherefore are we kept back, that we may not offer an offering of the LORD in his appointed season among the children of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 8, E'And Moses said unto them, Stand still, and I will hear what the LORD will command concerning you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 9, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 10, E'Speak unto the children of Israel, saying, If any man of you or of your posterity shall be unclean by reason of a dead body, or be in a journey afar off, yet he shall keep the passover unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 11, E'The fourteenth day of the second month at even they shall keep it, and eat it with unleavened bread and bitter herbs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 12, E'They shall leave none of it unto the morning, nor break any bone of it: according to all the ordinances of the passover they shall keep it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 13, E'But the man that is clean, and is not in a journey, and forbeareth to keep the passover, even the same soul shall be cut off from among his people: because he brought not the offering of the LORD in his appointed season, that man shall bear his sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 14, E'And if a stranger shall sojourn among you, and will keep the passover unto the LORD; according to the ordinance of the passover, and according to the manner thereof, so shall he do: ye shall have one ordinance, both for the stranger, and for him that was born in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 15, E'And on the day that the tabernacle was reared up the cloud covered the tabernacle, namely, the tent of the testimony: and at even there was upon the tabernacle as it were the appearance of fire, until the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 16, E'So it was alway: the cloud covered it by day, and the appearance of fire by night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 17, E'And when the cloud was taken up from the tabernacle, then after that the children of Israel journeyed: and in the place where the cloud abode, there the children of Israel pitched their tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 18, E'At the commandment of the LORD the children of Israel journeyed, and at the commandment of the LORD they pitched: as long as the cloud abode upon the tabernacle they rested in their tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 19, E'And when the cloud tarried long upon the tabernacle many days, then the children of Israel kept the charge of the LORD, and journeyed not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 20, E'And so it was, when the cloud was a few days upon the tabernacle; according to the commandment of the LORD they abode in their tents, and according to the commandment of the LORD they journeyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 21, E'And so it was, when the cloud abode from even unto the morning, and that the cloud was taken up in the morning, then they journeyed: whether it was by day or by night that the cloud was taken up, they journeyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 22, E'Or whether it were two days, or a month, or a year, that the cloud tarried upon the tabernacle, remaining thereon, the children of Israel abode in their tents, and journeyed not: but when it was taken up, they journeyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 9, 23, E'At the commandment of the LORD they rested in the tents, and at the commandment of the LORD they journeyed: they kept the charge of the LORD, at the commandment of the LORD by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 2, E'Make thee two trumpets of silver; of a whole piece shalt thou make them: that thou mayest use them for the calling of the assembly, and for the journeying of the camps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 3, E'And when they shall blow with them, all the assembly shall assemble themselves to thee at the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 4, E'And if they blow but with one trumpet, then the princes, which are heads of the thousands of Israel, shall gather themselves unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 5, E'When ye blow an alarm, then the camps that lie on the east parts shall go forward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 6, E'When ye blow an alarm the second time, then the camps that lie on the south side shall take their journey: they shall blow an alarm for their journeys.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 7, E'But when the congregation is to be gathered together, ye shall blow, but ye shall not sound an alarm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 8, E'And the sons of Aaron, the priests, shall blow with the trumpets; and they shall be to you for an ordinance for ever throughout your generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 9, E'And if ye go to war in your land against the enemy that oppresseth you, then ye shall blow an alarm with the trumpets; and ye shall be remembered before the LORD your God, and ye shall be saved from your enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 10, E'Also in the day of your gladness, and in your solemn days, and in the beginnings of your months, ye shall blow with the trumpets over your burnt offerings, and over the sacrifices of your peace offerings; that they may be to you for a memorial before your God: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 11, E'And it came to pass on the twentieth day of the second month, in the second year, that the cloud was taken up from off the tabernacle of the testimony.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 12, E'And the children of Israel took their journeys out of the wilderness of Sinai; and the cloud rested in the wilderness of Paran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 13, E'And they first took their journey according to the commandment of the LORD by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 14, E'In the first place went the standard of the camp of the children of Judah according to their armies: and over his host was Nahshon the son of Amminadab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 15, E'And over the host of the tribe of the children of Issachar was Nethaneel the son of Zuar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 16, E'And over the host of the tribe of the children of Zebulun was Eliab the son of Helon.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 17, E'And the tabernacle was taken down; and the sons of Gershon and the sons of Merari set forward, bearing the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 18, E'And the standard of the camp of Reuben set forward according to their armies: and over his host was Elizur the son of Shedeur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 19, E'And over the host of the tribe of the children of Simeon was Shelumiel the son of Zurishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 20, E'And over the host of the tribe of the children of Gad was Eliasaph the son of Deuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 21, E'And the Kohathites set forward, bearing the sanctuary: and the other did set up the tabernacle against they came.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 22, E'And the standard of the camp of the children of Ephraim set forward according to their armies: and over his host was Elishama the son of Ammihud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 23, E'And over the host of the tribe of the children of Manasseh was Gamaliel the son of Pedahzur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 24, E'And over the host of the tribe of the children of Benjamin was Abidan the son of Gideoni.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 25, E'And the standard of the camp of the children of Dan set forward, which was the rereward of all the camps throughout their hosts: and over his host was Ahiezer the son of Ammishaddai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 26, E'And over the host of the tribe of the children of Asher was Pagiel the son of Ocran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 27, E'And over the host of the tribe of the children of Naphtali was Ahira the son of Enan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 28, E'Thus were the journeyings of the children of Israel according to their armies, when they set forward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 29, E'And Moses said unto Hobab, the son of Raguel the Midianite, Moses’ father in law, We are journeying unto the place of which the LORD said, I will give it you: come thou with us, and we will do thee good: for the LORD hath spoken good concerning Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 30, E'And he said unto him, I will not go; but I will depart to mine own land, and to my kindred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 31, E'And he said, Leave us not, I pray thee; forasmuch as thou knowest how we are to encamp in the wilderness, and thou mayest be to us instead of eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 32, E'And it shall be, if thou go with us, yea, it shall be, that what goodness the LORD shall do unto us, the same will we do unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 33, E'And they departed from the mount of the LORD three days’ journey: and the ark of the covenant of the LORD went before them in the three days’ journey, to search out a resting place for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 34, E'And the cloud of the LORD was upon them by day, when they went out of the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 35, E'And it came to pass, when the ark set forward, that Moses said, Rise up, LORD, and let thine enemies be scattered; and let them that hate thee flee before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 10, 36, E'And when it rested, he said, Return, O LORD, unto the many thousands of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 1, E'And when the people complained, it displeased the LORD: and the LORD heard it; and his anger was kindled; and the fire of the LORD burnt among them, and consumed them that were in the uttermost parts of the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 2, E'And the people cried unto Moses; and when Moses prayed unto the LORD, the fire was quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 3, E'And he called the name of the place Taberah: because the fire of the LORD burnt among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 4, E'And the mixt multitude that was among them fell a lusting: and the children of Israel also wept again, and said, Who shall give us flesh to eat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 5, E'We remember the fish, which we did eat in Egypt freely; the cucumbers, and the melons, and the leeks, and the onions, and the garlick:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 6, E'But now our soul is dried away: there is nothing at all, beside this manna, before our eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 7, E'And the manna was as coriander seed, and the colour thereof as the colour of bdellium.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 8, E'And the people went about, and gathered it, and ground it in mills, or beat it in a mortar, and baked it in pans, and made cakes of it: and the taste of it was as the taste of fresh oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 9, E'And when the dew fell upon the camp in the night, the manna fell upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 10, E'Then Moses heard the people weep throughout their families, every man in the door of his tent: and the anger of the LORD was kindled greatly; Moses also was displeased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 11, E'And Moses said unto the LORD, Wherefore hast thou afflicted thy servant? and wherefore have I not found favour in thy sight, that thou layest the burden of all this people upon me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 12, E'Have I conceived all this people? have I begotten them, that thou shouldest say unto me, Carry them in thy bosom, as a nursing father beareth the sucking child, unto the land which thou swarest unto their fathers?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 13, E'Whence should I have flesh to give unto all this people? for they weep unto me, saying, Give us flesh, that we may eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 14, E'I am not able to bear all this people alone, because it is too heavy for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 15, E'And if thou deal thus with me, kill me, I pray thee, out of hand, if I have found favour in thy sight; and let me not see my wretchedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 16, E'And the LORD said unto Moses, Gather unto me seventy men of the elders of Israel, whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 17, E'And I will come down and talk with thee there: and I will take of the spirit which is upon thee, and will put it upon them; and they shall bear the burden of the people with thee, that thou bear it not thyself alone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 18, E'And say thou unto the people, Sanctify yourselves against to morrow, and ye shall eat flesh: for ye have wept in the ears of the LORD, saying, Who shall give us flesh to eat? for it was well with us in Egypt: therefore the LORD will give you flesh, and ye shall eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 19, E'Ye shall not eat one day, nor two days, nor five days, neither ten days, nor twenty days;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 20, E'But even a whole month, until it come out at your nostrils, and it be loathsome unto you: because that ye have despised the LORD which is among you, and have wept before him, saying, Why came we forth out of Egypt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 21, E'And Moses said, The people, among whom I am, are six hundred thousand footmen; and thou hast said, I will give them flesh, that they may eat a whole month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 22, E'Shall the flocks and the herds be slain for them, to suffice them? or shall all the fish of the sea be gathered together for them, to suffice them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 23, E'And the LORD said unto Moses, Is the LORD’s hand waxed short? thou shalt see now whether my word shall come to pass unto thee or not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 24, E'And Moses went out, and told the people the words of the LORD, and gathered the seventy men of the elders of the people, and set them round about the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 25, E'And the LORD came down in a cloud, and spake unto him, and took of the spirit that was upon him, and gave it unto the seventy elders: and it came to pass, that, when the spirit rested upon them, they prophesied, and did not cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 26, E'But there remained two of the men in the camp, the name of the one was Eldad, and the name of the other Medad: and the spirit rested upon them; and they were of them that were written, but went not out unto the tabernacle: and they prophesied in the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 27, E'And there ran a young man, and told Moses, and said, Eldad and Medad do prophesy in the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 28, E'And Joshua the son of Nun, the servant of Moses, one of his young men, answered and said, My lord Moses, forbid them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 29, E'And Moses said unto him, Enviest thou for my sake? would God that all the LORD’s people were prophets, and that the LORD would put his spirit upon them!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 30, E'And Moses gat him into the camp, he and the elders of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 31, E'And there went forth a wind from the LORD, and brought quails from the sea, and let them fall by the camp, as it were a day’s journey on this side, and as it were a day’s journey on the other side, round about the camp, and as it were two cubits high upon the face of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 32, E'And the people stood up all that day, and all that night, and all the next day, and they gathered the quails: he that gathered least gathered ten homers: and they spread them all abroad for themselves round about the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 33, E'And while the flesh was yet between their teeth, ere it was chewed, the wrath of the LORD was kindled against the people, and the LORD smote the people with a very great plague.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 34, E'And he called the name of that place Kibrothhattaavah: because there they buried the people that lusted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 11, 35, E'And the people journeyed from Kibrothhattaavah unto Hazeroth; and abode at Hazeroth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 1, E'And Miriam and Aaron spake against Moses because of the Ethiopian woman whom he had married: for he had married an Ethiopian woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 2, E'And they said, Hath the LORD indeed spoken only by Moses? hath he not spoken also by us? And the LORD heard it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 3, E'(Now the man Moses was very meek, above all the men which were upon the face of the earth.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 4, E'And the LORD spake suddenly unto Moses, and unto Aaron, and unto Miriam, Come out ye three unto the tabernacle of the congregation. And they three came out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 5, E'And the LORD came down in the pillar of the cloud, and stood in the door of the tabernacle, and called Aaron and Miriam: and they both came forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 6, E'And he said, Hear now my words: If there be a prophet among you, I the LORD will make myself known unto him in a vision, and will speak unto him in a dream.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 7, E'My servant Moses is not so, who is faithful in all mine house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 8, E'With him will I speak mouth to mouth, even apparently, and not in dark speeches; and the similitude of the LORD shall he behold: wherefore then were ye not afraid to speak against my servant Moses?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 9, E'And the anger of the LORD was kindled against them; and he departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 10, E'And the cloud departed from off the tabernacle; and, behold, Miriam became leprous, white as snow: and Aaron looked upon Miriam, and, behold, she was leprous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 11, E'And Aaron said unto Moses, Alas, my lord, I beseech thee, lay not the sin upon us, wherein we have done foolishly, and wherein we have sinned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 12, E'Let her not be as one dead, of whom the flesh is half consumed when he cometh out of his mother’s womb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 13, E'And Moses cried unto the LORD, saying, Heal her now, O God, I beseech thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 14, E'And the LORD said unto Moses, If her father had but spit in her face, should she not be ashamed seven days? let her be shut out from the camp seven days, and after that let her be received in again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 15, E'And Miriam was shut out from the camp seven days: and the people journeyed not till Miriam was brought in again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 12, 16, E'And afterward the people removed from Hazeroth, and pitched in the wilderness of Paran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 2, E'Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 3, E'And Moses by the commandment of the LORD sent them from the wilderness of Paran: all those men were heads of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 4, E'And these were their names: of the tribe of Reuben, Shammua the son of Zaccur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 5, E'Of the tribe of Simeon, Shaphat the son of Hori.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 6, E'Of the tribe of Judah, Caleb the son of Jephunneh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 7, E'Of the tribe of Issachar, Igal the son of Joseph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 8, E'Of the tribe of Ephraim, Oshea the son of Nun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 9, E'Of the tribe of Benjamin, Palti the son of Raphu.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 10, E'Of the tribe of Zebulun, Gaddiel the son of Sodi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 11, E'Of the tribe of Joseph, namely, of the tribe of Manasseh, Gaddi the son of Susi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 12, E'Of the tribe of Dan, Ammiel the son of Gemalli.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 13, E'Of the tribe of Asher, Sethur the son of Michael.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 14, E'Of the tribe of Naphtali, Nahbi the son of Vophsi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 15, E'Of the tribe of Gad, Geuel the son of Machi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 16, E'These are the names of the men which Moses sent to spy out the land. And Moses called Oshea the son of Nun Jehoshua.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 17, E'And Moses sent them to spy out the land of Canaan, and said unto them, Get you up this way southward, and go up into the mountain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 18, E'And see the land, what it is; and the people that dwelleth therein, whether they be strong or weak, few or many;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 19, E'And what the land is that they dwell in, whether it be good or bad; and what cities they be that they dwell in, whether in tents, or in strong holds;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 20, E'And what the land is, whether it be fat or lean, whether there be wood therein, or not. And be ye of good courage, and bring of the fruit of the land. Now the time was the time of the firstripe grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 21, E'So they went up, and searched the land from the wilderness of Zin unto Rehob, as men come to Hamath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 22, E'And they ascended by the south, and came unto Hebron; where Ahiman, Sheshai, and Talmai, the children of Anak, were. (Now Hebron was built seven years before Zoan in Egypt.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 23, E'And they came unto the brook of Eshcol, and cut down from thence a branch with one cluster of grapes, and they bare it between two upon a staff; and they brought of the pomegranates, and of the figs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 24, E'The place was called the brook Eshcol, because of the cluster of grapes which the children of Israel cut down from thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 25, E'And they returned from searching of the land after forty days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 26, E'And they went and came to Moses, and to Aaron, and to all the congregation of the children of Israel, unto the wilderness of Paran, to Kadesh; and brought back word unto them, and unto all the congregation, and shewed them the fruit of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 27, E'And they told him, and said, We came unto the land whither thou sentest us, and surely it floweth with milk and honey; and this is the fruit of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 28, E'Nevertheless the people be strong that dwell in the land, and the cities are walled, and very great: and moreover we saw the children of Anak there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 29, E'The Amalekites dwell in the land of the south: and the Hittites, and the Jebusites, and the Amorites, dwell in the mountains: and the Canaanites dwell by the sea, and by the coast of Jordan.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 30, E'And Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 31, E'But the men that went up with him said, We be not able to go up against the people; for they are stronger than we.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 32, E'And they brought up an evil report of the land which they had searched unto the children of Israel, saying, The land, through which we have gone to search it, is a land that eateth up the inhabitants thereof; and all the people that we saw in it are men of a great stature.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 13, 33, E'And there we saw the giants, the sons of Anak, which come of the giants: and we were in our own sight as grasshoppers, and so we were in their sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 1, E'And all the congregation lifted up their voice, and cried; and the people wept that night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 2, E'And all the children of Israel murmured against Moses and against Aaron: and the whole congregation said unto them, Would God that we had died in the land of Egypt! or would God we had died in this wilderness!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 3, E'And wherefore hath the LORD brought us unto this land, to fall by the sword, that our wives and our children should be a prey? were it not better for us to return into Egypt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 4, E'And they said one to another, Let us make a captain, and let us return into Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 5, E'Then Moses and Aaron fell on their faces before all the assembly of the congregation of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 6, E'And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 7, E'And they spake unto all the company of the children of Israel, saying, The land, which we passed through to search it, is an exceeding good land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 8, E'If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 9, E'Only rebel not ye against the LORD, neither fear ye the people of the land; for they are bread for us: their defence is departed from them, and the LORD is with us: fear them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 10, E'But all the congregation bade stone them with stones. And the glory of the LORD appeared in the tabernacle of the congregation before all the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 11, E'And the LORD said unto Moses, How long will this people provoke me? and how long will it be ere they believe me, for all the signs which I have shewed among them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 12, E'I will smite them with the pestilence, and disinherit them, and will make of thee a greater nation and mightier than they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 13, E'And Moses said unto the LORD, Then the Egyptians shall hear it, (for thou broughtest up this people in thy might from among them;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 14, E'And they will tell it to the inhabitants of this land: for they have heard that thou LORD art among this people, that thou LORD art seen face to face, and that thy cloud standeth over them, and that thou goest before them, by day time in a pillar of a cloud, and in a pillar of fire by night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 15, E'Now if thou shalt kill all this people as one man, then the nations which have heard the fame of thee will speak, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 16, E'Because the LORD was not able to bring this people into the land which he sware unto them, therefore he hath slain them in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 17, E'And now, I beseech thee, let the power of my LORD be great, according as thou hast spoken, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 18, E'The LORD is longsuffering, and of great mercy, forgiving iniquity and transgression, and by no means clearing the guilty, visiting the iniquity of the fathers upon the children unto the third and fourth generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 19, E'Pardon, I beseech thee, the iniquity of this people according unto the greatness of thy mercy, and as thou hast forgiven this people, from Egypt even until now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 20, E'And the LORD said, I have pardoned according to thy word:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 21, E'But as truly as I live, all the earth shall be filled with the glory of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 22, E'Because all those men which have seen my glory, and my miracles, which I did in Egypt and in the wilderness, and have tempted me now these ten times, and have not hearkened to my voice;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 23, E'Surely they shall not see the land which I sware unto their fathers, neither shall any of them that provoked me see it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 24, E'But my servant Caleb, because he had another spirit with him, and hath followed me fully, him will I bring into the land whereinto he went; and his seed shall possess it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 25, E'(Now the Amalekites and the Canaanites dwelt in the valley.) Tomorrow turn you, and get you into the wilderness by the way of the Red sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 26, E'And the LORD spake unto Moses and unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 27, E'How long shall I bear with this evil congregation, which murmur against me? I have heard the murmurings of the children of Israel, which they murmur against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 28, E'Say unto them, As truly as I live, saith the LORD, as ye have spoken in mine ears, so will I do to you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 29, E'Your carcases shall fall in this wilderness; and all that were numbered of you, according to your whole number, from twenty years old and upward, which have murmured against me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 30, E'Doubtless ye shall not come into the land, concerning which I sware to make you dwell therein, save Caleb the son of Jephunneh, and Joshua the son of Nun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 31, E'But your little ones, which ye said should be a prey, them will I bring in, and they shall know the land which ye have despised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 32, E'But as for you, your carcases, they shall fall in this wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 33, E'And your children shall wander in the wilderness forty years, and bear your whoredoms, until your carcases be wasted in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 34, E'After the number of the days in which ye searched the land, even forty days, each day for a year, shall ye bear your iniquities, even forty years, and ye shall know my breach of promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 35, E'I the LORD have said, I will surely do it unto all this evil congregation, that are gathered together against me: in this wilderness they shall be consumed, and there they shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 36, E'And the men, which Moses sent to search the land, who returned, and made all the congregation to murmur against him, by bringing up a slander upon the land,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 37, E'Even those men that did bring up the evil report upon the land, died by the plague before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 38, E'But Joshua the son of Nun, and Caleb the son of Jephunneh, which were of the men that went to search the land, lived still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 39, E'And Moses told these sayings unto all the children of Israel: and the people mourned greatly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 40, E'And they rose up early in the morning, and gat them up into the top of the mountain, saying, Lo, we be here, and will go up unto the place which the LORD hath promised: for we have sinned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 41, E'And Moses said, Wherefore now do ye transgress the commandment of the LORD? but it shall not prosper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 42, E'Go not up, for the LORD is not among you; that ye be not smitten before your enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 43, E'For the Amalekites and the Canaanites are there before you, and ye shall fall by the sword: because ye are turned away from the LORD, therefore the LORD will not be with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 44, E'But they presumed to go up unto the hill top: nevertheless the ark of the covenant of the LORD, and Moses, departed not out of the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 14, 45, E'Then the Amalekites came down, and the Canaanites which dwelt in that hill, and smote them, and discomfited them, even unto Hormah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 2, E'Speak unto the children of Israel, and say unto them, When ye be come into the land of your habitations, which I give unto you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 3, E'And will make an offering by fire unto the LORD, a burnt offering, or a sacrifice in performing a vow, or in a freewill offering, or in your solemn feasts, to make a sweet savour unto the LORD, of the herd, or of the flock:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 4, E'Then shall he that offereth his offering unto the LORD bring a meat offering of a tenth deal of flour mingled with the fourth part of an hin of oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 5, E'And the fourth part of an hin of wine for a drink offering shalt thou prepare with the burnt offering or sacrifice, for one lamb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 6, E'Or for a ram, thou shalt prepare for a meat offering two tenth deals of flour mingled with the third part of an hin of oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 7, E'And for a drink offering thou shalt offer the third part of an hin of wine, for a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 8, E'And when thou preparest a bullock for a burnt offering, or for a sacrifice in performing a vow, or peace offerings unto the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 9, E'Then shall he bring with a bullock a meat offering of three tenth deals of flour mingled with half an hin of oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 10, E'And thou shalt bring for a drink offering half an hin of wine, for an offering made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 11, E'Thus shall it be done for one bullock, or for one ram, or for a lamb, or a kid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 12, E'According to the number that ye shall prepare, so shall ye do to every one according to their number.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 13, E'All that are born of the country shall do these things after this manner, in offering an offering made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 14, E'And if a stranger sojourn with you, or whosoever be among you in your generations, and will offer an offering made by fire, of a sweet savour unto the LORD; as ye do, so he shall do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 15, E'One ordinance shall be both for you of the congregation, and also for the stranger that sojourneth with you, an ordinance for ever in your generations: as ye are, so shall the stranger be before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 16, E'One law and one manner shall be for you, and for the stranger that sojourneth with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 17, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 18, E'Speak unto the children of Israel, and say unto them, When ye come into the land whither I bring you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 19, E'Then it shall be, that, when ye eat of the bread of the land, ye shall offer up an heave offering unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 20, E'Ye shall offer up a cake of the first of your dough for an heave offering: as ye do the heave offering of the threshingfloor, so shall ye heave it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 21, E'Of the first of your dough ye shall give unto the LORD an heave offering in your generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 22, E'And if ye have erred, and not observed all these commandments, which the LORD hath spoken unto Moses,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 23, E'Even all that the LORD hath commanded you by the hand of Moses, from the day that the LORD commanded Moses, and henceforward among your generations;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 24, E'Then it shall be, if ought be committed by ignorance without the knowledge of the congregation, that all the congregation shall offer one young bullock for a burnt offering, for a sweet savour unto the LORD, with his meat offering, and his drink offering, according to the manner, and one kid of the goats for a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 25, E'And the priest shall make an atonement for all the congregation of the children of Israel, and it shall be forgiven them; for it is ignorance: and they shall bring their offering, a sacrifice made by fire unto the LORD, and their sin offering before the LORD, for their ignorance:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 26, E'And it shall be forgiven all the congregation of the children of Israel, and the stranger that sojourneth among them; seeing all the people were in ignorance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 27, E'And if any soul sin through ignorance, then he shall bring a she goat of the first year for a sin offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 28, E'And the priest shall make an atonement for the soul that sinneth ignorantly, when he sinneth by ignorance before the LORD, to make an atonement for him; and it shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 29, E'Ye shall have one law for him that sinneth through ignorance, both for him that is born among the children of Israel, and for the stranger that sojourneth among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 30, E'But the soul that doeth ought presumptuously, whether he be born in the land, or a stranger, the same reproacheth the LORD; and that soul shall be cut off from among his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 31, E'Because he hath despised the word of the LORD, and hath broken his commandment, that soul shall utterly be cut off; his iniquity shall be upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 32, E'And while the children of Israel were in the wilderness, they found a man that gathered sticks upon the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 33, E'And they that found him gathering sticks brought him unto Moses and Aaron, and unto all the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 34, E'And they put him in ward, because it was not declared what should be done to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 35, E'And the LORD said unto Moses, The man shall be surely put to death: all the congregation shall stone him with stones without the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 36, E'And all the congregation brought him without the camp, and stoned him with stones, and he died; as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 37, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 38, E'Speak unto the children of Israel, and bid them that they make them fringes in the borders of their garments throughout their generations, and that they put upon the fringe of the borders a ribband of blue:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 39, E'And it shall be unto you for a fringe, that ye may look upon it, and remember all the commandments of the LORD, and do them; and that ye seek not after your own heart and your own eyes, after which ye use to go a whoring:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 40, E'That ye may remember, and do all my commandments, and be holy unto your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 15, 41, E'I am the LORD your God, which brought you out of the land of Egypt, to be your God: I am the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 1, E'Now Korah, the son of Izhar, the son of Kohath, the son of Levi, and Dathan and Abiram, the sons of Eliab, and On, the son of Peleth, sons of Reuben, took men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 2, E'And they rose up before Moses, with certain of the children of Israel, two hundred and fifty princes of the assembly, famous in the congregation, men of renown:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 3, E'And they gathered themselves together against Moses and against Aaron, and said unto them, Ye take too much upon you, seeing all the congregation are holy, every one of them, and the LORD is among them: wherefore then lift ye up yourselves above the congregation of the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 4, E'And when Moses heard it, he fell upon his face:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 5, E'And he spake unto Korah and unto all his company, saying, Even to morrow the LORD will shew who are his, and who is holy; and will cause him to come near unto him: even him whom he hath chosen will he cause to come near unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 6, E'This do; Take you censers, Korah, and all his company;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 7, E'And put fire therein, and put incense in them before the LORD to morrow: and it shall be that the man whom the LORD doth choose, he shall be holy: ye take too much upon you, ye sons of Levi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 8, E'And Moses said unto Korah, Hear, I pray you, ye sons of Levi:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 9, E'Seemeth it but a small thing unto you, that the God of Israel hath separated you from the congregation of Israel, to bring you near to himself to do the service of the tabernacle of the LORD, and to stand before the congregation to minister unto them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 10, E'And he hath brought thee near to him, and all thy brethren the sons of Levi with thee: and seek ye the priesthood also?')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 11, E'For which cause both thou and all thy company are gathered together against the LORD: and what is Aaron, that ye murmur against him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 12, E'And Moses sent to call Dathan and Abiram, the sons of Eliab: which said, We will not come up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 13, E'Is it a small thing that thou hast brought us up out of a land that floweth with milk and honey, to kill us in the wilderness, except thou make thyself altogether a prince over us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 14, E'Moreover thou hast not brought us into a land that floweth with milk and honey, or given us inheritance of fields and vineyards: wilt thou put out the eyes of these men? we will not come up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 15, E'And Moses was very wroth, and said unto the LORD, Respect not thou their offering: I have not taken one ass from them, neither have I hurt one of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 16, E'And Moses said unto Korah, Be thou and all thy company before the LORD, thou, and they, and Aaron, to morrow:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 17, E'And take every man his censer, and put incense in them, and bring ye before the LORD every man his censer, two hundred and fifty censers; thou also, and Aaron, each of you his censer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 18, E'And they took every man his censer, and put fire in them, and laid incense thereon, and stood in the door of the tabernacle of the congregation with Moses and Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 19, E'And Korah gathered all the congregation against them unto the door of the tabernacle of the congregation: and the glory of the LORD appeared unto all the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 20, E'And the LORD spake unto Moses and unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 21, E'Separate yourselves from among this congregation, that I may consume them in a moment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 22, E'And they fell upon their faces, and said, O God, the God of the spirits of all flesh, shall one man sin, and wilt thou be wroth with all the congregation?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 23, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 24, E'Speak unto the congregation, saying, Get you up from about the tabernacle of Korah, Dathan, and Abiram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 25, E'And Moses rose up and went unto Dathan and Abiram; and the elders of Israel followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 26, E'And he spake unto the congregation, saying, Depart, I pray you, from the tents of these wicked men, and touch nothing of theirs, lest ye be consumed in all their sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 27, E'So they gat up from the tabernacle of Korah, Dathan, and Abiram, on every side: and Dathan and Abiram came out, and stood in the door of their tents, and their wives, and their sons, and their little children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 28, E'And Moses said, Hereby ye shall know that the LORD hath sent me to do all these works; for I have not done them of mine own mind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 29, E'If these men die the common death of all men, or if they be visited after the visitation of all men; then the LORD hath not sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 30, E'But if the LORD make a new thing, and the earth open her mouth, and swallow them up, with all that appertain unto them, and they go down quick into the pit; then ye shall understand that these men have provoked the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 31, E'And it came to pass, as he had made an end of speaking all these words, that the ground clave asunder that was under them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 32, E'And the earth opened her mouth, and swallowed them up, and their houses, and all the men that appertained unto Korah, and all their goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 33, E'They, and all that appertained to them, went down alive into the pit, and the earth closed upon them: and they perished from among the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 34, E'And all Israel that were round about them fled at the cry of them: for they said, Lest the earth swallow us up also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 35, E'And there came out a fire from the LORD, and consumed the two hundred and fifty men that offered incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 36, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 37, E'Speak unto Eleazar the son of Aaron the priest, that he take up the censers out of the burning, and scatter thou the fire yonder; for they are hallowed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 38, E'The censers of these sinners against their own souls, let them make them broad plates for a covering of the altar: for they offered them before the LORD, therefore they are hallowed: and they shall be a sign unto the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 39, E'And Eleazar the priest took the brasen censers, wherewith they that were burnt had offered; and they were made broad plates for a covering of the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 40, E'To be a memorial unto the children of Israel, that no stranger, which is not of the seed of Aaron, come near to offer incense before the LORD; that he be not as Korah, and as his company: as the LORD said to him by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 41, E'But on the morrow all the congregation of the children of Israel murmured against Moses and against Aaron, saying, Ye have killed the people of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 42, E'And it came to pass, when the congregation was gathered against Moses and against Aaron, that they looked toward the tabernacle of the congregation: and, behold, the cloud covered it, and the glory of the LORD appeared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 43, E'And Moses and Aaron came before the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 44, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 45, E'Get you up from among this congregation, that I may consume them as in a moment. And they fell upon their faces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 46, E'And Moses said unto Aaron, Take a censer, and put fire therein from off the altar, and put on incense, and go quickly unto the congregation, and make an atonement for them: for there is wrath gone out from the LORD; the plague is begun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 47, E'And Aaron took as Moses commanded, and ran into the midst of the congregation; and, behold, the plague was begun among the people: and he put on incense, and made an atonement for the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 48, E'And he stood between the dead and the living; and the plague was stayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 49, E'Now they that died in the plague were fourteen thousand and seven hundred, beside them that died about the matter of Korah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 16, 50, E'And Aaron returned unto Moses unto the door of the tabernacle of the congregation: and the plague was stayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 2, E'Speak unto the children of Israel, and take of every one of them a rod according to the house of their fathers, of all their princes according to the house of their fathers twelve rods: write thou every man’s name upon his rod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 3, E'And thou shalt write Aaron’s name upon the rod of Levi: for one rod shall be for the head of the house of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 4, E'And thou shalt lay them up in the tabernacle of the congregation before the testimony, where I will meet with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 5, E'And it shall come to pass, that the man’s rod, whom I shall choose, shall blossom: and I will make to cease from me the murmurings of the children of Israel, whereby they murmur against you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 6, E'And Moses spake unto the children of Israel, and every one of their princes gave him a rod apiece, for each prince one, according to their fathers’ houses, even twelve rods: and the rod of Aaron was among their rods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 7, E'And Moses laid up the rods before the LORD in the tabernacle of witness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 8, E'And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 9, E'And Moses brought out all the rods from before the LORD unto all the children of Israel: and they looked, and took every man his rod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 10, E'And the LORD said unto Moses, Bring Aaron’s rod again before the testimony, to be kept for a token against the rebels; and thou shalt quite take away their murmurings from me, that they die not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 11, E'And Moses did so: as the LORD commanded him, so did he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 12, E'And the children of Israel spake unto Moses, saying, Behold, we die, we perish, we all perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 17, 13, E'Whosoever cometh any thing near unto the tabernacle of the LORD shall die: shall we be consumed with dying?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 1, E'And the LORD said unto Aaron, Thou and thy sons and thy father’s house with thee shall bear the iniquity of the sanctuary: and thou and thy sons with thee shall bear the iniquity of your priesthood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 2, E'And thy brethren also of the tribe of Levi, the tribe of thy father, bring thou with thee, that they may be joined unto thee, and minister unto thee: but thou and thy sons with thee shall minister before the tabernacle of witness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 3, E'And they shall keep thy charge, and the charge of all the tabernacle: only they shall not come nigh the vessels of the sanctuary and the altar, that neither they, nor ye also, die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 4, E'And they shall be joined unto thee, and keep the charge of the tabernacle of the congregation, for all the service of the tabernacle: and a stranger shall not come nigh unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 5, E'And ye shall keep the charge of the sanctuary, and the charge of the altar: that there be no wrath any more upon the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 6, E'And I, behold, I have taken your brethren the Levites from among the children of Israel: to you they are given as a gift for the LORD, to do the service of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 7, E'Therefore thou and thy sons with thee shall keep your priest’s office for everything of the altar, and within the vail; and ye shall serve: I have given your priest’s office unto you as a service of gift: and the stranger that cometh nigh shall be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 8, E'And the LORD spake unto Aaron, Behold, I also have given thee the charge of mine heave offerings of all the hallowed things of the children of Israel; unto thee have I given them by reason of the anointing, and to thy sons, by an ordinance for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 9, E'This shall be thine of the most holy things, reserved from the fire: every oblation of theirs, every meat offering of theirs, and every sin offering of theirs, and every trespass offering of theirs which they shall render unto me, shall be most holy for thee and for thy sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 10, E'In the most holy place shalt thou eat it; every male shall eat it: it shall be holy unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 11, E'And this is thine; the heave offering of their gift, with all the wave offerings of the children of Israel: I have given them unto thee, and to thy sons and to thy daughters with thee, by a statute for ever: every one that is clean in thy house shall eat of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 12, E'All the best of the oil, and all the best of the wine, and of the wheat, the firstfruits of them which they shall offer unto the LORD, them have I given thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 13, E'And whatsoever is first ripe in the land, which they shall bring unto the LORD, shall be thine; every one that is clean in thine house shall eat of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 14, E'Every thing devoted in Israel shall be thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 15, E'Every thing that openeth the matrix in all flesh, which they bring unto the LORD, whether it be of men or beasts, shall be thine: nevertheless the firstborn of man shalt thou surely redeem, and the firstling of unclean beasts shalt thou redeem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 16, E'And those that are to be redeemed from a month old shalt thou redeem, according to thine estimation, for the money of five shekels, after the shekel of the sanctuary, which is twenty gerahs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 17, E'But the firstling of a cow, or the firstling of a sheep, or the firstling of a goat, thou shalt not redeem; they are holy: thou shalt sprinkle their blood upon the altar, and shalt burn their fat for an offering made by fire, for a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 18, E'And the flesh of them shall be thine, as the wave breast and as the right shoulder are thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 19, E'All the heave offerings of the holy things, which the children of Israel offer unto the LORD, have I given thee, and thy sons and thy daughters with thee, by a statute for ever: it is a covenant of salt for ever before the LORD unto thee and to thy seed with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 20, E'And the LORD spake unto Aaron, Thou shalt have no inheritance in their land, neither shalt thou have any part among them: I am thy part and thine inheritance among the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 21, E'And, behold, I have given the children of Levi all the tenth in Israel for an inheritance, for their service which they serve, even the service of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 22, E'Neither must the children of Israel henceforth come nigh the tabernacle of the congregation, lest they bear sin, and die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 23, E'But the Levites shall do the service of the tabernacle of the congregation, and they shall bear their iniquity: it shall be a statute for ever throughout your generations, that among the children of Israel they have no inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 24, E'But the tithes of the children of Israel, which they offer as an heave offering unto the LORD, I have given to the Levites to inherit: therefore I have said unto them, Among the children of Israel they shall have no inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 25, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 26, E'Thus speak unto the Levites, and say unto them, When ye take of the children of Israel the tithes which I have given you from them for your inheritance, then ye shall offer up an heave offering of it for the LORD, even a tenth part of the tithe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 27, E'And this your heave offering shall be reckoned unto you, as though it were the corn of the threshingfloor, and as the fulness of the winepress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 28, E'Thus ye also shall offer an heave offering unto the LORD of all your tithes, which ye receive of the children of Israel; and ye shall give thereof the LORD’s heave offering to Aaron the priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 29, E'Out of all your gifts ye shall offer every heave offering of the LORD, of all the best thereof, even the hallowed part thereof out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 30, E'Therefore thou shalt say unto them, When ye have heaved the best thereof from it, then it shall be counted unto the Levites as the increase of the threshingfloor, and as the increase of the winepress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 31, E'And ye shall eat it in every place, ye and your households: for it is your reward for your service in the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 18, 32, E'And ye shall bear no sin by reason of it, when ye have heaved from it the best of it: neither shall ye pollute the holy things of the children of Israel, lest ye die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 1, E'And the LORD spake unto Moses and unto Aaron, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 2, E'This is the ordinance of the law which the LORD hath commanded, saying, Speak unto the children of Israel, that they bring thee a red heifer without spot, wherein is no blemish, and upon which never came yoke:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 3, E'And ye shall give her unto Eleazar the priest, that he may bring her forth without the camp, and one shall slay her before his face:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 4, E'And Eleazar the priest shall take of her blood with his finger, and sprinkle of her blood directly before the tabernacle of the congregation seven times:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 5, E'And one shall burn the heifer in his sight; her skin, and her flesh, and her blood, with her dung, shall he burn:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 6, E'And the priest shall take cedar wood, and hyssop, and scarlet, and cast it into the midst of the burning of the heifer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 7, E'Then the priest shall wash his clothes, and he shall bathe his flesh in water, and afterward he shall come into the camp, and the priest shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 8, E'And he that burneth her shall wash his clothes in water, and bathe his flesh in water, and shall be unclean until the even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 9, E'And a man that is clean shall gather up the ashes of the heifer, and lay them up without the camp in a clean place, and it shall be kept for the congregation of the children of Israel for a water of separation: it is a purification for sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 10, E'And he that gathereth the ashes of the heifer shall wash his clothes, and be unclean until the even: and it shall be unto the children of Israel, and unto the stranger that sojourneth among them, for a statute for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 11, E'He that toucheth the dead body of any man shall be unclean seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 12, E'He shall purify himself with it on the third day, and on the seventh day he shall be clean: but if he purify not himself the third day, then the seventh day he shall not be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 13, E'Whosoever toucheth the dead body of any man that is dead, and purifieth not himself, defileth the tabernacle of the LORD; and that soul shall be cut off from Israel: because the water of separation was not sprinkled upon him, he shall be unclean; his uncleanness is yet upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 14, E'This is the law, when a man dieth in a tent: all that come into the tent, and all that is in the tent, shall be unclean seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 15, E'And every open vessel, which hath no covering bound upon it, is unclean.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 16, E'And whosoever toucheth one that is slain with a sword in the open fields, or a dead body, or a bone of a man, or a grave, shall be unclean seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 17, E'And for an unclean person they shall take of the ashes of the burnt heifer of purification for sin, and running water shall be put thereto in a vessel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 18, E'And a clean person shall take hyssop, and dip it in the water, and sprinkle it upon the tent, and upon all the vessels, and upon the persons that were there, and upon him that touched a bone, or one slain, or one dead, or a grave:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 19, E'And the clean person shall sprinkle upon the unclean on the third day, and on the seventh day: and on the seventh day he shall purify himself, and wash his clothes, and bathe himself in water, and shall be clean at even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 20, E'But the man that shall be unclean, and shall not purify himself, that soul shall be cut off from among the congregation, because he hath defiled the sanctuary of the LORD: the water of separation hath not been sprinkled upon him; he is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 21, E'And it shall be a perpetual statute unto them, that he that sprinkleth the water of separation shall wash his clothes; and he that toucheth the water of separation shall be unclean until even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 19, 22, E'And whatsoever the unclean person toucheth shall be unclean; and the soul that toucheth it shall be unclean until even.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 1, E'Then came the children of Israel, even the whole congregation, into the desert of Zin in the first month: and the people abode in Kadesh; and Miriam died there, and was buried there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 2, E'And there was no water for the congregation: and they gathered themselves together against Moses and against Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 3, E'And the people chode with Moses, and spake, saying, Would God that we had died when our brethren died before the LORD!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 4, E'And why have ye brought up the congregation of the LORD into this wilderness, that we and our cattle should die there?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 5, E'And wherefore have ye made us to come up out of Egypt, to bring us in unto this evil place? it is no place of seed, or of figs, or of vines, or of pomegranates; neither is there any water to drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 6, E'And Moses and Aaron went from the presence of the assembly unto the door of the tabernacle of the congregation, and they fell upon their faces: and the glory of the LORD appeared unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 7, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 8, E'Take the rod, and gather thou the assembly together, thou, and Aaron thy brother, and speak ye unto the rock before their eyes; and it shall give forth his water, and thou shalt bring forth to them water out of the rock: so thou shalt give the congregation and their beasts drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 9, E'And Moses took the rod from before the LORD, as he commanded him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 10, E'And Moses and Aaron gathered the congregation together before the rock, and he said unto them, Hear now, ye rebels; must we fetch you water out of this rock?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 11, E'And Moses lifted up his hand, and with his rod he smote the rock twice: and the water came out abundantly, and the congregation drank, and their beasts also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 12, E'And the LORD spake unto Moses and Aaron, Because ye believed me not, to sanctify me in the eyes of the children of Israel, therefore ye shall not bring this congregation into the land which I have given them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 13, E'This is the water of Meribah; because the children of Israel strove with the LORD, and he was sanctified in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 14, E'And Moses sent messengers from Kadesh unto the king of Edom, Thus saith thy brother Israel, Thou knowest all the travail that hath befallen us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 15, E'How our fathers went down into Egypt, and we have dwelt in Egypt a long time; and the Egyptians vexed us, and our fathers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 16, E'And when we cried unto the LORD, he heard our voice, and sent an angel, and hath brought us forth out of Egypt: and, behold, we are in Kadesh, a city in the uttermost of thy border:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 17, E'Let us pass, I pray thee, through thy country: we will not pass through the fields, or through the vineyards, neither will we drink of the water of the wells: we will go by the king’s high way, we will not turn to the right hand nor to the left, until we have passed thy borders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 18, E'And Edom said unto him, Thou shalt not pass by me, lest I come out against thee with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 19, E'And the children of Israel said unto him, We will go by the high way: and if I and my cattle drink of thy water, then I will pay for it: I will only, without doing anything else, go through on my feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 20, E'And he said, Thou shalt not go through. And Edom came out against him with much people, and with a strong hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 21, E'Thus Edom refused to give Israel passage through his border: wherefore Israel turned away from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 22, E'And the children of Israel, even the whole congregation, journeyed from Kadesh, and came unto mount Hor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 23, E'And the LORD spake unto Moses and Aaron in mount Hor, by the coast of the land of Edom, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 24, E'Aaron shall be gathered unto his people: for he shall not enter into the land which I have given unto the children of Israel, because ye rebelled against my word at the water of Meribah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 25, E'Take Aaron and Eleazar his son, and bring them up unto mount Hor:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 26, E'And strip Aaron of his garments, and put them upon Eleazar his son: and Aaron shall be gathered unto his people, and shall die there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 27, E'And Moses did as the LORD commanded: and they went up into mount Hor in the sight of all the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 28, E'And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 20, 29, E'And when all the congregation saw that Aaron was dead, they mourned for Aaron thirty days, even all the house of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 1, E'And when king Arad the Canaanite, which dwelt in the south, heard tell that Israel came by the way of the spies; then he fought against Israel, and took some of them prisoners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 2, E'And Israel vowed a vow unto the LORD, and said, If thou wilt indeed deliver this people into my hand, then I will utterly destroy their cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 3, E'And the LORD hearkened to the voice of Israel, and delivered up the Canaanites; and they utterly destroyed them and their cities: and he called the name of the place Hormah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 4, E'And they journeyed from mount Hor by the way of the Red sea, to compass the land of Edom: and the soul of the people was much discouraged because of the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 5, E'And the people spake against God, and against Moses, Wherefore have ye brought us up out of Egypt to die in the wilderness? for there is no bread, neither is there any water; and our soul loatheth this light bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 6, E'And the LORD sent fiery serpents among the people, and they bit the people; and much people of Israel died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 7, E'Therefore the people came to Moses, and said, We have sinned, for we have spoken against the LORD, and against thee; pray unto the LORD, that he take away the serpents from us. And Moses prayed for the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 8, E'And the LORD said unto Moses, Make thee a fiery serpent, and set it upon a pole: and it shall come to pass, that every one that is bitten, when he looketh upon it, shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 9, E'And Moses made a serpent of brass, and put it upon a pole, and it came to pass, that if a serpent had bitten any man, when he beheld the serpent of brass, he lived.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 10, E'And the children of Israel set forward, and pitched in Oboth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 11, E'And they journeyed from Oboth, and pitched at Ijeabarim, in the wilderness which is before Moab, toward the sunrising.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 12, E'From thence they removed, and pitched in the valley of Zared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 13, E'From thence they removed, and pitched on the other side of Arnon, which is in the wilderness that cometh out of the coasts of the Amorites: for Arnon is the border of Moab, between Moab and the Amorites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 14, E'Wherefore it is said in the book of the wars of the LORD, What he did in the Red sea, and in the brooks of Arnon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 15, E'And at the stream of the brooks that goeth down to the dwelling of Ar, and lieth upon the border of Moab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 16, E'And from thence they went to Beer: that is the well whereof the LORD spake unto Moses, Gather the people together, and I will give them water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 17, E'Then Israel sang this song, Spring up, O well; sing ye unto it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 18, E'The princes digged the well, the nobles of the people digged it, by the direction of the lawgiver, with their staves. And from the wilderness they went to Mattanah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 19, E'And from Mattanah to Nahaliel: and from Nahaliel to Bamoth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 20, E'And from Bamoth in the valley, that is in the country of Moab, to the top of Pisgah, which looketh toward Jeshimon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 21, E'And Israel sent messengers unto Sihon king of the Amorites, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 22, E'Let me pass through thy land: we will not turn into the fields, or into the vineyards; we will not drink of the waters of the well: but we will go along by the king’s high way, until we be past thy borders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 23, E'And Sihon would not suffer Israel to pass through his border: but Sihon gathered all his people together, and went out against Israel into the wilderness: and he came to Jahaz, and fought against Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 24, E'And Israel smote him with the edge of the sword, and possessed his land from Arnon unto Jabbok, even unto the children of Ammon: for the border of the children of Ammon was strong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 25, E'And Israel took all these cities: and Israel dwelt in all the cities of the Amorites, in Heshbon, and in all the villages thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 26, E'For Heshbon was the city of Sihon the king of the Amorites, who had fought against the former king of Moab, and taken all his land out of his hand, even unto Arnon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 27, E'Wherefore they that speak in proverbs say, Come into Heshbon, let the city of Sihon be built and prepared:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 28, E'For there is a fire gone out of Heshbon, a flame from the city of Sihon: it hath consumed Ar of Moab, and the lords of the high places of Arnon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 29, E'Woe to thee, Moab! thou art undone, O people of Chemosh: he hath given his sons that escaped, and his daughters, into captivity unto Sihon king of the Amorites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 30, E'We have shot at them; Heshbon is perished even unto Dibon, and we have laid them waste even unto Nophah, which reacheth unto Medeba.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 31, E'Thus Israel dwelt in the land of the Amorites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 32, E'And Moses sent to spy out Jaazer, and they took the villages thereof, and drove out the Amorites that were there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 33, E'And they turned and went up by the way of Bashan: and Og the king of Bashan went out against them, he, and all his people, to the battle at Edrei.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 34, E'And the LORD said unto Moses, Fear him not: for I have delivered him into thy hand, and all his people, and his land; and thou shalt do to him as thou didst unto Sihon king of the Amorites, which dwelt at Heshbon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 21, 35, E'So they smote him, and his sons, and all his people, until there was none left him alive: and they possessed his land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 1, E'And the children of Israel set forward, and pitched in the plains of Moab on this side Jordan by Jericho.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 2, E'And Balak the son of Zippor saw all that Israel had done to the Amorites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 3, E'And Moab was sore afraid of the people, because they were many: and Moab was distressed because of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 4, E'And Moab said unto the elders of Midian, Now shall this company lick up all that are round about us, as the ox licketh up the grass of the field. And Balak the son of Zippor was king of the Moabites at that time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 5, E'He sent messengers therefore unto Balaam the son of Beor to Pethor, which is by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 6, E'Come now therefore, I pray thee, curse me this people; for they are too mighty for me: peradventure I shall prevail, that we may smite them, and that I may drive them out of the land: for I wot that he whom thou blessest is blessed, and he whom thou cursest is cursed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 7, E'And the elders of Moab and the elders of Midian departed with the rewards of divination in their hand; and they came unto Balaam, and spake unto him the words of Balak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 8, E'And he said unto them, Lodge here this night, and I will bring you word again, as the LORD shall speak unto me: and the princes of Moab abode with Balaam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 9, E'And God came unto Balaam, and said, What men are these with thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 10, E'And Balaam said unto God, Balak the son of Zippor, king of Moab, hath sent unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 11, E'Behold, there is a people come out of Egypt, which covereth the face of the earth: come now, curse me them; peradventure I shall be able to overcome them, and drive them out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 12, E'And God said unto Balaam, Thou shalt not go with them; thou shalt not curse the people: for they are blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 13, E'And Balaam rose up in the morning, and said unto the princes of Balak, Get you into your land: for the LORD refuseth to give me leave to go with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 14, E'And the princes of Moab rose up, and they went unto Balak, and said, Balaam refuseth to come with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 15, E'And Balak sent yet again princes, more, and more honourable than they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 16, E'And they came to Balaam, and said to him, Thus saith Balak the son of Zippor, Let nothing, I pray thee, hinder thee from coming unto me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 17, E'For I will promote thee unto very great honour, and I will do whatsoever thou sayest unto me: come therefore, I pray thee, curse me this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 18, E'And Balaam answered and said unto the servants of Balak, If Balak would give me his house full of silver and gold, I cannot go beyond the word of the LORD my God, to do less or more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 19, E'Now therefore, I pray you, tarry ye also here this night, that I may know what the LORD will say unto me more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 20, E'And God came unto Balaam at night, and said unto him, If the men come to call thee, rise up, and go with them; but yet the word which I shall say unto thee, that shalt thou do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 21, E'And Balaam rose up in the morning, and saddled his ass, and went with the princes of Moab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 22, E'And God’s anger was kindled because he went: and the angel of the LORD stood in the way for an adversary against him. Now he was riding upon his ass, and his two servants were with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 23, E'And the ass saw the angel of the LORD standing in the way, and his sword drawn in his hand: and the ass turned aside out of the way, and went into the field: and Balaam smote the ass, to turn her into the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 24, E'But the angel of the LORD stood in a path of the vineyards, a wall being on this side, and a wall on that side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 25, E'And when the ass saw the angel of the LORD, she thrust herself unto the wall, and crushed Balaam’s foot against the wall: and he smote her again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 26, E'And the angel of the LORD went further, and stood in a narrow place, where was no way to turn either to the right hand or to the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 27, E'And when the ass saw the angel of the LORD, she fell down under Balaam: and Balaam’s anger was kindled, and he smote the ass with a staff.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 28, E'And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 29, E'And Balaam said unto the ass, Because thou hast mocked me: I would there were a sword in mine hand, for now would I kill thee.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 30, E'And the ass said unto Balaam, Am not I thine ass, upon which thou hast ridden ever since I was thine unto this day? was I ever wont to do so unto thee? And he said, Nay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 31, E'Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 32, E'And the angel of the LORD said unto him, Wherefore hast thou smitten thine ass these three times? behold, I went out to withstand thee, because thy way is perverse before me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 33, E'And the ass saw me, and turned from me these three times: unless she had turned from me, surely now also I had slain thee, and saved her alive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 34, E'And Balaam said unto the angel of the LORD, I have sinned; for I knew not that thou stoodest in the way against me: now therefore, if it displease thee, I will get me back again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 35, E'And the angel of the LORD said unto Balaam, Go with the men: but only the word that I shall speak unto thee, that thou shalt speak. So Balaam went with the princes of Balak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 36, E'And when Balak heard that Balaam was come, he went out to meet him unto a city of Moab, which is in the border of Arnon, which is in the utmost coast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 37, E'And Balak said unto Balaam, Did I not earnestly send unto thee to call thee? wherefore camest thou not unto me? am I not able indeed to promote thee to honour?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 38, E'And Balaam said unto Balak, Lo, I am come unto thee: have I now any power at all to say any thing? the word that God putteth in my mouth, that shall I speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 39, E'And Balaam went with Balak, and they came unto Kirjathhuzoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 40, E'And Balak offered oxen and sheep, and sent to Balaam, and to the princes that were with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 22, 41, E'And it came to pass on the morrow, that Balak took Balaam, and brought him up into the high places of Baal, that thence he might see the utmost part of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 1, E'And Balaam said unto Balak, Build me here seven altars, and prepare me here seven oxen and seven rams.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 2, E'And Balak did as Balaam had spoken; and Balak and Balaam offered on every altar a bullock and a ram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 3, E'And Balaam said unto Balak, Stand by thy burnt offering, and I will go: peradventure the LORD will come to meet me: and whatsoever he sheweth me I will tell thee. And he went to an high place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 4, E'And God met Balaam: and he said unto him, I have prepared seven altars, and I have offered upon every altar a bullock and a ram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 5, E'And the LORD put a word in Balaam’s mouth, and said, Return unto Balak, and thus thou shalt speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 6, E'And he returned unto him, and, lo, he stood by his burnt sacrifice, he, and all the princes of Moab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 7, E'And he took up his parable, and said, Balak the king of Moab hath brought me from Aram, out of the mountains of the east, saying, Come, curse me Jacob, and come, defy Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 8, E'How shall I curse, whom God hath not cursed? or how shall I defy, whom the LORD hath not defied?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 9, E'For from the top of the rocks I see him, and from the hills I behold him: lo, the people shall dwell alone, and shall not be reckoned among the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 10, E'Who can count the dust of Jacob, and the number of the fourth part of Israel? Let me die the death of the righteous, and let my last end be like his!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 11, E'And Balak said unto Balaam, What hast thou done unto me? I took thee to curse mine enemies, and, behold, thou hast blessed them altogether.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 12, E'And he answered and said, Must I not take heed to speak that which the LORD hath put in my mouth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 13, E'And Balak said unto him, Come, I pray thee, with me unto another place, from whence thou mayest see them: thou shalt see but the utmost part of them, and shalt not see them all: and curse me them from thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 14, E'And he brought him into the field of Zophim, to the top of Pisgah, and built seven altars, and offered a bullock and a ram on every altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 15, E'And he said unto Balak, Stand here by thy burnt offering, while I meet the LORD yonder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 16, E'And the LORD met Balaam, and put a word in his mouth, and said, Go again unto Balak, and say thus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 17, E'And when he came to him, behold, he stood by his burnt offering, and the princes of Moab with him. And Balak said unto him, What hath the LORD spoken?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 18, E'And he took up his parable, and said, Rise up, Balak, and hear; hearken unto me, thou son of Zippor:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 19, E'God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 20, E'Behold, I have received commandment to bless: and he hath blessed; and I cannot reverse it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 21, E'He hath not beheld iniquity in Jacob, neither hath he seen perverseness in Israel: the LORD his God is with him, and the shout of a king is among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 22, E'God brought them out of Egypt; he hath as it were the strength of an unicorn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 23, E'Surely there is no enchantment against Jacob, neither is there any divination against Israel: according to this time it shall be said of Jacob and of Israel, What hath God wrought!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 24, E'Behold, the people shall rise up as a great lion, and lift up himself as a young lion: he shall not lie down until he eat of the prey, and drink the blood of the slain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 25, E'And Balak said unto Balaam, Neither curse them at all, nor bless them at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 26, E'But Balaam answered and said unto Balak, Told not I thee, saying, All that the LORD speaketh, that I must do?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 27, E'And Balak said unto Balaam, Come, I pray thee, I will bring thee unto another place; peradventure it will please God that thou mayest curse me them from thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 28, E'And Balak brought Balaam unto the top of Peor, that looketh toward Jeshimon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 29, E'And Balaam said unto Balak, Build me here seven altars, and prepare me here seven bullocks and seven rams.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 23, 30, E'And Balak did as Balaam had said, and offered a bullock and a ram on every altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 1, E'And when Balaam saw that it pleased the LORD to bless Israel, he went not, as at other times, to seek for enchantments, but he set his face toward the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 2, E'And Balaam lifted up his eyes, and he saw Israel abiding in his tents according to their tribes; and the spirit of God came upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 3, E'And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 4, E'He hath said, which heard the words of God, which saw the vision of the Almighty, falling into a trance, but having his eyes open:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 5, E'How goodly are thy tents, O Jacob, and thy tabernacles, O Israel!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 6, E'As the valleys are they spread forth, as gardens by the river’s side, as the trees of lign aloes which the LORD hath planted, and as cedar trees beside the waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 7, E'He shall pour the water out of his buckets, and his seed shall be in many waters, and his king shall be higher than Agag, and his kingdom shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 8, E'God brought him forth out of Egypt; he hath as it were the strength of an unicorn: he shall eat up the nations his enemies, and shall break their bones, and pierce them through with his arrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 9, E'He couched, he lay down as a lion, and as a great lion: who shall stir him up? Blessed is he that blesseth thee, and cursed is he that curseth thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 10, E'And Balak’s anger was kindled against Balaam, and he smote his hands together: and Balak said unto Balaam, I called thee to curse mine enemies, and, behold, thou hast altogether blessed them these three times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 11, E'Therefore now flee thou to thy place: I thought to promote thee unto great honour; but, lo, the LORD hath kept thee back from honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 12, E'And Balaam said unto Balak, Spake I not also to thy messengers which thou sentest unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 13, E'If Balak would give me his house full of silver and gold, I cannot go beyond the commandment of the LORD, to do either good or bad of mine own mind; but what the LORD saith, that will I speak?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 14, E'And now, behold, I go unto my people: come therefore, and I will advertise thee what this people shall do to thy people in the latter days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 15, E'And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 16, E'He hath said, which heard the words of God, and knew the knowledge of the most High, which saw the vision of the Almighty, falling into a trance, but having his eyes open:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 17, E'I shall see him, but not now: I shall behold him, but not nigh: there shall come a Star out of Jacob, and a Sceptre shall rise out of Israel, and shall smite the corners of Moab, and destroy all the children of Sheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 18, E'And Edom shall be a possession, Seir also shall be a possession for his enemies; and Israel shall do valiantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 19, E'Out of Jacob shall come he that shall have dominion, and shall destroy him that remaineth of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 20, E'And when he looked on Amalek, he took up his parable, and said, Amalek was the first of the nations; but his latter end shall be that he perish for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 21, E'And he looked on the Kenites, and took up his parable, and said, Strong is thy dwellingplace, and thou puttest thy nest in a rock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 22, E'Nevertheless the Kenite shall be wasted, until Asshur shall carry thee away captive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 23, E'And he took up his parable, and said, Alas, who shall live when God doeth this!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 24, E'And ships shall come from the coast of Chittim, and shall afflict Asshur, and shall afflict Eber, and he also shall perish for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 24, 25, E'And Balaam rose up, and went and returned to his place: and Balak also went his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 1, E'And Israel abode in Shittim, and the people began to commit whoredom with the daughters of Moab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 2, E'And they called the people unto the sacrifices of their gods: and the people did eat, and bowed down to their gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 3, E'And Israel joined himself unto Baalpeor: and the anger of the LORD was kindled against Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 4, E'And the LORD said unto Moses, Take all the heads of the people, and hang them up before the LORD against the sun, that the fierce anger of the LORD may be turned away from Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 5, E'And Moses said unto the judges of Israel, Slay ye every one his men that were joined unto Baalpeor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 6, E'And, behold, one of the children of Israel came and brought unto his brethren a Midianitish woman in the sight of Moses, and in the sight of all the congregation of the children of Israel, who were weeping before the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 7, E'And when Phinehas, the son of Eleazar, the son of Aaron the priest, saw it, he rose up from among the congregation, and took a javelin in his hand;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 8, E'And he went after the man of Israel into the tent, and thrust both of them through, the man of Israel, and the woman through her belly. So the plague was stayed from the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 9, E'And those that died in the plague were twenty and four thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 10, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 11, E'Phinehas, the son of Eleazar, the son of Aaron the priest, hath turned my wrath away from the children of Israel, while he was zealous for my sake among them, that I consumed not the children of Israel in my jealousy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 12, E'Wherefore say, Behold, I give unto him my covenant of peace:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 13, E'And he shall have it, and his seed after him, even the covenant of an everlasting priesthood; because he was zealous for his God, and made an atonement for the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 14, E'Now the name of the Israelite that was slain, even that was slain with the Midianitish woman, was Zimri, the son of Salu, a prince of a chief house among the Simeonites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 15, E'And the name of the Midianitish woman that was slain was Cozbi, the daughter of Zur; he was head over a people, and of a chief house in Midian.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 16, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 17, E'Vex the Midianites, and smite them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 25, 18, E'For they vex you with their wiles, wherewith they have beguiled you in the matter of Peor, and in the matter of Cozbi, the daughter of a prince of Midian, their sister, which was slain in the day of the plague for Peor’s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 1, E'And it came to pass after the plague, that the LORD spake unto Moses and unto Eleazar the son of Aaron the priest, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 2, E'Take the sum of all the congregation of the children of Israel, from twenty years old and upward, throughout their fathers’ house, all that are able to go to war in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 3, E'And Moses and Eleazar the priest spake with them in the plains of Moab by Jordan near Jericho, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 4, E'Take the sum of the people, from twenty years old and upward; as the LORD commanded Moses and the children of Israel, which went forth out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 5, E'Reuben, the eldest son of Israel: the children of Reuben; Hanoch, of whom cometh the family of the Hanochites: of Pallu, the family of the Palluites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 6, E'Of Hezron, the family of the Hezronites: of Carmi, the family of the Carmites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 7, E'These are the families of the Reubenites: and they that were numbered of them were forty and three thousand and seven hundred and thirty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 8, E'And the sons of Pallu; Eliab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 9, E'And the sons of Eliab; Nemuel, and Dathan, and Abiram. This is that Dathan and Abiram, which were famous in the congregation, who strove against Moses and against Aaron in the company of Korah, when they strove against the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 10, E'And the earth opened her mouth, and swallowed them up together with Korah, when that company died, what time the fire devoured two hundred and fifty men: and they became a sign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 11, E'Notwithstanding the children of Korah died not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 12, E'The sons of Simeon after their families: of Nemuel, the family of the Nemuelites: of Jamin, the family of the Jaminites: of Jachin, the family of the Jachinites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 13, E'Of Zerah, the family of the Zarhites: of Shaul, the family of the Shaulites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 14, E'These are the families of the Simeonites, twenty and two thousand and two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 15, E'The children of Gad after their families: of Zephon, the family of the Zephonites: of Haggi, the family of the Haggites: of Shuni, the family of the Shunites:')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 16, E'Of Ozni, the family of the Oznites: of Eri, the family of the Erites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 17, E'Of Arod, the family of the Arodites: of Areli, the family of the Arelites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 18, E'These are the families of the children of Gad according to those that were numbered of them, forty thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 19, E'The sons of Judah were Er and Onan: and Er and Onan died in the land of Canaan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 20, E'And the sons of Judah after their families were; of Shelah, the family of the Shelanites: of Pharez, the family of the Pharzites: of Zerah, the family of the Zarhites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 21, E'And the sons of Pharez were; of Hezron, the family of the Hezronites: of Hamul, the family of the Hamulites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 22, E'These are the families of Judah according to those that were numbered of them, threescore and sixteen thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 23, E'Of the sons of Issachar after their families: of Tola, the family of the Tolaites: of Pua, the family of the Punites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 24, E'Of Jashub, the family of the Jashubites: of Shimron, the family of the Shimronites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 25, E'These are the families of Issachar according to those that were numbered of them, threescore and four thousand and three hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 26, E'Of the sons of Zebulun after their families: of Sered, the family of the Sardites: of Elon, the family of the Elonites: of Jahleel, the family of the Jahleelites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 27, E'These are the families of the Zebulunites according to those that were numbered of them, threescore thousand and five hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 28, E'The sons of Joseph after their families were Manasseh and Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 29, E'Of the sons of Manasseh: of Machir, the family of the Machirites: and Machir begat Gilead: of Gilead come the family of the Gileadites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 30, E'These are the sons of Gilead: of Jeezer, the family of the Jeezerites: of Helek, the family of the Helekites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 31, E'And of Asriel, the family of the Asrielites: and of Shechem, the family of the Shechemites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 32, E'And of Shemida, the family of the Shemidaites: and of Hepher, the family of the Hepherites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 33, E'And Zelophehad the son of Hepher had no sons, but daughters: and the names of the daughters of Zelophehad were Mahlah, and Noah, Hoglah, Milcah, and Tirzah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 34, E'These are the families of Manasseh, and those that were numbered of them, fifty and two thousand and seven hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 35, E'These are the sons of Ephraim after their families: of Shuthelah, the family of the Shuthalhites: of Becher, the family of the Bachrites: of Tahan, the family of the Tahanites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 36, E'And these are the sons of Shuthelah: of Eran, the family of the Eranites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 37, E'These are the families of the sons of Ephraim according to those that were numbered of them, thirty and two thousand and five hundred. These are the sons of Joseph after their families.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 38, E'The sons of Benjamin after their families: of Bela, the family of the Belaites: of Ashbel, the family of the Ashbelites: of Ahiram, the family of the Ahiramites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 39, E'Of Shupham, the family of the Shuphamites: of Hupham, the family of the Huphamites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 40, E'And the sons of Bela were Ard and Naaman: of Ard, the family of the Ardites: and of Naaman, the family of the Naamites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 41, E'These are the sons of Benjamin after their families: and they that were numbered of them were forty and five thousand and six hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 42, E'These are the sons of Dan after their families: of Shuham, the family of the Shuhamites. These are the families of Dan after their families.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 43, E'All the families of the Shuhamites, according to those that were numbered of them, were threescore and four thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 44, E'Of the children of Asher after their families: of Jimna, the family of the Jimnites: of Jesui, the family of the Jesuites: of Beriah, the family of the Beriites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 45, E'Of the sons of Beriah: of Heber, the family of the Heberites: of Malchiel, the family of the Malchielites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 46, E'And the name of the daughter of Asher was Sarah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 47, E'These are the families of the sons of Asher according to those that were numbered of them; who were fifty and three thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 48, E'Of the sons of Naphtali after their families: of Jahzeel, the family of the Jahzeelites: of Guni, the family of the Gunites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 49, E'Of Jezer, the family of the Jezerites: of Shillem, the family of the Shillemites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 50, E'These are the families of Naphtali according to their families: and they that were numbered of them were forty and five thousand and four hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 51, E'These were the numbered of the children of Israel, six hundred thousand and a thousand seven hundred and thirty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 52, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 53, E'Unto these the land shall be divided for an inheritance according to the number of names.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 54, E'To many thou shalt give the more inheritance, and to few thou shalt give the less inheritance: to every one shall his inheritance be given according to those that were numbered of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 55, E'Notwithstanding the land shall be divided by lot: according to the names of the tribes of their fathers they shall inherit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 56, E'According to the lot shall the possession thereof be divided between many and few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 57, E'And these are they that were numbered of the Levites after their families: of Gershon, the family of the Gershonites: of Kohath, the family of the Kohathites: of Merari, the family of the Merarites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 58, E'These are the families of the Levites: the family of the Libnites, the family of the Hebronites, the family of the Mahlites, the family of the Mushites, the family of the Korathites. And Kohath begat Amram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 59, E'And the name of Amram’s wife was Jochebed, the daughter of Levi, whom her mother bare to Levi in Egypt: and she bare unto Amram Aaron and Moses, and Miriam their sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 60, E'And unto Aaron was born Nadab, and Abihu, Eleazar, and Ithamar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 61, E'And Nadab and Abihu died, when they offered strange fire before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 62, E'And those that were numbered of them were twenty and three thousand, all males from a month old and upward: for they were not numbered among the children of Israel, because there was no inheritance given them among the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 63, E'These are they that were numbered by Moses and Eleazar the priest, who numbered the children of Israel in the plains of Moab by Jordan near Jericho.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 64, E'But among these there was not a man of them whom Moses and Aaron the priest numbered, when they numbered the children of Israel in the wilderness of Sinai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 26, 65, E'For the LORD had said of them, They shall surely die in the wilderness. And there was not left a man of them, save Caleb the son of Jephunneh, and Joshua the son of Nun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 1, E'Then came the daughters of Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, of the families of Manasseh the son of Joseph: and these are the names of his daughters; Mahlah, Noah, and Hoglah, and Milcah, and Tirzah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 2, E'And they stood before Moses, and before Eleazar the priest, and before the princes and all the congregation, by the door of the tabernacle of the congregation, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 3, E'Our father died in the wilderness, and he was not in the company of them that gathered themselves together against the LORD in the company of Korah; but died in his own sin, and had no sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 4, E'Why should the name of our father be done away from among his family, because he hath no son? Give unto us therefore a possession among the brethren of our father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 5, E'And Moses brought their cause before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 6, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 7, E'The daughters of Zelophehad speak right: thou shalt surely give them a possession of an inheritance among their father’s brethren; and thou shalt cause the inheritance of their father to pass unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 8, E'And thou shalt speak unto the children of Israel, saying, If a man die, and have no son, then ye shall cause his inheritance to pass unto his daughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 9, E'And if he have no daughter, then ye shall give his inheritance unto his brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 10, E'And if he have no brethren, then ye shall give his inheritance unto his father’s brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 11, E'And if his father have no brethren, then ye shall give his inheritance unto his kinsman that is next to him of his family, and he shall possess it: and it shall be unto the children of Israel a statute of judgment, as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 12, E'And the LORD said unto Moses, Get thee up into this mount Abarim, and see the land which I have given unto the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 13, E'And when thou hast seen it, thou also shalt be gathered unto thy people, as Aaron thy brother was gathered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 14, E'For ye rebelled against my commandment in the desert of Zin, in the strife of the congregation, to sanctify me at the water before their eyes: that is the water of Meribah in Kadesh in the wilderness of Zin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 15, E'And Moses spake unto the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 16, E'Let the LORD, the God of the spirits of all flesh, set a man over the congregation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 17, E'Which may go out before them, and which may go in before them, and which may lead them out, and which may bring them in; that the congregation of the LORD be not as sheep which have no shepherd.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 18, E'And the LORD said unto Moses, Take thee Joshua the son of Nun, a man in whom is the spirit, and lay thine hand upon him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 19, E'And set him before Eleazar the priest, and before all the congregation; and give him a charge in their sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 20, E'And thou shalt put some of thine honour upon him, that all the congregation of the children of Israel may be obedient.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 21, E'And he shall stand before Eleazar the priest, who shall ask counsel for him after the judgment of Urim before the LORD: at his word shall they go out, and at his word they shall come in, both he, and all the children of Israel with him, even all the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 22, E'And Moses did as the LORD commanded him: and he took Joshua, and set him before Eleazar the priest, and before all the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 27, 23, E'And he laid his hands upon him, and gave him a charge, as the LORD commanded by the hand of Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 2, E'Command the children of Israel, and say unto them, My offering, and my bread for my sacrifices made by fire, for a sweet savour unto me, shall ye observe to offer unto me in their due season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 3, E'And thou shalt say unto them, This is the offering made by fire which ye shall offer unto the LORD; two lambs of the first year without spot day by day, for a continual burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 4, E'The one lamb shalt thou offer in the morning, and the other lamb shalt thou offer at even;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 5, E'And a tenth part of an ephah of flour for a meat offering, mingled with the fourth part of an hin of beaten oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 6, E'It is a continual burnt offering, which was ordained in mount Sinai for a sweet savour, a sacrifice made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 7, E'And the drink offering thereof shall be the fourth part of an hin for the one lamb: in the holy place shalt thou cause the strong wine to be poured unto the LORD for a drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 8, E'And the other lamb shalt thou offer at even: as the meat offering of the morning, and as the drink offering thereof, thou shalt offer it, a sacrifice made by fire, of a sweet savour unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 9, E'And on the sabbath day two lambs of the first year without spot, and two tenth deals of flour for a meat offering, mingled with oil, and the drink offering thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 10, E'This is the burnt offering of every sabbath, beside the continual burnt offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 11, E'And in the beginnings of your months ye shall offer a burnt offering unto the LORD; two young bullocks, and one ram, seven lambs of the first year without spot;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 12, E'And three tenth deals of flour for a meat offering, mingled with oil, for one bullock; and two tenth deals of flour for a meat offering, mingled with oil, for one ram;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 13, E'And a several tenth deal of flour mingled with oil for a meat offering unto one lamb; for a burnt offering of a sweet savour, a sacrifice made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 14, E'And their drink offerings shall be half an hin of wine unto a bullock, and the third part of an hin unto a ram, and a fourth part of an hin unto a lamb: this is the burnt offering of every month throughout the months of the year.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 15, E'And one kid of the goats for a sin offering unto the LORD shall be offered, beside the continual burnt offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 16, E'And in the fourteenth day of the first month is the passover of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 17, E'And in the fifteenth day of this month is the feast: seven days shall unleavened bread be eaten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 18, E'In the first day shall be an holy convocation; ye shall do no manner of servile work therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 19, E'But ye shall offer a sacrifice made by fire for a burnt offering unto the LORD; two young bullocks, and one ram, and seven lambs of the first year: they shall be unto you without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 20, E'And their meat offering shall be of flour mingled with oil: three tenth deals shall ye offer for a bullock, and two tenth deals for a ram;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 21, E'A several tenth deal shalt thou offer for every lamb, throughout the seven lambs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 22, E'And one goat for a sin offering, to make an atonement for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 23, E'Ye shall offer these beside the burnt offering in the morning, which is for a continual burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 24, E'After this manner ye shall offer daily, throughout the seven days, the meat of the sacrifice made by fire, of a sweet savour unto the LORD: it shall be offered beside the continual burnt offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 25, E'And on the seventh day ye shall have an holy convocation; ye shall do no servile work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 26, E'Also in the day of the firstfruits, when ye bring a new meat offering unto the LORD, after your weeks be out, ye shall have an holy convocation; ye shall do no servile work:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 27, E'But ye shall offer the burnt offering for a sweet savour unto the LORD; two young bullocks, one ram, seven lambs of the first year;')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 28, E'And their meat offering of flour mingled with oil, three tenth deals unto one bullock, two tenth deals unto one ram,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 29, E'A several tenth deal unto one lamb, throughout the seven lambs;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 30, E'And one kid of the goats, to make an atonement for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 28, 31, E'Ye shall offer them beside the continual burnt offering, and his meat offering, (they shall be unto you without blemish) and their drink offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 1, E'And in the seventh month, on the first day of the month, ye shall have an holy convocation; ye shall do no servile work: it is a day of blowing the trumpets unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 2, E'And ye shall offer a burnt offering for a sweet savour unto the LORD; one young bullock, one ram, and seven lambs of the first year without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 3, E'And their meat offering shall be of flour mingled with oil, three tenth deals for a bullock, and two tenth deals for a ram,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 4, E'And one tenth deal for one lamb, throughout the seven lambs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 5, E'And one kid of the goats for a sin offering, to make an atonement for you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 6, E'Beside the burnt offering of the month, and his meat offering, and the daily burnt offering, and his meat offering, and their drink offerings, according unto their manner, for a sweet savour, a sacrifice made by fire unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 7, E'And ye shall have on the tenth day of this seventh month an holy convocation; and ye shall afflict your souls: ye shall not do any work therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 8, E'But ye shall offer a burnt offering unto the LORD for a sweet savour; one young bullock, one ram, and seven lambs of the first year; they shall be unto you without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 9, E'And their meat offering shall be of flour mingled with oil, three tenth deals to a bullock, and two tenth deals to one ram,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 10, E'A several tenth deal for one lamb, throughout the seven lambs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 11, E'One kid of the goats for a sin offering; beside the sin offering of atonement, and the continual burnt offering, and the meat offering of it, and their drink offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 12, E'And on the fifteenth day of the seventh month ye shall have an holy convocation; ye shall do no servile work, and ye shall keep a feast unto the LORD seven days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 13, E'And ye shall offer a burnt offering, a sacrifice made by fire, of a sweet savour unto the LORD; thirteen young bullocks, two rams, and fourteen lambs of the first year; they shall be without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 14, E'And their meat offering shall be of flour mingled with oil, three tenth deals unto every bullock of the thirteen bullocks, two tenth deals to each ram of the two rams,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 15, E'And a several tenth deal to each lamb of the fourteen lambs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 16, E'And one kid of the goats for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 17, E'And on the second day ye shall offer twelve young bullocks, two rams, fourteen lambs of the first year without spot:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 18, E'And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 19, E'And one kid of the goats for a sin offering; beside the continual burnt offering, and the meat offering thereof, and their drink offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 20, E'And on the third day eleven bullocks, two rams, fourteen lambs of the first year without blemish;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 21, E'And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 22, E'And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 23, E'And on the fourth day ten bullocks, two rams, and fourteen lambs of the first year without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 24, E'Their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 25, E'And one kid of the goats for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 26, E'And on the fifth day nine bullocks, two rams, and fourteen lambs of the first year without spot:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 27, E'And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 28, E'And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 29, E'And on the sixth day eight bullocks, two rams, and fourteen lambs of the first year without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 30, E'And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 31, E'And one goat for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 32, E'And on the seventh day seven bullocks, two rams, and fourteen lambs of the first year without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 33, E'And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 34, E'And one goat for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 35, E'On the eighth day ye shall have a solemn assembly: ye shall do no servile work therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 36, E'But ye shall offer a burnt offering, a sacrifice made by fire, of a sweet savour unto the LORD: one bullock, one ram, seven lambs of the first year without blemish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 37, E'Their meat offering and their drink offerings for the bullock, for the ram, and for the lambs, shall be according to their number, after the manner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 38, E'And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 39, E'These things ye shall do unto the LORD in your set feasts, beside your vows, and your freewill offerings, for your burnt offerings, and for your meat offerings, and for your drink offerings, and for your peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 29, 40, E'And Moses told the children of Israel according to all that the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 1, E'And Moses spake unto the heads of the tribes concerning the children of Israel, saying, This is the thing which the LORD hath commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 2, E'If a man vow a vow unto the LORD, or swear an oath to bind his soul with a bond; he shall not break his word, he shall do according to all that proceedeth out of his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 3, E'If a woman also vow a vow unto the LORD, and bind herself by a bond, being in her father’s house in her youth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 4, E'And her father hear her vow, and her bond wherewith she hath bound her soul, and her father shall hold his peace at her: then all her vows shall stand, and every bond wherewith she hath bound her soul shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 5, E'But if her father disallow her in the day that he heareth; not any of her vows, or of her bonds wherewith she hath bound her soul, shall stand: and the LORD shall forgive her, because her father disallowed her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 6, E'And if she had at all an husband, when she vowed, or uttered ought out of her lips, wherewith she bound her soul;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 7, E'And her husband heard it, and held his peace at her in the day that he heard it: then her vows shall stand, and her bonds wherewith she bound her soul shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 8, E'But if her husband disallowed her on the day that he heard it; then he shall make her vow which she vowed, and that which she uttered with her lips, wherewith she bound her soul, of none effect: and the LORD shall forgive her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 9, E'But every vow of a widow, and of her that is divorced, wherewith they have bound their souls, shall stand against her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 10, E'And if she vowed in her husband’s house, or bound her soul by a bond with an oath;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 11, E'And her husband heard it, and held his peace at her, and disallowed her not: then all her vows shall stand, and every bond wherewith she bound her soul shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 12, E'But if her husband hath utterly made them void on the day he heard them; then whatsoever proceeded out of her lips concerning her vows, or concerning the bond of her soul, shall not stand: her husband hath made them void; and the LORD shall forgive her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 13, E'Every vow, and every binding oath to afflict the soul, her husband may establish it, or her husband may make it void.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 14, E'But if her husband altogether hold his peace at her from day to day; then he establisheth all her vows, or all her bonds, which are upon her: he confirmeth them, because he held his peace at her in the day that he heard them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 15, E'But if he shall any ways make them void after that he hath heard them; then he shall bear her iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 30, 16, E'These are the statutes, which the LORD commanded Moses, between a man and his wife, between the father and his daughter, being yet in her youth in her father’s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 1, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 2, E'Avenge the children of Israel of the Midianites: afterward shalt thou be gathered unto thy people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 3, E'And Moses spake unto the people, saying, Arm some of yourselves unto the war, and let them go against the Midianites, and avenge the LORD of Midian.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 4, E'Of every tribe a thousand, throughout all the tribes of Israel, shall ye send to the war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 5, E'So there were delivered out of the thousands of Israel, a thousand of every tribe, twelve thousand armed for war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 6, E'And Moses sent them to the war, a thousand of every tribe, them and Phinehas the son of Eleazar the priest, to the war, with the holy instruments, and the trumpets to blow in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 7, E'And they warred against the Midianites, as the LORD commanded Moses; and they slew all the males.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 8, E'And they slew the kings of Midian, beside the rest of them that were slain; namely, Evi, and Rekem, and Zur, and Hur, and Reba, five kings of Midian: Balaam also the son of Beor they slew with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 9, E'And the children of Israel took all the women of Midian captives, and their little ones, and took the spoil of all their cattle, and all their flocks, and all their goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 10, E'And they burnt all their cities wherein they dwelt, and all their goodly castles, with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 11, E'And they took all the spoil, and all the prey, both of men and of beasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 12, E'And they brought the captives, and the prey, and the spoil, unto Moses, and Eleazar the priest, and unto the congregation of the children of Israel, unto the camp at the plains of Moab, which are by Jordan near Jericho.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 13, E'And Moses, and Eleazar the priest, and all the princes of the congregation, went forth to meet them without the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 14, E'And Moses was wroth with the officers of the host, with the captains over thousands, and captains over hundreds, which came from the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 15, E'And Moses said unto them, Have ye saved all the women alive?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 16, E'Behold, these caused the children of Israel, through the counsel of Balaam, to commit trespass against the LORD in the matter of Peor, and there was a plague among the congregation of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 17, E'Now therefore kill every male among the little ones, and kill every woman that hath known man by lying with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 18, E'But all the women children, that have not known a man by lying with him, keep alive for yourselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 19, E'And do ye abide without the camp seven days: whosoever hath killed any person, and whosoever hath touched any slain, purify both yourselves and your captives on the third day, and on the seventh day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 20, E'And purify all your raiment, and all that is made of skins, and all work of goats’ hair, and all things made of wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 21, E'And Eleazar the priest said unto the men of war which went to the battle, This is the ordinance of the law which the LORD commanded Moses;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 22, E'Only the gold, and the silver, the brass, the iron, the tin, and the lead,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 23, E'Every thing that may abide the fire, ye shall make it go through the fire, and it shall be clean: nevertheless it shall be purified with the water of separation: and all that abideth not the fire ye shall make go through the water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 24, E'And ye shall wash your clothes on the seventh day, and ye shall be clean, and afterward ye shall come into the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 25, E'And the LORD spake unto Moses, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 26, E'Take the sum of the prey that was taken, both of man and of beast, thou, and Eleazar the priest, and the chief fathers of the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 27, E'And divide the prey into two parts; between them that took the war upon them, who went out to battle, and between all the congregation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 28, E'And levy a tribute unto the Lord of the men of war which went out to battle: one soul of five hundred, both of the persons, and of the beeves, and of the asses, and of the sheep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 29, E'Take it of their half, and give it unto Eleazar the priest, for an heave offering of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 30, E'And of the children of Israel’s half, thou shalt take one portion of fifty, of the persons, of the beeves, of the asses, and of the flocks, of all manner of beasts, and give them unto the Levites, which keep the charge of the tabernacle of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 31, E'And Moses and Eleazar the priest did as the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 32, E'And the booty, being the rest of the prey which the men of war had caught, was six hundred thousand and seventy thousand and five thousand sheep,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 33, E'And threescore and twelve thousand beeves,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 34, E'And threescore and one thousand asses,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 35, E'And thirty and two thousand persons in all, of women that had not known man by lying with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 36, E'And the half, which was the portion of them that went out to war, was in number three hundred thousand and seven and thirty thousand and five hundred sheep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 37, E'And the LORD’s tribute of the sheep was six hundred and threescore and fifteen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 38, E'And the beeves were thirty and six thousand; of which the LORD’s tribute was threescore and twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 39, E'And the asses were thirty thousand and five hundred; of which the LORD’s tribute was threescore and one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '090f4893-cf2f-4c9d-8aa7-900aa50f33b5', 31, 40, E'And the persons were sixteen thousand; of which the LORD’s tribute was thirty and two persons.')
) AS v(chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Numbers') b
ON CONFLICT DO NOTHING;

